window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s7-953","number":953,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"لماذا انتقل من خطاب موسى إلى قومه: ﴿وأمر قومك يأخذوا بأحسنها﴾؟","answer":"لم يكن العطاء لموسى وحده؛ فانتقل الخطاب من تكليفه بالأخذ إلى تكليفه بتبليغ قومه وحملهم على العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص513–514، تحت «فائدة التفريق بين أخذ موسى عليه السلام وأخذ قومه»","url":""}]},{"id":"s7-954","number":954,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما دلالة جزم ﴿يأخذوا﴾ في ﴿وأمر قومك يأخذوا بأحسنها﴾؟","answer":"جزم الفعل في جواب الأمر ﴿وأمر﴾، وفيه تصوير امتثالهم كأنه حاصل عند صدور أمر موسى إليهم. فيقوي طلب التسليم لأمر الله والعمل بما جاء في الألواح.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص514–515، تحت «فائدة جزم الفعل ﴿يأخذوا﴾»","url":""}]},{"id":"s7-955","number":955,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"كيف يُفهم قوله تعالى: ﴿يأخذوا بأحسنها﴾، وهل في الألواح ما ليس حسنًا؟","answer":"قد تأتي صيغة التفضيل للمبالغة في الحسن، فتكون الألواح كلها حسنة ويطلب الأخذ بجميعها. وقد تحمل على التفاضل بين وجوه العمل، كالعفو مع جواز الاقتصاص؛ فلا يلزم أن في شريعة الله حكمًا قبيحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص515–516، تحت «وجوه التعبير بلفظ ﴿بأحسنها﴾»","url":""}]},{"id":"s7-956","number":956,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما علة التعبير بقوله: ﴿سأريكم دار الفاسقين﴾؟","answer":"الوعيد يجعل مصير الفاسقين منظورًا كأنه دار تُرى، ليعتبروا بعاقبة من خرج عن أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص516–517، تحت «علة التعبير بقوله: ﴿سأريكم دار الفاسقين﴾»","url":""}]},{"id":"s7-957","number":957,"surah":7,"verses":[145],"references":[{"surah":7,"verses":[145]}],"verseLabel":"الأعراف: 145","question":"ما المراد بـ﴿دار الفاسقين﴾: مصر أم مساكن الهالكين أم جهنم؟","answer":"والسياق يحتمل العبرة بمصير الفاسقين في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص517–518، تحت «علة التعبير بقوله: ﴿سأريكم دار الفاسقين﴾»","url":""}]},{"id":"s7-958","number":958,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿سأصرف عن آياتي﴾، وما معنى صرف المتكبرين عنها؟","answer":"الصرف مجازاة لهم على الاستكبار: يحرمون فهم الآيات والاعتبار بها، أو يصرفون عن إبطالها، لا أنهم يمنعون قسرًا من إيمان أرادوه بإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص524–525، تحت «دلالة الفعل ﴿سأصرف﴾، على حماية الله لآياته وأوليائه»","url":""}]},{"id":"s7-959","number":959,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لم اختلف الضمير في ﴿عن آياتي﴾ و﴿كذبوا بآياتنا﴾ في الآية نفسها؟","answer":"افتتحت الآية بضمير المتكلم المفرد، وختمت بضمير التعظيم. ويبين المصدر مناسبة الافتتاح لما قبله من ﴿سأريكم﴾، ومناسبة الختام لما بعده من ﴿والذين كذبوا بآياتنا﴾؛ فينتظم التعبير مع السياق من جهتيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص534–535، تحت «علة التباين في نسبة الآيات إليه تعالى»","url":""}]},{"id":"s7-960","number":960,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا وُصفوا بـ﴿الذين يتكبرون﴾ بالمضارع؟","answer":"المضارع في ﴿يتكبرون﴾ يصور تجدد تكبرهم واستمراره حتى صار دأبًا يصدهم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص527، تحت «سر التعبير عن التكبر بصيغة المضارع»","url":""}]},{"id":"s7-961","number":961,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا قُيّد تكبرهم بـ﴿في الأرض﴾؟","answer":"يبرز القيد ضآلة موطنهم؛ فهم متكبرون في بقعة من الأرض ليست شيئًا يعتد به أمام سعة الخلق. فذكر الأرض يشهر تكبرهم ويفضح غرورهم مع صغر شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص527–528، تحت «بلاغة الإطناب، بزيادة: ﴿في الأرض﴾»","url":""}]},{"id":"s7-962","number":962,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿بغير الحق﴾، وهل يكون التكبر بحق؟","answer":"القيد كاشف لواقع تكبرهم؛ فالكبرياء الحق لله وحده، ولا يكون تكبر البشر بحق. وقيل للاحتراز من إظهار العزة على أهل الباطل دون بطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص528، تحت «وجوه التعبير بقوله: ﴿بغير الحق﴾»","url":""}]},{"id":"s7-963","number":963,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا كرر الشرط: ﴿وإن يروا كل آية... وإن يروا سبيل الرشد... وإن يروا سبيل الغي﴾؟","answer":"تكرار الشرط يفصل وجوه عنادهم: لا يؤمنون بالدليل مهما ظهر، ويرفضون طريق الرشد، ويتخذون طريق الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص531–532، تحت «سر تكرار ألفاظ ﴿الرؤية﴾، و﴿السبيل﴾، و﴿الاتخاذ﴾»","url":""}]},{"id":"s7-964","number":964,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما دلالة ﴿كل آية﴾ في وصف عناد المتكبرين؟","answer":"يفسر المصدر ﴿كل﴾ هنا بالتكثير واستغراق ما يرونه من الآيات، مبالغة في شدة عنادهم؛ مهما كثرت الدلائل أمامهم لا يؤمنون. فلا يشترط أن يشاهدوا جميع آيات الله التي لا تحصى حتى يصدق الوصف عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص529، تحت «دلالة لفظ ﴿كل﴾ بين المجاز والحقيقة»","url":""}]},{"id":"s7-965","number":965,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما أثر التعبير بالأفعال في ﴿وإن يروا كل آية لا يؤمنوا بها﴾؟","answer":"تصور الجملة الفعلية تجدد جحودهم وعدم إيمانهم بتجدد رؤيتهم الآيات. فعند كل دليل يتكرر منهم الموقف نفسه، ويتصل ذلك بوصفهم بالتكبر قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص528–529، تحت «دلالة الوصل، والتعبير بالجملة الفعلية»","url":""}]},{"id":"s7-966","number":966,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا قوبل ﴿سبيل الرشد﴾ بـ﴿سبيل الغي﴾؟","answer":"الرشد إصابة طريق الحق والصلاح، والغي العدول عنه إلى الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص522–523، تحت «شرح المفردات: ﴿الرشد﴾ و﴿الغي﴾»","url":""}]},{"id":"s7-967","number":967,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير في قوله تعالى في الطريقين: ﴿لا يتخذوه سبيلًا﴾ و﴿يتخذوه سبيلًا﴾؟","answer":"الاتخاذ فعل قصد واختيار؛ فهم لا يكتفون بترك الرشد بل يرفضون جعله طريقًا، ويعمدون إلى الغي فيجعلونه طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص529–530، تحت «بلاغة الاستعارة، بألفاظ السبيل، والرؤية، والاتخاذ»","url":""}]},{"id":"s7-968","number":968,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا أعيد لفظ ﴿سبيلًا﴾ بعد ﴿سبيل الرشد﴾ و﴿سبيل الغي﴾؟","answer":"أعيد ﴿سبيلًا﴾ لتأكيد أن موقفهم ليس رؤية عابرة للطريقين، بل اتخاذ أحدهما منهجًا ورفض الآخر منهجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص531–532، تحت «سر تكرار ألفاظ ﴿الرؤية﴾، و﴿السبيل﴾، و﴿الاتخاذ﴾»","url":""}]},{"id":"s7-969","number":969,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"ما سرّ التعبير بالباء السببية، في: ﴿بأنهم كذبوا﴾؟","answer":"اسم الإشارة يلخص سبب الصرف واتخاذ الغي: تكذيبهم بآيات الله وإعراضهم عن تدبرها والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص532–533، تحت «سر التعبير بالباء السببية، في: ﴿بأنهم كذبوا﴾»","url":""}]},{"id":"s7-970","number":970,"surah":7,"verses":[146],"references":[{"surah":7,"verses":[146]}],"verseLabel":"الأعراف: 146","question":"لماذا جُمِع بين التكذيب والغفلة مرة أخرى بعد الآية 136؟","answer":"في الآية 136 وصف حال فرعون وقومه قبل الإغراق، وهنا وصف سنة المتكبرين وعلة صرفهم عن الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص534، تحت «بلاغة جملتي الإخبار في سياق الآية»","url":""}]},{"id":"s7-971","number":971,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"لماذا أعيد الموصول: ﴿والذين كذبوا بآياتنا ولقاء الآخرة﴾؟","answer":"عدل عن الضمير إلى الموصول وصلته ليظهر أن التكذيب سبب خسران الأعمال وحبوطها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص539–540، تحت «بلاغة العدول، من الإضمار إلى التعريف بالموصولية»","url":""}]},{"id":"s7-972","number":972,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"لماذا عُطف ﴿لقاء الآخرة﴾ على ﴿آياتنا﴾؟","answer":"يضم إلى تكذيب الآيات إنكار يوم الجزاء، وهو المقام الذي يظهر فيه ثواب الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص539–540، تحت «سر إضافة ﴿لقاء﴾ إلى ﴿الآخرة﴾»","url":""}]},{"id":"s7-973","number":973,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير بقوله تعالى: ﴿لقاء الآخرة﴾ لا «لقاء الله»؟","answer":"﴿لقاء الآخرة﴾ يعم لقاء ما في الدار الآخرة من بعث وحساب وجزاء، فيناسب مقام حبوط الأعمال والجزاء عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص540، تحت «سر إضافة ﴿لقاء﴾ إلى ﴿الآخرة﴾»","url":""}]},{"id":"s7-974","number":974,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم﴾، وصوّر الأعمال كشيء يفسد؟","answer":"شبه ضياع ثواب الأعمال وعدم الانتفاع بها بفساد ما كان ينتظر نفعه. فقد تبدو بعض أعمالهم صالحة في نفسها، ولكن تكذيبهم بآيات الله ولقاء الآخرة يحرمهم ثمرتها عند الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص540–541، تحت «بلاغة التعبير بالفعل ﴿حبط﴾، على طريق التشبيه»","url":""}]},{"id":"s7-975","number":975,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"ما وجه التعبير بإحباط الأعمال دون مطلق إبطالها؟","answer":"الإحباط أخص هنا؛ فهو إبطال عمل البر من الحسنات بالسيئات. فيلائم السياق الذي يبين أن تكذيبهم بآيات الله ولقاء الآخرة أذهب ثواب ما ظنوه من أعمال الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص543، تحت «الإبطال، والإدحاض، والإحباط»","url":""}]},{"id":"s7-976","number":976,"surah":7,"verses":[147],"references":[{"surah":7,"verses":[147]}],"verseLabel":"الأعراف: 147","question":"لماذا ختم باستفهام: ﴿هل يجزون إلا ما كانوا يعملون﴾؟","answer":"الاستفهام إنكاري تقريري يفيد عدل الجزاء وحصره: لا يجزون إلا جنس ما داوموا على عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص541–542، تحت «نكتة الاستفهام بالأداة ﴿هل﴾»","url":""}]},{"id":"s7-978","number":978,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿واتخذ قوم موسى من بعده﴾، دون أن يقال: بنو إسرائيل؟","answer":"إضافتهم إلى موسى تستحضر قبح انقلاب قوم نبيهم في غيبته، وتبرئ موسى من فعلهم؛ وهي أنسب من الاسم النسبي المجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص549–550، تحت «دلالة التعبير بالبعدية في قوله: ﴿من بعده﴾»","url":""}]},{"id":"s7-979","number":979,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعده﴾ مع أن غيبة موسى معلومة؟","answer":"﴿من بعده﴾ أي بعد ذهابه إلى الميقات، وفيها تصوير سرعة الفتنة فور غيابه، لا بعد وفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص549–550، تحت «فائدة التعبير بـ﴿من﴾، في قوله: ﴿من بعده﴾»","url":""}]},{"id":"s7-980","number":980,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿من حليهم﴾، وما دلالة نسبة الحلي إليهم؟","answer":"نسب الحلي إليهم لأنها صارت في أيديهم وحيازتهم، وإن كان أصلها مما استعاروه من القبط؛ ومنها صيغ العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص550–551، تحت «سر إضافة الحلي إلى القوم»","url":""}]},{"id":"s7-981","number":981,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لم قدم ﴿من بعده﴾ و﴿من حليهم﴾ على ﴿عجلًا﴾؟","answer":"ينبه التقديم إلى موضع التعجيب والتوبيخ: سرعة اتخاذ العجل بعد غياب موسى، وإسهامهم بحليهم في صنع ما عبدوه. فيبرز قبح فعلهم قبل ذكر المفعول نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص551، تحت «سر تقديم شبه الجملة على المفعول»","url":""}]},{"id":"s7-982","number":982,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿عجلًا جسدًا﴾ لا «تمثال عجل»؟","answer":"يبين ﴿جسدًا﴾ أن المراد صورة عجل ذات جسم، لا عجل حي يعقل أو يميز، ولا مجرد نقش على سطح. ففي القيد احتراس يحدد حقيقة ما اتخذوه ويزيد توبيخهم على عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص551–552، تحت «بلاغة الاحتراس، في إتباع ﴿العجل﴾ بلفظ ﴿الجسد﴾»","url":""}]},{"id":"s7-983","number":983,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما معنى ﴿خوار﴾؟","answer":"الخوار صوت البقر، وذُكر هنا صوتًا خرج من العجل المصنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص546، تحت «شرح المفردات: ﴿خوار﴾»","url":""}]},{"id":"s7-1620","number":1620,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما الذي يكشفه قوله تعالى: ﴿له خوار﴾ عن فتنة العجل؟","answer":"وجود الصوت لا يثبت للعجل حياة ولا ألوهية؛ فهو صوت لا يفيد كلامًا ولا هداية، ومع ذلك كان موضع افتتانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص552–553، تحت «دلالة قوله: ﴿له خوار﴾، وأثرها في السياق»","url":""}]},{"id":"s7-984","number":984,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لماذا احتج عليهم بقوله: ﴿ألم يروا أنه لا يكلمهم﴾؟","answer":"الكلام من أوضح دلائل العلم والإرادة، فإذا كان لا يجيب عابديه ظهر بطلان ألوهيته مما يشاهدونه بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص553–554، تحت «توجيه الاستفهام في قوله: ﴿ألم يروا﴾»","url":""}]},{"id":"s7-985","number":985,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما وجه الاحتجاج بنفي التكليم والهداية عن العجل؟","answer":"نفي التكليم يكشف افتقاره إلى العلم والحياة، ونفي الهداية يكشف افتقاره إلى القدرة على الإرشاد. وبانتفاء هذه الصفات يظهر بطلان اتخاذه إلهًا، فيقيم الكلام الحجة من حال المعبود المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص554، تحت «تجلي بلاغة المذهب الكلامي بالاحتجاج النظري»","url":""}]},{"id":"s7-986","number":986,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"ما سر التعبير بقوله تعالى: ﴿ولا يهديهم سبيلًا﴾ لا «ولا يهديهم» فقط؟","answer":"ذكر ﴿سبيلًا﴾ يعمم نفي الإرشاد إلى الخير؛ فلا يدلهم العجل على طريق ينتفعون به، فضلًا عن هداية الدين والنجاة، فيظهر عجز ما اتخذوه معبودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص546، تحت «المعنى الإجمالي»","url":""}]},{"id":"s7-987","number":987,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لماذا كرر ﴿اتخذوه﴾ بعد تفصيل صنعه وعجزه؟","answer":"أعيد ﴿اتخذوه﴾ بعد إظهار عجزه للتعجيب والتوبيخ: مع وضوح أنه جسد لا يكلم ولا يهدي، اتخذوه إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص555–556، تحت «بلاغة الكناية في ﴿اتخذوه﴾»","url":""}]},{"id":"s7-988","number":988,"surah":7,"verses":[148],"references":[{"surah":7,"verses":[148]}],"verseLabel":"الأعراف: 148","question":"لماذا ختم بـ﴿وكانوا ظالمين﴾؟","answer":"الخاتمة تبين أن فعلهم ناشئ عن ظلم راسخ: ظلموا أنفسهم بالشرك ووضعوا العبادة في غير موضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص556–557، تحت «وجوه التعبير بجملة: ﴿وكانوا ظالمين﴾»","url":""}]},{"id":"s7-989","number":989,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما سقط في أيديهم﴾، وما صورة السقوط في اليد؟","answer":"كأن الندم وقع في أيديهم أو عضوا أيديهم بعد فوات الأمر، فصاروا عاجزين متحسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص562–563، تحت «الاستعارة التمثيلية، أو الكناية، أو التشبيه في: ﴿ولما سقط في أيديهم﴾»","url":""}]},{"id":"s7-990","number":990,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا بُني ﴿سقط﴾ للمجهول ولم يذكر الساقط؟","answer":"أجري التعبير مجرى المثل، فالمقصود تصوير الندم والعجز لا تعيين شيء سقط حقيقة. ويذكر المصدر أن البناء للمجهول يلائم وقوع هذه الحال عليهم من غير اختيار، وكأنهم صاروا مغلوبين محصورين لا حيلة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص566–567، تحت «براعة التعبير بالفعل المبني للمجهول ﴿سقط﴾»","url":""}]},{"id":"s7-991","number":991,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا جمع بين ﴿سقط في أيديهم﴾ و﴿ورأوا أنهم قد ضلوا﴾؟","answer":"الأول يصور حال الندم والحسرة، والثاني يبين سببها العقلي: تبين لهم أنهم فارقوا طريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص568–569، تحت «نكتة تقديم الندم على تبين الضلال»","url":""}]},{"id":"s7-992","number":992,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا أكد ضلالهم بـ﴿أنهم قد ضلوا﴾؟","answer":"﴿أن﴾ و﴿قد﴾ تثبتان تحقق الضلال ووضوحه لهم بعد انكشاف الفتنة؛ فلم يعد مجرد ظن.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص569، تحت «سر التعبير بالفعلين الماضيين ﴿ورأوا﴾، و﴿ضلوا﴾»","url":""}]},{"id":"s7-993","number":993,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما سرّ تقديم الرحمة على المغفرة في قولهم: ﴿لئن لم يرحمنا ربنا ويغفر لنا﴾؟","answer":"قدمت الرحمة لأنها المقصود الأصيل، ولأنها تشمل إرادة الخير لهم وتوفيقهم للتوبة التي تكون سببًا للمغفرة. فقدموا ما يرجون به الرجوع إلى الله، ثم طلبوا محو الذنب والتجاوز عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص571، تحت «علة تقديم الرحمة على المغفرة»","url":""}]},{"id":"s7-994","number":994,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما دلالة قولهم: ﴿ربنا﴾ بعد عبادتهم العجل؟","answer":"قولهم ﴿ربنا﴾ اعتراف بالرجوع إلى ربهم الحق بعد بطلان العجل، واستعطاف بوصف الربوبية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص570، تحت «سر الإتيان باللفظين ﴿ربنا﴾، و﴿لنا﴾»","url":""}]},{"id":"s7-995","number":995,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"لماذا أكدوا الخسران باللام والنون: ﴿لنكونن من الخاسرين﴾؟","answer":"اللام ونون التوكيد تثبتان يقينهم بأن عدم الرحمة والمغفرة يوقعهم حتمًا في الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص569، تحت «بلاغة حشد المؤكدات في الآية»","url":""}]},{"id":"s7-996","number":996,"surah":7,"verses":[149],"references":[{"surah":7,"verses":[149]}],"verseLabel":"الأعراف: 149","question":"ما سرّ تعبيرهم: ﴿من الخاسرين﴾ لا «خاسرين»؟","answer":"﴿من الخاسرين﴾ تدخلهم في زمرة معروفة استقر فيها الخسران، فهي أبلغ من وصفهم بخسارة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص570–571، تحت «بلاغة التعبير بـ﴿من﴾، على طريق الكناية»","url":""}]},{"id":"s7-997","number":997,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما رجع موسى إلى قومه غضبان أسفًا﴾، فجمع الغضب والأسف؟","answer":"الغضب إنكار شديد لما وقع من الشرك، والأسف شدة الحزن والتلهف عليه؛ فجمع بين الغيرة للحق والألم على ضلال قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص592، تحت «الأسف والغضب والحزن».","url":""}]},{"id":"s7-998","number":998,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ تقديم ﴿غضبان﴾ على ﴿أسفًا﴾؟","answer":"قدم الغضب لأن مقام الرسول أمام الشرك يقتضي الإنكار والغيرة على الدين، ولا يكتفى فيه بالحزن وحده. ثم جاء الأسف ليصور شدة التألم على ما آل إليه قومه، فجمع الموقف بين الإنكار والحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص578، تحت «علة تقديم الغضب على الأسف»","url":""}]},{"id":"s7-999","number":999,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما دلالة التعبير بفعل الذم ﴿بئسما﴾؟","answer":"﴿بئسما﴾ ذم شديد لما صنعوه في غيبته، و﴿خلفتموني﴾ أي بئس الخلافة التي قمتم بها بعدي إذ عبدتم العجل وخالفتم وصيتي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص578–579، تحت «دلالة التعبير بفعل الذم ﴿بئسما﴾»","url":""}]},{"id":"s7-1000","number":1000,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا جمع بين ﴿خلفتموني﴾ و﴿من بعدي﴾؟","answer":"يذم ﴿خلفتموني﴾ ما صنعوه في غيبته، ويصرح ﴿من بعدي﴾ بأن الانقلاب وقع بعد مفارقته؛ فيؤكد قبح الجحود ويرفع توهم أن اتخاذ العجل وقع بإقراره أو بحضوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص579–580، تحت «بلاغة الإطناب في قوله: ﴿من بعدي﴾»","url":""}]},{"id":"s7-1001","number":1001,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا سألهم: ﴿أعجلتم أمر ربكم﴾؟","answer":"الاستفهام إنكاري: أعجلتم عن أمر ربكم وميعاده قبل تمامه، واستبقتم حكمه فاتخذتم العجل؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص580–581، تحت «دلالة الاستفهام»","url":""}]},{"id":"s7-1002","number":1002,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا أضاف الأمر إلى ﴿ربكم﴾؟","answer":"إضافة الأمر إلى الرب تعظم ما استعجلوه وخالفوه، وتذكرهم بأن الميقات والتشريع صادران ممن يربيهم وينعم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص581–582، تحت «بلاغة العدول من التعريف بأل إلى التعريف بالإضافة»","url":""}]},{"id":"s7-1003","number":1003,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا ألقى موسى الألواح مع أنه أُمر أن يأخذها بقوة؟","answer":"ألقى الألواح من شدة الغضب لله عند رؤية الشرك، إلقاءً عارضًا لا رفضًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص582–583، تحت «علة التعبير بإلقاء الألواح»","url":""}]},{"id":"s7-1004","number":1004,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿وأخذ برأس أخيه يجره إليه﴾ لا «عاتب أخاه»؟","answer":"حكى الفعل المحسوس شدة غضبه وعتابه لهارون، إذ أخذ بشعر رأسه يجره إليه ظانًا أنه قصر، وهو أبلغ في تصوير المشهد من لفظ العتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص583–584، تحت «بلاغة التعبير بالمجاز المرسل عن أخذ الرأس»","url":""}]},{"id":"s7-1005","number":1005,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا نادى هارون موسى بقوله: ﴿ابن أم﴾ لا «يا أخي»؟","answer":"استعطفه برابطة الأم لأنها أرق وأدعى للرحمة، وهما أخوان لأب وأم؛ فاختار النداء الذي يهدئ غضبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص586–587، تحت «سر العدول من عبارة ابن أب إلى عبارة ﴿ابن أم﴾»","url":""}]},{"id":"s7-1006","number":1006,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما دلالة اعتذار هارون: ﴿إن القوم استضعفوني﴾؟","answer":"بيّن أنه لم يرض بعبادة العجل، لكن القوم عدوه ضعيفًا ولم يطيعوه، فكان قوله دفعًا لتهمة التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص587–588، تحت «علة تأكيد الخبر بـ﴿إن﴾»","url":""}]},{"id":"s7-1007","number":1007,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا جمع بين ﴿استضعفوني﴾ و﴿كادوا يقتلونني﴾؟","answer":"﴿استضعفوني﴾ يبين بداية تسلطهم ورفضهم أمره، و﴿كادوا يقتلونني﴾ يبلغ بهذا التسلط غايته؛ فالعجز كان عن مقاومة فتنة تهدد حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص588–589، تحت «فائدة تقديم فعل الاستضعاف على إرادة القتل»","url":""}]},{"id":"s7-1008","number":1008,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تشمت بي الأعداء﴾ قبل قوله ﴿ولا تجعلني مع القوم الظالمين﴾؟","answer":"بدأ بطلب دفع الأمر الأخص، وهو شماتة الأعداء به، ثم طلب الأمر الأعم، وهو ألا يلحق بالقوم الظالمين. فترقى في الالتماس من دفع أثر العتاب عنه إلى إظهار براءته من ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص590، تحت «نكتة تقديم فعل النهي عن الشماتة على فعل الترك»","url":""}]},{"id":"s7-1009","number":1009,"surah":7,"verses":[150],"references":[{"surah":7,"verses":[150]}],"verseLabel":"الأعراف: 150","question":"لماذا سمّى بعض القوم ﴿الأعداء﴾ مع أنهم من بني إسرائيل؟","answer":"سموا أعداء لأنهم عاندوا التوحيد وفرحوا بما يصيب هارون، وإن جمعهم نسب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص589–590، تحت «إيثار لفظ ﴿الأعداء﴾ على غيره»","url":""}]},{"id":"s7-1010","number":1010,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا بدأ موسى بالدعاء: ﴿رب اغفر لي ولأخي﴾ بعد سماع عذر هارون؟","answer":"جاء الدعاء جوابًا لما سمعه من اعتذار هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص594–595، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-1011","number":1011,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا قدّم نفسه في المغفرة: ﴿لي ولأخي﴾؟","answer":"بدأ بنفسه تأدبًا مع الله، ثم سأل المغفرة لأخيه وجمعه معه في الدعاء. وفي ذلك إظهار رضاه عنه، وقطع لطمع من أراد أن يشمت بهما أو يفرق بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص595، تحت «سر تقديم مغفرته على مغفرة أخيه»","url":""}]},{"id":"s7-1012","number":1012,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا طلب المغفرة لهارون مع ظهور عذره؟","answer":"الاستغفار لا يقتضي ثبوت ذنب محقق؛ هو دعاء بالستر والتجاوز عما قد يكون وقع من قصور في مقاومة القوم، وزيادة في التواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص595–596، تحت «سر تقديم مغفرته على مغفرة أخيه»","url":""}]},{"id":"s7-1013","number":1013,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿وأدخلنا في رحمتك﴾، فصوّر الرحمة مكانًا يُدخل فيه؟","answer":"صورت الرحمة كحيز واسع يحيط بهما ويحميهما، فطلبا رحمة شاملة لا عطاءً جزئيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص596–597، تحت «جمال التعبير بفعل الإدخال ﴿وأدخلنا﴾»","url":""}]},{"id":"s7-1014","number":1014,"surah":7,"verses":[151],"references":[{"surah":7,"verses":[151]}],"verseLabel":"الأعراف: 151","question":"لماذا ختم بـ﴿وأنت أرحم الراحمين﴾؟","answer":"ختم بأوسع وصف للرحمة توسلًا يناسب قوله ﴿وأدخلنا في رحمتك﴾، وإقرارًا بأن رحمته فوق رحمة كل راحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص597، تحت «بلاغة رد العجز على الصدر»","url":""}]},{"id":"s7-1015","number":1015,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا أعيد وصفهم بـ﴿الذين اتخذوا العجل﴾ بدل الضمير؟","answer":"أظهر الموصول ليعيد وصف جرمهم نفسه في مقام الوعيد، فيكون سبب العقوبة حاضرًا: اتخاذ العجل إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص602، تحت «براعة التعريف بالموصولية بلفظ ﴿الذين﴾»","url":""}]},{"id":"s7-1017","number":1017,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿سينالهم غضب﴾، فجعل الغضب نائلًا لهم؟","answer":"استعير النيل لإصابتهم بالغضب والذلة وتلبسهم بهما، فصور وقوع الجزاء عليهم. وتؤكد السين تحقق الوعيد في المستقبل، وأن ما توعدوا به سيلحقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص602–603، تحت «علة التعبير بسين الاستقبال ﴿سينالهم﴾»","url":""}]},{"id":"s7-1018","number":1018,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا نُكّر ﴿غضب﴾ و﴿ذلة﴾؟","answer":"التنكير للتهويل: غضب عظيم وذلة عظيمة لا يحيط السامع بمقدارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص603–604، تحت «نكتة تنكير الغضب والذلة»","url":""}]},{"id":"s7-1019","number":1019,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لم خص الغضب بقوله ﴿من ربهم﴾، ولم يكرر القيد مع الذلة؟","answer":"يذكر المصدر وجهًا يختص فيه غضب الآخرة بالله، فلا يشاركه فيه أحد، أما الذلة في الدنيا فقد تجري على أيدي البشر بإذنه. فناسب تقييد الغضب بأنه من ربهم، مع إطلاق الذلة التي تصيبهم في حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص604–605، تحت «نكتة قصر الغضب على الله دون الذلة»","url":""}]},{"id":"s7-1020","number":1020,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا قيّد الذلة بـ﴿في الحياة الدنيا﴾؟","answer":"قيدها بالدنيا لبيان أن أثر الشرك لا ينتظر الآخرة، بل يلحقهم فيه هوان دنيوي، مع بقاء عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص604–605، تحت «سر الجمع بين لفظي ﴿الحياة﴾ و﴿الدنيا﴾»","url":""}]},{"id":"s7-1021","number":1021,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"لماذا سمّى عبادة العجل افتراءً: ﴿وكذلك نجزي المفترين﴾؟","answer":"لأنهم اختلقوا على الله شريكًا ونسبوا الألوهية إلى العجل بلا برهان؛ فهذا أظهر الافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص605–606، تحت «نكتة التعبير بفعل الافتراء»","url":""}]},{"id":"s7-1022","number":1022,"surah":7,"verses":[152],"references":[{"surah":7,"verses":[152]}],"verseLabel":"الأعراف: 152","question":"ما أثر التذييل بقوله ﴿وكذلك نجزي المفترين﴾؟","answer":"يعمم التذييل الجزاء بعد ذكر عبدة العجل؛ فكل مفتر داخل في الوعيد بحسب افترائه. ويصور المضارع ﴿نجزي﴾ تجدد المجازاة واستمرارها، فلا ينحصر الحكم في أصحاب القصة وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص606، تحت «دلالة التعبير باسم الفاعل ﴿المفترين﴾»","url":""}]},{"id":"s7-1023","number":1023,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا قابل وعيد المفترين بقوله: ﴿والذين عملوا السيئات ثم تابوا﴾؟","answer":"بعد الوعيد فتح باب الرجاء: حتى من عمل السيئات إذا تاب وآمن وجد المغفرة والرحمة، فلا يتحول الوعيد إلى يأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص607–608، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s7-1024","number":1024,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿عملوا السيئات﴾ لا «أساؤوا»؟","answer":"التعبير بـ﴿عملوا السيئات﴾ يصرح بإسناد العمل السيئ إليهم، سواء تعلق سوء الفعل بالمباشرة أو كان العمل سيئًا في نفسه. وهو أخص من مطلق الإساءة، فإذا قبلت التوبة ممن تحقق منه هذا العمل كان ذلك أبلغ في فتح باب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص608–609، تحت «سر العدول عن التعبير بعبارة والذين أساؤوا»","url":""}]},{"id":"s7-1025","number":1025,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"ما أثر صيغة الماضي والجمع في ﴿تابوا﴾ و﴿آمنوا﴾؟","answer":"يثبت الماضي وقوع التوبة والإيمان والعزم عليهما، ويعلن الجمع اتساع القبول للتائبين؛ فلا يعظم على مغفرة الله ذنب تاب صاحبه منه، مهما كثر الذنب أو طال زمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص610، تحت «سر التعبير بالماضي والجمع»","url":""}]},{"id":"s7-1026","number":1026,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا عطف التوبة بـ﴿ثم﴾؟","answer":"تفيد ﴿ثم﴾ التراخي، فتفتح باب التوبة ولو جاءت بعد زمن طويل قضاه العبد في السيئات. وفي ذلك ترغيب في الرجوع إلى الله، دون اليأس بسبب طول المدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص609، تحت «جمال التعبير بحرف العطف ﴿ثم﴾»","url":""}]},{"id":"s7-1027","number":1027,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"إلى ماذا يعود الضمير في موضعي ﴿من بعدها﴾ في الآية؟","answer":"في ﴿ثم تابوا من بعدها﴾ يعود إلى السيئات، أي بعد عملها. وفي ﴿إن ربك من بعدها لغفور رحيم﴾ يرجح المصدر عوده إلى التوبة المفهومة من ﴿تابوا﴾، ويذكر احتمال عوده إلى السيئات مع تقدير العمل والتوبة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص609–610، تحت «توجيه عود الضمير في ﴿من بعدها﴾»","url":""}]},{"id":"s7-1028","number":1028,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا أكد المغفرة بـ﴿إن ربك من بعدها لغفور رحيم﴾؟","answer":"أكدت الجملة بـ﴿إن﴾ واللام لرفع اليأس بعد عظم السيئات، وتثبيت أن المغفرة والرحمة حاصلتان لمن صدق في التوبة والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص611–612، تحت «بلاغة التوكيد بحشد المؤكدات»","url":""}]},{"id":"s7-1029","number":1029,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"ما أثر إضافة الرب إلى المخاطب في ﴿إن ربك﴾؟","answer":"في الإضافة تشريف للمخاطب بانتسابه إلى ربه، وفي وصف الربوبية تمهيد للمغفرة والرحمة بما يتضمنه من التربية والرعاية والإحسان. ويجعل المصدر الخطاب لمحمد ﷺ على الأظهر، ويذكر احتمال أن يكون لموسى في حكاية الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص611، تحت «كمال التعريف بالإضافة، والوصف بالربوبية»","url":""}]},{"id":"s7-1030","number":1030,"surah":7,"verses":[153],"references":[{"surah":7,"verses":[153]}],"verseLabel":"الأعراف: 153","question":"لماذا جُمع بين ﴿غفور رحيم﴾؟","answer":"﴿غفور﴾ لمحو الذنب وستره، و﴿رحيم﴾ لإيصال الخير بعد المغفرة؛ فالتائب لا ينجو فقط بل تناله الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص612، تحت «دلالة التعبير بصيغتي المبالغة فعول وفعيل»","url":""}]},{"id":"s7-1031","number":1031,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما سكت عن موسى الغضب﴾، فجعل الغضب كأنه متكلم؟","answer":"شبه الغضب بشخص كان يحرك موسى ويدفعه إلى الكلام والفعل ثم سكت عنه؛ فصوّر هدوء ثورته بعد زوال سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص615–616، تحت «كمال الاستعارات وتنوعها في لفظة السكوت»","url":""}]},{"id":"s7-1032","number":1032,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا عُدّي السكوت بـ﴿عن﴾؟","answer":"﴿سكت عن موسى﴾ تفيد انصراف سلطان الغضب عنه وكف أثره، كما يكف المتكلم كلامه عن شخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص614–615، تحت «وجه التعبير بلفظ ﴿سكت﴾ على طريق التضمين»","url":""}]},{"id":"s7-1033","number":1033,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا أعاد موسى أخذ الألواح بعد أن ألقاها؟","answer":"لما هدأ غضبه عاد إلى الألواح تعظيمًا للوحي وامتثالًا للأخذ بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص617، تحت «دلالة أل التعريف في لفظ ﴿الألواح﴾»","url":""}]},{"id":"s7-1034","number":1034,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿وفي نسختها﴾ لا «وفيها»؟","answer":"﴿نسختها﴾ أي ما نُسخ وكتب فيها، فوجه النظر إلى مضمونها المثبت لا إلى جرم الألواح وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص617–618، تحت «وجه التعبير عن نسخة ﴿الألواح﴾ على طريق الإيجاز»","url":""}]},{"id":"s7-1035","number":1035,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا جمع بين ﴿هدى ورحمة﴾؟","answer":"الهدى يبين طريق الحق، والرحمة ثمرة سلوكه من خير ونجاة؛ فجمعت الألواح الدلالة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص619–620، تحت «سر تقديم الهدى على الرحمة»","url":""}]},{"id":"s7-1036","number":1036,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا خُص الهدى والرحمة بـ﴿للذين هم لربهم يرهبون﴾؟","answer":"الألواح هدى ورحمة في ذاتها، لكن الانتفاع الخاص بهما لمن يخاف ربه فيقبل أمره ويترك نهيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص620، تحت «علة تخصيص أهل الرهبة بالذكر، والتعبير بالمضارع»","url":""}]},{"id":"s7-1037","number":1037,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"ما سرّ تقديم ﴿لربهم﴾ على ﴿يرهبون﴾؟","answer":"تقديم ﴿لربهم﴾ للاختصاص والعناية: رهبتهم متوجهة إلى ربهم لا إلى سواه، ومن هذه الرهبة ينشأ امتثالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص620، تحت «نكتة تقديم المفعول في ﴿يرهبون﴾»","url":""}]},{"id":"s7-1038","number":1038,"surah":7,"verses":[154],"references":[{"surah":7,"verses":[154]}],"verseLabel":"الأعراف: 154","question":"لماذا جيء بضمير ﴿هم﴾؟","answer":"ضمير ﴿هم﴾ يقوي الحكم ويخص المنتفعين الكاملين بالرهبة، فيفصلهم عمن يقرأ ولا يتعظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص620، تحت «فائدة الضمير ﴿هم﴾ في قوله: ﴿هم لربهم﴾»","url":""}]},{"id":"s7-1039","number":1039,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿واختار موسى قومه سبعين رجلًا﴾ من غير حرف جر؟","answer":"ويصور الحذف شدة اتصال المختارين بقومهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص624–625، تحت «سر حذف حرف الجر في السياق»","url":""}]},{"id":"s7-1040","number":1040,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لم قدم ﴿قومه﴾ على ﴿سبعين رجلًا﴾؟","answer":"قدم ذكر القوم لأن الاختيار وقع فيهم، وللعناية بهم وبصلتهم بموسى، ثم بين المختارين منهم. ويعرض المصدر التقديم بوصفه عناية بالمجموعة التي انتخب منها خيارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص625–626، تحت «فائدة تقديم المجرور، وتأخير المفعول»","url":""}]},{"id":"s7-1041","number":1041,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما دلالة لفظ الميقات واللام في ﴿لميقاتنا﴾؟","answer":"الميقات وقت معين مقدر للعمل، فهو أخص من مطلق الوقت.؛ أي اختارهم ليأتوا إلى ذلك الميقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص627، تحت «الغاية من التعبير بلفظ الميقات، والفرق بينه وبين الوقت»","url":""}]},{"id":"s7-1042","number":1042,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما أخذتهم الرجفة﴾، فجعل الرجفة آخذة؟","answer":"شبهت الرجفة بقوة تقبض عليهم وتستولي على أجسادهم، فكان الأخذ تصويرًا لشدة إحاطتها وتمكنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص628، تحت «بلاغة المجاز اللغوي والعقلي في ﴿أخذتهم الرجفة﴾»","url":""}]},{"id":"s7-1043","number":1043,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما دلالة قول موسى: ﴿لو شئت أهلكتهم من قبل وإياي﴾؟","answer":"ويذكر المصدر أنه تذكير بالعفو السابق واستجلاب للعفو اللاحق، مع تسليم موسى نفسه لأمر ربه، لا اعتراض على حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص631–632، تحت «سر تفريق موسى عليه السلام في الإهلاك بينه وبينهم»","url":""}]},{"id":"s7-1044","number":1044,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لم قال ﴿أهلكتهم من قبل وإياي﴾ ولم يجمعهم في «أهلكتنا»؟","answer":"يفرد التعبير كل فريق بالذكر ليناسب اختلاف الحال وما يتعلق بكل منهم. ويذكر المصدر وجهًا آخر في ذكر موسى نفسه: أنه تسليم لأمر الله مع طلب العفو لقومه، فكأنه لا يطلب سلامتهم مع الاستثناء لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص631–632، تحت «سر تفريق موسى عليه السلام في الإهلاك بينه وبينهم»","url":""}]},{"id":"s7-1045","number":1045,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا سأل: ﴿أتهلكنا بما فعل السفهاء منا﴾؟","answer":"الاستفهام استعطاف وتبرؤ من فعل السفهاء: أتهلك الجماعة بسبب من اقترف الجرم منها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص632–633، تحت «بلاغة الاستفهام في ﴿أتهلكنا﴾»","url":""}]},{"id":"s7-1046","number":1046,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا وصف الفاعلين بـ﴿السفهاء منا﴾؟","answer":"وصفهم بالسفه لأن طلب الرؤية أو عبادة العجل صدر عن خفة عقل وجهل، و﴿منا﴾ تقر بالانتساب إليهم من غير تعميم الجرم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص634، تحت «إيثار لفظ ﴿السفهاء﴾ والتعبير به»","url":""}]},{"id":"s7-1047","number":1047,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إن هي إلا فتنتك﴾ بالقصر؟","answer":"القصر يرد الأمر كله إلى اختبار الله وحده: هذه الحادثة ليست خارجة عن تدبيره، بل امتحان يكشف المواقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص635، تحت «بلاغة القصر باستعمال الخبر والتعبير به»","url":""}]},{"id":"s7-1048","number":1048,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"إلى ماذا يعود الضمير في ﴿إن هي إلا فتنتك﴾؟","answer":"يعود إلى الفتنة الواقعة، كعبادة العجل أو طلب الرؤية وما ترتب عليه من الرجفة؛ والتأنيث لمراعاة لفظ ﴿فتنة﴾ المفهوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص634–635، تحت «بيان عود الضمير ﴿هي﴾»","url":""}]},{"id":"s7-1049","number":1049,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا جمع بين ﴿تضل بها من تشاء وتهدي من تشاء﴾؟","answer":"جمع الضدين لإظهار أن الفتنة الواحدة تكون سببًا لضلال من يعرض وهداية من يعتبر، وكل ذلك بمشيئة الله وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص636، تحت «بلاغة الطباق في ﴿تضل﴾ و﴿تهدي﴾»","url":""}]},{"id":"s7-1050","number":1050,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"كيف يتضمن قوله ﴿تضل بها من تشاء وتهدي من تشاء﴾ طلب الهداية؟","answer":"أقر موسى بأن الهداية بمشيئة الله، وفي هذا الإقرار تعريض بطلبها لقومه واسترحام لهم. فلم يقتصر الكلام على الإخبار، بل حمل معنى الدعاء بأدب وتضرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص635، تحت «نكتة التعريض بطلب الهداية لهم»","url":""}]},{"id":"s7-1051","number":1051,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"ما سرّ تقديم ضمير المخاطب في قوله: ﴿أنت ولينا﴾؟","answer":"تقديم ﴿أنت﴾ يفيد القصر والتوكيد: أنت وحدك متولي أمرنا وناصرنا، لا ملجأ لنا في هذه الفتنة إلا إليك.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص636–637، تحت «بلاغة القصر والتقديم في ﴿أنت ولينا﴾»","url":""}]},{"id":"s7-1052","number":1052,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا جمع بين ﴿فاغفر لنا وارحمنا﴾؟","answer":"المغفرة تزيل أثر الذنب، والرحمة تجلب العفو والخير؛ فطلب رفع الضر وإحلال الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص637–638، تحت «علة تقديم المغفرة على الرحمة»","url":""}]},{"id":"s7-1053","number":1053,"surah":7,"verses":[155],"references":[{"surah":7,"verses":[155]}],"verseLabel":"الأعراف: 155","question":"لماذا ختم بـ﴿وأنت خير الغافرين﴾ لا «أرحم الراحمين»؟","answer":"لأن المقام بدأ بطلب المغفرة في ﴿فاغفر لنا﴾، فناسبه ﴿خير الغافرين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص638–639، تحت «سر قوله: ﴿وأنت خير الغافرين﴾»","url":""}]},{"id":"s7-1054","number":1054,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿واكتب لنا في هذه الدنيا حسنة﴾، واستعار الكتابة للحسنة؟","answer":"الكتابة استعارة للإثبات والتقدير المحكم؛ أي قدر لنا حسنة ثابتة لا تزول كأنها مكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص644–645، تحت «سر التعبير بالكتابة دون الإيتاء»","url":""}]},{"id":"s7-1055","number":1055,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿في هذه الدنيا﴾ باسم الإشارة؟","answer":"الإشارة تحضر الدنيا القريبة المشاهدة وتقابلها بالآخرة الغائبة، وفيها اعتراف بقصر هذه الدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص646–647، تحت «سر الإشارة بـ﴿هذه الدنيا﴾»","url":""}]},{"id":"s7-1056","number":1056,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا نكّر ﴿حسنة﴾ في الدنيا وحذفها بعد ﴿وفي الآخرة﴾؟","answer":"نُكرت ﴿حسنة﴾ لتعم كل نعمة حسنة في الدنيا، وحذفت بعد ﴿وفي الآخرة﴾ لدلالة الأولى عليها، أي واكتب لنا حسنة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص652–653، تحت «سر عدم تكرار لفظ ﴿حسنة﴾ مع الآخرة»","url":""}]},{"id":"s7-1057","number":1057,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما دلالة قولهم: ﴿إنا هدنا إليك﴾، وما معنى «هدنا»؟","answer":"﴿هدنا﴾ أي رجعنا وتبنا إليك، فأعلنوا الانتقال من المعصية إلى ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص654–655، تحت «دلالة التعبير بالماضي ﴿هدنا﴾»","url":""}]},{"id":"s7-1058","number":1058,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما صلة ﴿هدنا﴾ بتسمية اليهود؟","answer":"يذكر المصدر وجه اشتقاق تسميتهم من الهود بمعنى الرجوع والتوبة، لقولهم ﴿إنا هدنا إليك﴾. فالآية في هذا التوجيه تعلن توبتهم ورجوعهم، وهذا وجه في تعليل الاسم وليس جزمًا بحصر أصله فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص641–642، تحت «شرح المفردات: ﴿هدنا﴾»","url":""}]},{"id":"s7-1059","number":1059,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا جاء الجواب: ﴿عذابي أصيب به من أشاء ورحمتي وسعت كل شيء﴾؟","answer":"جاء الجواب موزعًا بين العدل والفضل: العذاب يصيب من تعلقت به المشيئة لحكمة، أما الرحمة فأصلها واسع ثم تكتب كتابة خاصة للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص661–662، تحت «دلالة الإتيان بجملة: ﴿ورحمتي﴾ عقب ﴿قال عذابي﴾»","url":""}]},{"id":"s7-1060","number":1060,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى في العذاب: ﴿أصيب به﴾، وفي الرحمة: ﴿وسعت﴾؟","answer":"﴿أصيب به﴾ يجعل العذاب محددًا يقع على من استحقه، أما ﴿وسعت﴾ فتصور الرحمة محيطة بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص658–659، تحت «سر التعبير بالإصابة، في قوله: ﴿أصيب به﴾»","url":""}]},{"id":"s7-1061","number":1061,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ تقديم العذاب على الرحمة هنا؟","answer":"قدم العذاب للتخويف والتحذير في مقام الخوف من الهلاك، ثم عقب بسعة الرحمة ليقوي الرجاء. ويذكر المصدر أن البدء بالرحمة ثم ختم الكلام بالعذاب قد يجعل الخوف هو الأثر الأخير؛ فجاء هذا الترتيب ألطف بالمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص662، تحت «دلالة تقديم ذكر العذاب على الرحمة»","url":""}]},{"id":"s7-1062","number":1062,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا نُسب العذاب والرحمة إلى ضمير المتكلم: ﴿عذابي... رحمتي﴾؟","answer":"الإضافة في ﴿عذابي﴾ و﴿رحمتي﴾ تثبت أن التصرف لله وحده، وتعظم الأمرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص658، تحت «دلالة الإضافة في قوله: ﴿عذابي﴾»","url":""}]},{"id":"s7-1063","number":1063,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿ورحمتي وسعت كل شيء﴾، دون أن يقال: وأرحم من أشاء؟","answer":"أبرزت الجملة سعة الرحمة وعمومها فلم يقيد أصلها بفئة في صدر الكلام، ثم فرع عليها الوعد الخاص لمن يتقون ويؤتون الزكاة ويؤمنون بالآيات. فاجتمع عموم الرحمة مع بيان أهل الوعد المخصوص بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص665–666، تحت «دلالة الجمع بين ﴿كل﴾ و﴿شيء﴾ في الآية»","url":""}]},{"id":"s7-1064","number":1064,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"كيف تجمع الآية بين سعة الرحمة لكل شيء وقوله: ﴿فسأكتبها للذين يتقون﴾؟","answer":"الأولى تقرر عموم رحمة الله وسعة آثارها في الخلق، والثانية وعد مخصوص لمن اتصفوا بالتقوى والإيمان والعمل المذكور. فالتخصيص يتعلق بكتابة هذا الوعد لهم، ولا ينفي ما ينال سائر الخلق من آثار الرحمة العامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص665–666، تحت «دلالة الجمع بين ﴿كل﴾ و﴿شيء﴾ في الآية»","url":""}]},{"id":"s7-1065","number":1065,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا عُبر عن الرحمة الخاصة بالكتابة: ﴿فسأكتبها﴾؟","answer":"الكتابة تفيد التثبيت والإيجاب بوعد لا يتخلف؛ فهي رحمة خاصة مقدرة للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص644–645، تحت «سر التعبير بالكتابة دون الإيتاء»","url":""}]},{"id":"s7-1066","number":1066,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا رتبت صفات مستحقي الرحمة: ﴿يتقون ويؤتون الزكاة والذين هم بآياتنا يؤمنون﴾؟","answer":"بدأ بالتقوى لأنها أصل الكف عن المعصية، ثم الزكاة مثال البذل العملي، ثم الإيمان بالآيات أصل التصديق الجامع للأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص668–669، تحت «دلالة الواو في ﴿ويؤتون الزكاة﴾»","url":""}]},{"id":"s7-1067","number":1067,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"لماذا أعيد الموصول في ﴿والذين هم بآياتنا يؤمنون﴾؟","answer":"أعيد الموصول للاهتمام بالإيمان بالآيات وجعله صفة مستقلة جامعة، مع تقوية فصلها عما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص671–672، تحت «سر إعادة اسم الموصول ﴿والذين﴾»","url":""}]},{"id":"s7-1068","number":1068,"surah":7,"verses":[156],"references":[{"surah":7,"verses":[156]}],"verseLabel":"الأعراف: 156","question":"ما سرّ تقديم ﴿بآياتنا﴾ على ﴿يؤمنون﴾؟","answer":"تقديم ﴿بآياتنا﴾ للعناية والاختصاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص672–673، تحت «سر التعبير بالآيات في قوله: ﴿بآياتنا﴾»","url":""}]},{"id":"s7-1069","number":1069,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا وصف محمد ﷺ بـ﴿الرسول النبي الأمي﴾، وجمع هذه الأوصاف؟","answer":"﴿الرسول﴾ يبرز حمله الرسالة إلى الناس، و﴿النبي﴾ صلته بالوحي، و﴿الأمي﴾ قيام الحجة بأن ما جاء به ليس مكتسبًا من قراءة كتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص681–682، تحت «سر الجمع بين وصفي ﴿الرسول النبي﴾»","url":""}]},{"id":"s7-1070","number":1070,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ تقديم ﴿الرسول﴾ على ﴿النبي﴾ هنا؟","answer":"قدم وصف الرسول لشرف الرسالة وإبراز كونه مرسلًا من الله إلى الناس، ثم أتبع بالنبوة التي تؤكد تلقيه الوحي. واجتماع الوصفين يقوي الحجة الداعية إلى اتباعه ويجمع أسباب الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص680–681، تحت «سر الجمع بين وصفي ﴿الرسول النبي﴾»","url":""}]},{"id":"s7-1071","number":1071,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا وُصف النبي ﷺ بـ﴿الأمي﴾؟","answer":"وصفه بالأمي لأنه لم يقرأ كتابًا ولم يكتب، فكان مجيئه بالقرآن دليلًا على الوحي، وهو أيضًا من الأمة الأمية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص682–683، تحت «دلالة تأخير وصف ﴿الأمي﴾ على الرسالة والنبوة»","url":""}]},{"id":"s7-1072","number":1072,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما فائدة التعبير بالظرفية في قوله: ﴿عندهم﴾ دون فيه؟","answer":"﴿يجدونه﴾ يدل على أنهم يعثرون على صفته حاضرة ثابتة، و﴿مكتوبًا عندهم﴾ يلزمهم بما في الكتب التي بأيديهم لا بخبر بعيد عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص684–685، تحت «فائدة التعبير بالظرفية في قوله: ﴿عندهم﴾ دون فيه»","url":""}]},{"id":"s7-1073","number":1073,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا جمع بين ﴿في التوراة والإنجيل﴾؟","answer":"ذكرا لأن البشارة به وصفاته ثبتت في كتابي اليهود والنصارى، فالحجة قائمة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص685–686، تحت «دلالة الجمع بين التوراة والإنجيل»","url":""}]},{"id":"s7-1074","number":1074,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا رتبت وظائفه: ﴿يأمرهم بالمعروف وينهاهم عن المنكر ويحل لهم الطيبات ويحرم عليهم الخبائث﴾؟","answer":"بدأ بإصلاح المجتمع بالأمر والنهي، ثم بيان الحلال والحرام، ثم رفع التكاليف الشاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص691–692، تحت «سر الإتيان بالتحليل والتحريم، مقابل الأمر بالمعروف والنهي عن المنكر»","url":""}]},{"id":"s7-1075","number":1075,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما أثر التعبير بالمعروف والمنكر والطيبات والخبائث في وصف رسالته؟","answer":"وذكر الطيبات والخبائث يبين أن الحل والتحريم متعلقان بما فيه نفع وحسن أو خبث وضرر، فيقترن بيان الحكم بما يرغب في امتثاله أو ينفر من مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص693–694، تحت «دلالة التعبير بلفظ ﴿الطيبات﴾ عن الحلال»","url":""}]},{"id":"s7-1076","number":1076,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿ويضع عنهم إصرهم﴾، وصوّر الإصر كحمل؟","answer":"الإصر الثقل والتكليف الشاق؛ فصوّر الشرائع الثقيلة بحمل موضوع فوقهم، والرسول يرفعه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص694–695، تحت «بلاغة الاستعارة، في قوله: ﴿ويضع عنهم﴾»","url":""}]},{"id":"s7-1077","number":1077,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا أفرد ﴿إصرهم﴾ وجمع ﴿الأغلال﴾؟","answer":"الإصر مفرد لأنه اسم جنس للثقل الجامع، والأغلال جمعت لتعدد القيود والتكاليف التي كانت تكبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص696–697، تحت «دلالة الإفراد والجمع، في القراءة المتواترة: ﴿إصرهم﴾»","url":""}]},{"id":"s7-1078","number":1078,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير بقوله عليهم دون فوقهم؟","answer":"شبهت التكاليف الشديدة بالأغلال المحيطة بالأعناق، و﴿كانت عليهم﴾ تدل على ثقلها واستعلائها قبل أن ترفعها الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص697–698، تحت «سر التعبير بقوله عليهم دون فوقهم»","url":""}]},{"id":"s7-1079","number":1079,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا رتبت الاستجابة: ﴿آمنوا به وعزروه ونصروه واتبعوا النور﴾؟","answer":"بدأوا بتصديقه في القلب، ثم تعظيمه وتوقيره، ثم نصر رسالته، ثم ملازمة القرآن والعمل به؛ فانتقل من الاعتقاد إلى النصرة والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص699–700، تحت «سر الترتيب في أوصاف: الإيمان والتعزير والنصر واتباع التنزيل»","url":""}]},{"id":"s7-1080","number":1080,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا سمّى القرآن ﴿النور الذي أنزل معه﴾؟","answer":"سماه نورًا لأنه يكشف الحق من الباطل ويهدي في ظلمات الجهل، كما يكشف النور الطريق المحسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص700، تحت «بلاغة التعبير بلفظ ﴿النور﴾ عن القران»","url":""}]},{"id":"s7-1081","number":1081,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿أنزل معه﴾ مع أن القرآن أُنزل إليه؟","answer":"﴿معه﴾ تفيد المصاحبة بين الرسول والقرآن في أداء الرسالة؛ أنزل القرآن مؤيدًا له ومقترنًا ببعثته، وإن كان التنزيل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص701، تحت «سر التعبير بالمعية في ﴿أنزل معه﴾»","url":""}]},{"id":"s7-1082","number":1082,"surah":7,"verses":[157],"references":[{"surah":7,"verses":[157]}],"verseLabel":"الأعراف: 157","question":"لماذا خُتم بـ﴿أولئك هم المفلحون﴾؟","answer":"اسم الإشارة مع ضمير الفصل وتعريف الخبر يفيد اختصاصهم بالفلاح الكامل؛ لأنهم جمعوا الإيمان والتعظيم والنصرة والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص701–702، تحت «بلاغة التركيب، في قوله: ﴿أولئك هم المفلحون﴾»","url":""}]},{"id":"s7-1083","number":1083,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا انتقل إلى الأمر العام: ﴿قل يا أيها الناس﴾ بعد خطاب بني إسرائيل؟","answer":"انتقل من حكاية البشارة به في كتب أهل الكتاب إلى إعلان عموم رسالته لكل البشر، فلا يظن أنها خاصة بأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص706، تحت «دلالة جملة النداء ﴿يا أيها الناس﴾»","url":""}]},{"id":"s7-1084","number":1084,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"ما أثر النداء في ﴿يا أيها الناس﴾؟","answer":"يلفت النداء انتباه المخاطبين إلى الدعوة ويوقظهم من الغفلة، ولفظ الناس يعمم الإعلان ليشمل البشر جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص706، تحت «دلالة جملة النداء ﴿يا أيها الناس﴾»","url":""}]},{"id":"s7-1085","number":1085,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا أكد: ﴿إني رسول الله إليكم جميعًا﴾؟","answer":"أكد بـ﴿إن﴾ لمواجهة من ينكر عموم رسالته أو يقصرها على العرب، وقرر أنه رسول الله إلى المخاطبين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص707–708، تحت «دلالة التأكيد بـ﴿إني﴾»","url":""}]},{"id":"s7-1086","number":1086,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿إليكم جميعًا﴾ مع أن ﴿الناس﴾ تفيد العموم؟","answer":"﴿جميعًا﴾ نص في استغراق أفراد الناس وتدفع احتمال إرادة طائفة مخصوصة من لفظ ﴿الناس﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص708–709، تحت «سر التعبير بقوله تعالى ﴿جميعًا﴾»","url":""}]},{"id":"s7-1087","number":1087,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا وُصف الله بـ﴿الذي له ملك السماوات والأرض﴾ عقب عالمية الرسالة؟","answer":"من له ملك السماوات والأرض يملك إرسال رسول إلى جميع من فيهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص709–710، تحت «علاقة قوله ﴿الذي له ملك السماوات والأرض﴾ بما قبله»","url":""}]},{"id":"s7-1089","number":1089,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا أعقب الملك بقوله: ﴿لا إله إلا هو﴾؟","answer":"إذا انفرد بالملك لزم انفراده بالعبادة، فجاء التوحيد نتيجة لتمام السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص710، تحت «دلالة موقع جملة ﴿لا إله إلا هو يحيي ويميت﴾ مما قبلها»","url":""}]},{"id":"s7-1090","number":1090,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا جمع بين ﴿يحيي ويميت﴾؟","answer":"جمعهما لإثبات السلطان على طرفي الوجود الإنساني ومصيره، ومن يحيي ويميت وحده يستحق العبادة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص710–711، تحت «سر الإتيان بصفة الإحياء والإماتة»","url":""}]},{"id":"s7-1091","number":1091,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا فرّع الأمر بالإيمان: ﴿فآمنوا بالله ورسوله﴾؟","answer":"الفاء تفرع وجوب الإيمان على البراهين السابقة: عموم الرسالة، وملك الله، ووحدانيته، وإحياؤه وإماتته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص712–713، تحت «دلالة الفاء في قوله ﴿فآمنوا﴾»","url":""}]},{"id":"s7-1092","number":1092,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا أعيد وصف الرسول بـ﴿النبي الأمي﴾ بعد الآية السابقة؟","answer":"أعيد الوصف لتعيين الرسول المأمور بالإيمان به، ولتذكير الناس بدليل أميته الذي سبق أن أقيم على أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص714–715، تحت «سر إعادة وصفه بقوله ﴿النبي الأمي﴾»","url":""}]},{"id":"s7-1093","number":1093,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"ما سرّ التعبير في قوله تعالى عن الرسول: ﴿الذي يؤمن بالله وكلماته﴾؟","answer":"يعلن الوصف كمال إيمانه بالله وتصديقه بكلماته؛ فالإيمان بالله لا ينفك عن الإيمان بوحيه وآياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص715–716، تحت «دلالة التصريح بإيمانه بالله في قوله ﴿الذي يؤمن بالله﴾»","url":""}]},{"id":"s7-1094","number":1094,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا جُمعت ﴿كلماته﴾؟","answer":"الجمع يشمل كلمات الله الكونية والشرعية وكتبه ووحيه المتعدد، وفيه كمال تصديق الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص716–717، تحت «سر اختيار صيغة الجمع ﴿وكلماته﴾»","url":""}]},{"id":"s7-1095","number":1095,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]}],"verseLabel":"الأعراف: 158","question":"لماذا ختم بـ﴿واتبعوه لعلكم تهتدون﴾ بعد الأمر بالإيمان؟","answer":"الإيمان أصل القلب، والاتباع أثره العملي؛ فليس المقصود مجرد التصديق، وإنما سلوك هديه، وبه ترجى الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص718، تحت «بلاغة موقع فاصلة الآية: ﴿لعلكم تهتدون﴾».","url":""}]},{"id":"s7-1096","number":1096,"surah":7,"verses":[158],"references":[{"surah":7,"verses":[158]},{"surah":57,"verses":[7]},{"surah":64,"verses":[8]}],"verseLabel":"الأعراف: 158؛ الحديد: 7؛ التغابن: 8","question":"ما سرّ التعبير في قوله تعالى في الأعراف والتغابن: ﴿فآمنوا بالله ورسوله﴾ بالفاء، وفي الحديد: ﴿آمنوا بالله ورسوله﴾ بلا فاء؟","answer":"في الأعراف جاءت الفاء تفريعًا على صفات الله من الملك والتوحيد والإحياء والإماتة، وفي التغابن فاء فصيحة: إذا تبينت الحجج والعواقب فآمنوا؛ أما الحديد فانتقل من الاستدلال إلى الأمر المباشر بلا حاجة إلى تفريع ظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص658، تحت «سر اختلاف التعبير بالإيمان في الأعراف والتغابن»","url":""}]},{"id":"s7-1097","number":1097,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن قوم موسى أمة﴾ بعد ذكر انحرافات بني إسرائيل؟","answer":"استدرك بأن من قوم موسى جماعة ثابتة على الحق، إنصافًا للصالحين منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص722–723، تحت «دلالة الواو في قوله ﴿ومن قوم موسى﴾»","url":""}]},{"id":"s7-1098","number":1098,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لم اختير لفظ ﴿أمة﴾ دون طائفة أو جماعة؟","answer":"يشعر لفظ الأمة باجتماعهم على قصد واحد هو الحق، وبائتمامهم بموسى وهداهم الذي يقتدي به غيرهم. فلا يراد مجرد جماعة اجتمع أفرادها، بل جماعة يجمعها مقصد هادٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص723، تحت «سر اختيار لفظ ﴿أمة﴾ دون طائفة أو جماعة»","url":""}]},{"id":"s7-1099","number":1099,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿يهدون بالحق﴾ لا «يهتدون»؟","answer":"﴿يهدون﴾ متعدٍّ.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص723–724، تحت «سر اختيار ﴿يهدون﴾ دون يدعون»","url":""}]},{"id":"s7-1100","number":1100,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لماذا عُدّيت الهداية بـ﴿الباء﴾: ﴿بالحق﴾؟","answer":"الباء للملابسة؛ فهم يهدون ملازمين للحق، ويقيمون العدل به. فهدايتهم وعدلهم مرتبطان بالحق لا بالهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص724، تحت «سر تكرار الجار والمجرور ﴿وبه﴾ في السياق»","url":""}]},{"id":"s7-1101","number":1101,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لماذا كرر الحق ضميرًا في ﴿وبه يعدلون﴾؟","answer":"أعيد الحق ضميرًا وقدّم في ﴿وبه يعدلون﴾ لإبراز أنه الأداة والمعيار الذي يقيمون به العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص724، تحت «سر تكرار الجار والمجرور ﴿وبه﴾ في السياق»","url":""}]},{"id":"s7-1102","number":1102,"surah":7,"verses":[159],"references":[{"surah":7,"verses":[159]}],"verseLabel":"الأعراف: 159","question":"لماذا جمع بين الهداية والعدل؟","answer":"الهداية تبليغ الحق والدلالة عليه، والعدل تنفيذه في الحكم والعمل؛ فجمعوا العلم بالحق وتطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص724–725، تحت «سر ختام الآية بالعدل في قوله ﴿يعدلون﴾»","url":""}]},{"id":"s7-1103","number":1103,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعناهم اثنتي عشرة أسباطًا أممًا﴾، واستعمل «قطعنا» للتقسيم؟","answer":"﴿قطعناهم﴾ أي قسمناهم جماعات متميزة، فصوّر انفصال الأسباط بعضهم عن بعض مع بقائهم من أصل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص731، تحت «نكتة المجاز في قوله ﴿وقطعناهم﴾»","url":""}]},{"id":"s7-1104","number":1104,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا أُنّث العدد في ﴿اثنتي عشرة﴾ مع ﴿أسباطًا﴾ المذكر؟","answer":"العدد يطابق معدودًا مؤنثًا مقدرًا، أي اثنتي عشرة فرقة أو قطعة.؛ و﴿أسباطًا﴾ بدل يبين تلك الفرق، وليس تمييز العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص732–733، تحت «دلالة التأنيث في العدد اثنتي عشرة»","url":""}]},{"id":"s7-1105","number":1105,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جمع بين ﴿أسباطًا﴾ و﴿أممًا﴾؟","answer":"﴿أسباطًا﴾ تبين أن التقسيم بحسب الأنساب، و﴿أممًا﴾ تبين أن كل سبط صار جماعة مستقلة لها نظامها وشؤونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص733–734، تحت «تنكير أممًا»","url":""}]},{"id":"s7-1106","number":1106,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما أثر ﴿إذ استسقاه قومه﴾ في بيان وقت الوحي؟","answer":"فإدخاله بين الإيحاء ومضمونه يبرز اتصال الإغاثة بالطلب وعناية الله بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص734–735، تحت «فائدة دخول إذ استسقاه بين فعل الإيحاء ومضمونه»","url":""}]},{"id":"s7-1107","number":1107,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا أضيف القوم إلى موسى: ﴿قومه﴾؟","answer":"الإضافة تربطهم بنبيهم الذي طلبوا منه واستسقى لهم، وتذكر بمسؤوليته عنهم وصلتهم برسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص736–737، تحت «فائدة إضافة القوم إلى الضمير العائد في قومه»","url":""}]},{"id":"s7-1108","number":1108,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿أن اضرب بعصاك الحجر﴾، وجُعل الضرب سببًا لخروج الماء؟","answer":"جعل الضرب بالعصا سببًا ظاهرًا لخروج الماء مع أن القدرة لله، لتظهر المعجزة من اجتماع سبب لا يخرج الماء عادة بنتيجة خارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص737–738، تحت «معنى الباء في قوله ﴿بعصاك﴾»","url":""}]},{"id":"s7-1109","number":1109,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا عُرّف ﴿الحجر﴾؟","answer":"على التوجيه الذي يختاره المصدر، أل للجنس: أي اضرب أي حجر، فلا تختص المعجزة بحجر معين. وبذلك تبرز الآية أثر القدرة الإلهية في خروج الماء بالضرب بالعصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص738، تحت «معنى أل الجنس في ﴿الحجر﴾»","url":""}]},{"id":"s7-1110","number":1110,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فانبجست﴾، وفي البقرة: ﴿فانفجرت﴾؟","answer":"الانبجاس بدء خروج الماء بقلة، والانفجار خروجه بغزارة، فيمكن أن يصورا مرحلتين من النعمة. وذكر الانفجار في البقرة يبرز كمال الإنعام في مقام التذكير به وتوبيخ من لم يشكره، أما الانبجاس في الأعراف فيثبت أصل المنة بخروج الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص739، تحت «دلالة التعبير بالفعل فانبجست»","url":""}]},{"id":"s7-1111","number":1111,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما فائدة قوله: ﴿قد علم كل أناس مشربهم﴾ بعد تفجير العيون؟","answer":"جعل لكل جماعة عينًا ومشربًا تعرفه وتختص به، منعًا للتزاحم والنزاع، فصارت النعمة منظمة ظاهرة لكل سبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص740–741، تحت «فائدة إضافة المشرب إليهم»","url":""}]},{"id":"s7-1112","number":1112,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما فائدة دخول قد في قوله تعالى: ﴿قد علم كل أناس مشربهم﴾؟","answer":"﴿قد﴾ تحقق العلم، و﴿كل أناس﴾ تفيد أن كل جماعة عرفت موردها المخصص.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص741–742، تحت «فائدة دخول قد»","url":""}]},{"id":"s7-1113","number":1113,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لم نكر ﴿أناس﴾ في ﴿قد علم كل أناس مشربهم﴾؟","answer":"يفيد التنكير التكثير؛ فكل سبط جماعة كثيرة، ومع كثرتهم عرفت كل جماعة مشربها. وفي ذلك إبراز إحكام تقسيم الماء وكفايته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص741، تحت «نكتة تنكير أناس»","url":""}]},{"id":"s7-1114","number":1114,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿وظللنا عليهم الغمام﴾، فجعل الغمام مظلة؟","answer":"جعل الغمام فوقهم يحجب حر الشمس، فالفعل يصور السحاب مظلة ممتدة بعناية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص742–743، تحت «فائدة تعدية الفعل وظللنا بعلى»","url":""}]},{"id":"s7-1115","number":1115,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا اختير ﴿الغمام﴾ لا «السحاب»؟","answer":"الغمام من الغم بمعنى الستر، فناسب التعبير به عن التظليل وحجب الشمس. أما السحاب فيلحظ في تسميته معنى السحب والحركة، فاختير ما يبرز وظيفة الستر في هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص750–751، تحت «الغمام والسحاب»","url":""}]},{"id":"s7-1116","number":1116,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جمع بين الماء والظل والمن والسلوى في آية واحدة؟","answer":"جمعت مقومات بقائهم في الصحراء: الماء للشرب، والغمام للوقاية، والمن والسلوى للطعام؛ فتكامل الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص745–746، تحت «بلاغة ترتيب ذكر النعم»","url":""}]},{"id":"s7-1117","number":1117,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"كيف يُشرح بلاغيًا المفردات: المن والسلوى في قوله تعالى: ﴿وأنزلنا عليهم المن والسلوى﴾؟","answer":"﴿أنزلنا﴾ يفيد أن الرزق جاءهم من فوق من غير كسب معتاد، و﴿عليهم﴾ تشعر بإحاطته وكثرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص729–730، تحت «شرح المفردات: المن والسلوى»","url":""}]},{"id":"s7-1118","number":1118,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جاء الأمر: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"الأمر للإباحة والامتنان: انتفعوا بالحلال المستطاب الذي رزقكم الله، وفي إضافة الرزق إليه تذكير بالمنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص744–745، تحت «دلالة فعل الأمر كلوا في الآية»","url":""}]},{"id":"s7-1120","number":1120,"surah":7,"verses":[160,177],"references":[{"surah":7,"verses":[160,177]}],"verseLabel":"الأعراف: 160؛ الأعراف: 177","question":"ما دلالة تقديم ﴿أنفسهم﴾ في قوله تعالى: ﴿وأنفسهم كانوا يظلمون﴾؟","answer":"يفيد التقديم قصر ظلمهم على أنفسهم واختصاص ضرره بهم؛ فتكذيبهم لا يتعدى أثره إلى الله ولا يضر غيرهم، وإنما ترجع عاقبته عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص177، تحت «بلاغة القصر بتقديم المفعول به: ﴿وأنفسهم﴾»","url":""}]},{"id":"s7-1121","number":1121,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا جرت آية الأعراف أولًا بضمير الغيبة: ﴿وقطعناهم... وأوحينا... استسقاه قومه﴾، ثم التفتت إلى الخطاب: ﴿كلوا من طيبات ما رزقناكم﴾؟","answer":"بدأت القصة حكايةً عن أسلاف المخاطبين بضمير الغيبة، ثم التفتت إلى خطابهم في النعمة والتكليف ليشعر السامعون أنهم معنيون بالشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-1122","number":1122,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا خوطب بنو إسرائيل في البقرة بقوله: ﴿وظللنا عليكم... وأنزلنا عليكم﴾، وحُكي عنهم في الأعراف بضمير الغيبة: ﴿وظللنا عليهم... وأنزلنا عليهم﴾؟","answer":"البقرة تخاطب بني إسرائيل مباشرة في مقام تعداد نعم الله عليهم، أما الأعراف فتسرد قصتهم للنبي ﷺ والأمة، فغلب فيها ضمير الغيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص470، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-1123","number":1123,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"لماذا ذُكر في البقرة: ﴿كلوا واشربوا من رزق الله﴾، ولم يذكر الشرب في آية الأعراف؟","answer":"جمعت البقرة: 60 الأكل والشرب لتجمع التذكير بالنعم وتبرز كمال الإكرام بعد تفجر العيون. أما ﴿كلوا من طيبات ما رزقناكم﴾ في الأعراف فمتصل بذكر المن والسلوى، وهو الأمر الذي جاء أيضًا في البقرة: 57 بعد ذكرهما؛ فكل تعبير منظور فيه إلى موضعه وسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص497–499، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s7-1124","number":1124,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وإذ قيل لهم اسكنوا هذه القرية﴾، وفي البقرة: ﴿وإذ قلنا ادخلوا هذه القرية﴾؟","answer":"في الأعراف أوجز بذكر ﴿قيل﴾ لعلم القائل، وفي البقرة صرح بإسناد القول إلى الله. والدخول أول الوصول إلى القرية، أما السكن فالإقامة فيها بعد الدخول؛ فكل سورة تذكر من القصة ما يلائم مقامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773–774، تحت «فائدة التعبير بفعل الأمر اسكنوا»","url":""}]},{"id":"s7-1125","number":1125,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"لماذا بُني ﴿قيل﴾ للمجهول هنا، وأُسند القول إلى الله في البقرة؟","answer":"بناء ﴿قيل﴾ للمجهول يوجز الحكاية لأن القائل معلوم، أما ﴿قلنا﴾ في البقرة فيبرز المنعم ضمن سياق الامتنان المباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص755، تحت «نكتة بناء الفعل قيل لما لم يسم فاعله»","url":""}]},{"id":"s7-1126","number":1126,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿اسكنوا﴾ هنا و﴿ادخلوا﴾ في البقرة؟","answer":"﴿ادخلوا﴾ يلحظ ابتداء الوصول إلى القرية، و﴿اسكنوا﴾ يلحظ الإقامة والاستقرار فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص756–757، تحت «فائدة التعبير بفعل الأمر اسكنوا»","url":""}]},{"id":"s7-1127","number":1127,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلوا منها حيث شئتم﴾، وفي البقرة: ﴿فكلوا منها حيث شئتم رغدًا﴾؟","answer":"وفي الأعراف عطف الأكل بالواو على السكن لتلازمهما في حال الاستقرار، فذكر كل موضع ما يلائم الحال التي يصورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص757–758، تحت «دلالة العطف في فعل الأمر، من اسكنوا وكلوا منها»","url":""}]},{"id":"s7-1128","number":1128,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"لماذا حُذفت ﴿رغدًا﴾ في الأعراف؟","answer":"يذكر المصدر أن موضع البقرة يتحدث عن ابتداء الدخول، فصرح برغد الأكل فيه إظهارًا لمزيد الامتنان. أما الأعراف فذكرت حال السكن والاستقرار، حيث يكون الأكل معتادًا ملازمًا للإقامة، فاستغنت عن هذه الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773، 775، تحت «بلاغة المتشابه اللفظي بين آيتي الأعراف161 و162 وآيتي البقرة58 و59»","url":""}]},{"id":"s7-1129","number":1129,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ تقديم هنا ﴿قولوا حطة﴾ على ﴿وادخلوا الباب سجدًا﴾، وعُكس الترتيب في البقرة؟","answer":"في الأعراف قدم طلب المغفرة ثم ذكر الدخول خاضعين، فيقترن الاعتراف بالذنب بهيئة التواضع.؛ ويبين اختلاف الترتيب في السورتين، مع العطف بالواو، أن المطلوب جمع القول والخضوع من غير إلزام بتقديم أحدهما على الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص762، تحت «نكتة تأخير الدخول على لفظ حطة»","url":""}]},{"id":"s7-1130","number":1130,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما دلالة الأمر بكلمة واحدة: ﴿حطة﴾؟","answer":"﴿حطة﴾ كلمة جامعة، أي مسألتنا حط خطايانا عنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص760–761، تحت «بلاغة الإيجاز في قوله حطة»","url":""}]},{"id":"s7-1131","number":1131,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وادخلوا الباب سجدًا﴾، وكيف يكون الدخول سجودًا؟","answer":"أي ادخلوا خاضعين منحنين أو حال كونكم سجدًا عند الباب؛ فالسجود وصف لهيئتهم الدالة على التواضع، لا لعملية المشي نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص763، تحت «بلاغة التعبير بسجدًا، ودلالتها على الحال»","url":""}]},{"id":"s7-1132","number":1132,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿نغفر لكم خطيئاتكم﴾، وفي البقرة: ﴿نغفر لكم خطاياكم﴾؟","answer":"يذكر المصدر أن اختلاف صيغ الجمع يوسع الوعد بالمغفرة، فيشمل الذنوب قليلة كانت أو كثيرة متى امتثلوا الأمر وتابوا.؛ فصيغة جمع القلة لا تحصر المغفرة في القليل، كما تدل صيغة الكثرة على سعة العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص764–765، تحت «نكتة جمع لفظ خطيئاتكم»","url":""}]},{"id":"s7-1133","number":1133,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿سنزيد المحسنين﴾ من غير واو، وفي البقرة: ﴿وسنزيد المحسنين﴾؟","answer":"في الأعراف استؤنفت جملة ﴿سنزيد﴾ وعدًا مستقلًا، أما الواو في البقرة فعطفت الزيادة على المغفرة ضمن تعداد النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص765، تحت «نكتة ترك العطف في قوله سنزيد المحسنين»","url":""}]},{"id":"s7-1134","number":1134,"surah":7,"verses":[161],"references":[{"surah":7,"verses":[161]}],"verseLabel":"الأعراف: 161","question":"لماذا تجاوز الوعد المغفرة إلى الزيادة للمحسنين؟","answer":"المغفرة ترفع أثر الإساءة، ثم الزيادة تمنح المحسنين فضلًا فوق مجرد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص765–766، تحت «نكتة ترك العطف في قوله سنزيد المحسنين»","url":""}]},{"id":"s7-1135","number":1135,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿فبدل الذين ظلموا منهم﴾، وزاد ﴿منهم﴾ خلاف موضع البقرة؟","answer":"﴿منهم﴾ للتبعيض.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص768–769، تحت «معنى من في قوله منهم»","url":""}]},{"id":"s7-1136","number":1136,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا وُصف المبدّلون بـ﴿الذين ظلموا﴾؟","answer":"وصفهم بالظلم لأنهم وضعوا القول والفعل في غير موضعهما، فكان التبديل مظهرًا من ظلمهم لا مجرد خطأ لفظي.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص767–768، تحت «نكتة مجيء جملة صلة الموصول الذين ظلموا»","url":""}]},{"id":"s7-1137","number":1137,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما أثر تنكير ﴿قولًا﴾ ووصفه بـ﴿غير الذي قيل لهم﴾؟","answer":"يفيد التنكير تحقير القول الذي اختاروه، والوصف بالمغايرة يحقق أنهم خالفوا المأمور به واستبدلوا به غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص769–770، تحت «نكتة تنكير لفظ قولًا»","url":""}]},{"id":"s7-1138","number":1138,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا كرر مادة القول: ﴿قولًا غير الذي قيل لهم﴾؟","answer":"الأول مفعول يبين أنهم استبدلوا قولًا، والثاني في الصلة يذكر القول المأمور به؛ فتقابل القولان وظهر التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص769–770، تحت «فائدة التعبير بالاسم الموصول وصلته في الذي قيل لهم»","url":""}]},{"id":"s7-1139","number":1139,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿فأرسلنا عليهم رجزًا﴾ لا «فأنزلنا»؟","answer":"يفيد الإرسال توجيه العذاب إليهم، وقد ضمن هنا معنى الإنزال لأنه أرسل من فوق.؛ ويذكر المصدر في المقارنة أن الإنزال لا يشعر بالكثرة بذاته، أما الإرسال فيتصور معه بدء العذاب ثم تتابعه، فتبرز صورة التسليط.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص771، تحت «نكتة تعدية الإرسال بعلى»","url":""}]},{"id":"s7-1140","number":1140,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا عُدي الرجز بـ﴿عليهم﴾؟","answer":"﴿عليهم﴾ تصور الرجز نازلًا مستوليًا محيطًا بهم من فوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص771–772، تحت «نكتة تعدية الإرسال بعلى»","url":""}]},{"id":"s7-1141","number":1141,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"لماذا قُيد الرجز بأنه ﴿من السماء﴾؟","answer":"لتأكيد أن العذاب جاء من جهة لا يملكون دفعها وبأمر إلهي، لا من سبب أرضي مألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص772–773، تحت «معنى من في قوله من السماء»","url":""}]},{"id":"s7-1143","number":1143,"surah":7,"verses":[162],"references":[{"surah":7,"verses":[162]}],"verseLabel":"الأعراف: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿كانوا يظلمون﴾ لا «ظلموا»؟","answer":"﴿كانوا يظلمون﴾ تفيد أن الظلم كان دأبًا متكررًا راسخًا، لا واقعة تبديل منفردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص773، تحت «سر وجود كانوا مع الخبر يظلمون»","url":""}]},{"id":"s7-1144","number":1144,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما دلالة تعريف ﴿القرية﴾ في ﴿واسألهم عن القرية﴾؟","answer":"التعريف للعهد؛ فهو يسألهم عن قرية معروفة لديهم، وعن خبر أهلها الذي يذكرهم باعتدائهم. ويعينها المصدر بأيلة، ويجعل السؤال عن أحوال أهلها لا عن ذات القرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص785، تحت «معنى أل في القرية والمراد بها»","url":""}]},{"id":"s7-1145","number":1145,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا أُمر النبي أن يسألهم مع أن الله سيقص الخبر؟","answer":"السؤال للتقرير والتوبيخ؛ يجعل المخاطبين يقرون بما يعرفونه من خبر أسلافهم، فتكون مشاركتهم في تقريره أبلغ في الحجة. وإخبار النبي ﷺ به دليل على الوحي، لا طلب علم بما يجهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص783–784، تحت «سر العدول من الإخبار إلى السؤال»","url":""}]},{"id":"s7-1146","number":1146,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا وُصفت القرية بأنها ﴿كانت حاضرة البحر﴾؟","answer":"الوصف يبين سبب الفتنة: قربها من البحر جعل الصيد موردًا ظاهرًا، وكانت الحيتان تحضر عند الساحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص786، تحت «سر وصف القرية بأنها حاضرة البحر»","url":""}]},{"id":"s7-1147","number":1147,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿حاضرة البحر﴾ لا «على البحر»؟","answer":"﴿حاضرة البحر﴾ أي قريبة منه ومجاورة له؛ ففيه بيان الصلة بين مكان القرية وما سيقع لأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص786، تحت «سر وصف القرية بأنها حاضرة البحر»","url":""}]},{"id":"s7-1148","number":1148,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ يعدون في السبت﴾، وما دلالة العدوان «في» السبت؟","answer":"﴿في السبت﴾ يدل على وقوع العدوان داخل حرمة اليوم وأحكامه؛ فقد تجاوزوا النهي عن الصيد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص788، تحت «دلالة تقييد قوله يعدون في السبت»","url":""}]},{"id":"s7-1149","number":1149,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا كرر ﴿إذ﴾: ﴿إذ يعدون... إذ تأتيهم حيتانهم﴾؟","answer":"الأولى تحدد زمن عدوانهم، والثانية تفصل صورة الابتلاء الذي وقع في ذلك الزمن؛ فتكرار ﴿إذ﴾ ينقل إلى مشهد أدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص787–789، تحت «الموقع النحوي والبياني لجملة إذ يعدون في السبت؛ الموقع النحوي والبياني لإتيان الحيتان»","url":""}]},{"id":"s7-1150","number":1150,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا أضيفت الحيتان إليهم: ﴿حيتانهم﴾؟","answer":"الإضافة تربط الحيتان بموضعهم وبما هيئ لهم من الرزق؛ فهي الحيتان الكائنة في ناحيتهم والمخلوقة لمنفعتهم. وبهذا تبرز شدة تعلق الابتلاء بمورد معاشهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص789، تحت «نكتة إضافة الحيتان إليهم»","url":""}]},{"id":"s7-1151","number":1151,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير بقوله تعالى: ﴿يوم سبتهم﴾ فأضيف السبت إليهم؟","answer":"إضافته إليهم لأنه اليوم الذي خصص لهم وفرض عليهم تعظيمه، فازدادت مسؤوليتهم عن انتهاكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص789، تحت «دلالة إضافة السبت إليهم»","url":""}]},{"id":"s7-1152","number":1152,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا وصف مجيء الحيتان بـ﴿شرعًا﴾؟","answer":"﴿شرعًا﴾ أي ظاهرة مرتفعة قريبة على وجه الماء، كأنها شارعة رؤوسها، فاشتد الإغراء والابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص789–790، تحت «بلاغة الكناية في قوله شرعًا»","url":""}]},{"id":"s7-1153","number":1153,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا قابل ﴿يوم سبتهم﴾ بـ﴿ويوم لا يسبتون لا تأتيهم﴾؟","answer":"تقابل الآية بين مجيء الحيتان ظاهرة قريبة يوم السبت، وانتفاء مجيئها في غيره على هذا التوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص791–792، تحت «نكتة إضافة لفظ اليوم إلى لا يسبتون»","url":""}]},{"id":"s7-1154","number":1154,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا كرر النفي في ﴿لا يسبتون لا تأتيهم﴾؟","answer":"فلكل نفي متعلَّق مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص791–792، تحت «موقع قوله لا تأتيهم ومعنى النفي في هذا السياق»","url":""}]},{"id":"s7-1155","number":1155,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك نبلوهم﴾، وإلى ماذا تشير الكاف؟","answer":"الكاف تشير إلى هذا الابتلاء العجيب بإظهار الحيتان يوم المنع وحجبها يوم الحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص792–793، تحت «معنى الكاف في كذلك ودلالتها على التشبيه»","url":""}]},{"id":"s7-1156","number":1156,"surah":7,"verses":[163],"references":[{"surah":7,"verses":[163]}],"verseLabel":"الأعراف: 163","question":"لماذا عبّر بالمضارع ﴿نبلوهم﴾ عن ابتلاء ماضٍ؟","answer":"المضارع يستحضر صورة الابتلاء المتكرر كل أسبوع، كأنه يجري أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص793، تحت «سر التعبير بالمضارع نبلوهم»","url":""}]},{"id":"s7-1158","number":1158,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا بدأت الآية بـ﴿وإذ قالت أمة منهم﴾ مع أن الجماعات لم تُذكر بعد؟","answer":"افتتحت بـ﴿وإذ﴾ لاستحضار موقف جديد، وظهرت ﴿أمة﴾ أولًا تمهيدًا لانقسام أهل القرية إلى معتدين وواعظين وساكتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص21، تحت عنوان «بلاغة الإيجاز في التعبير عن انقسام أهل القرية إلى ثلاث فرق»","url":""}]},{"id":"s7-1159","number":1159,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا نُكرت ﴿أمة﴾؟","answer":"يذكر المصدر أن التنكير يحتمل التقليل، إشارة إلى أن الفئة المثبطة للواعظين قليلة، ويحتمل التحقير لذم موقفها من تعطيل عمل المصلحين. فالتركيز على تقويم الموقف الذي اتخذته هذه الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص12–13، تحت «فائدة تنكير لفظ أمة»","url":""}]},{"id":"s7-1160","number":1160,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما دلالة استفهامهم: ﴿لم تعظون قومًا﴾؟","answer":"الاستفهام إنكاري عند القائلين؛ يستبعدون فائدة وعظ قوم يظنون أن العقوبة واقعة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص13، تحت «بلاغة الاستفهام الإنكاري وغرضه»","url":""}]},{"id":"s7-1161","number":1161,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا نُكّر ﴿قومًا﴾ مع أنهم معروفون؟","answer":"يحمل التنكير معنى التحقير لهؤلاء المعتدين، ويذكر المصدر معه معنى التكثير بالنظر إلى كثرة الفئة وما تكرر في تاريخهم من العصيان. فهو يصور قبح حالهم وشدة إصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص14، تحت «نكتة تنكير قومًا»","url":""}]},{"id":"s7-1162","number":1162,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما دلالة عطف معذبهم على مهلكهم؟","answer":"تفيد أو تنويع الوعيد: إهلاك بالاستئصال أو عذاب شديد دونه، ويذكر المصدر أيضًا احتمال الإهلاك في الدنيا والعذاب في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص16–17، تحت عنوان «دلالة عطف معذبهم على مهلكهم»","url":""}]},{"id":"s7-1621","number":1621,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما معنى أو ودلالتها؟","answer":"ليست أو هنا مانعة من اجتماع الجزاءين، والمقام تأكيد سوء العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص16–17، تحت عنوان «معنى أو ودلالتها»","url":""}]},{"id":"s7-1163","number":1163,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا جاء ﴿مهلكهم﴾ و﴿معذبهم﴾ باسم الفاعل؟","answer":"اسم الفاعل يستحضر العقوبة كأمر متوقع ثابت الوقوع، لا احتمالًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص15، تحت «نكتة التعبير باسم الفاعل»","url":""}]},{"id":"s7-1164","number":1164,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما سرّ قولهم: ﴿عذابًا شديدًا﴾ بعد ﴿معذبهم﴾؟","answer":"المصدر المؤكد ﴿عذابًا﴾ مع وصفه بالشدة يفخم نوع التعذيب بعد ذكر فاعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص17، تحت «غرض تأكيد العذاب بالمفعول المطلق ووصفه بالشدة دون الإهلاك»","url":""}]},{"id":"s7-1165","number":1165,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما دلالة جواب الواعظين بكلمة ﴿معذرة﴾؟","answer":"أي نعظهم إقامةً لمعذرتنا عند ربكم وأداءً لواجب النهي، ولو لم نر أثرًا عاجلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص20، تحت «بلاغة التعبير بـ﴿معذرة﴾»","url":""}]},{"id":"s7-1166","number":1166,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما الفرق الدلالي بين قراءتي ﴿معذرةٌ﴾ بالرفع و﴿معذرةً﴾ بالنصب؟","answer":"بالرفع: خبر لمبتدأ محذوف، أي موعظتنا معذرة ثابتة؛ وبالنصب: نعظهم معذرةً، أي لأجل الاعتذار. والقراءتان تجمعان ثبوت المعذرة وكونها غاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص19–20، تحت «التوجيه البلاغي والنحوي للقراءات المتواترة في معذرة»","url":""}]},{"id":"s7-1167","number":1167,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"ما سرّ تعبيرهم: ﴿إلى ربكم﴾ لا «إلى ربنا»؟","answer":"خاطبوهم بـ﴿ربكم﴾ تذكيرًا بأنهم أيضًا مسؤولون أمام الرب عن ترك الإنكار، مع أن ربهم وربنا واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص20–21، تحت «نكتة التعبير بالربوبية وإضافته إليهم»","url":""}]},{"id":"s7-1168","number":1168,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"لماذا عطفوا ﴿ولعلهم يتقون﴾ على ﴿معذرة إلى ربكم﴾؟","answer":"لم يحصروا الغاية في إعذار أنفسهم، بل أبقوا باب رجوع المعتدين مفتوحًا؛ فالوعظ واجب ورجاء التقوى قائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص21–22، تحت «نكتة العطف ودلالاته في ولعلهم يتقون»","url":""}]},{"id":"s7-1169","number":1169,"surah":7,"verses":[164],"references":[{"surah":7,"verses":[164]}],"verseLabel":"الأعراف: 164","question":"كيف يُفهم رجاؤهم ﴿لعلهم يتقون﴾ مع قول الآخرين إن الله مهلكهم؟","answer":"لم يقطع الواعظون بإهلاكهم، بل رجوا أثر النصيحة؛ لأن القلوب بيد الله، وغاية الناصح البلاغ مع عدم اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص22–23، تحت «نكتة مجيء حرف الرجاء لعل»","url":""}]},{"id":"s7-1170","number":1170,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما نسوا ما ذكروا به﴾، وهل كان نسيانًا حقيقيًا؟","answer":"النسيان هنا ترك متعمد وإعراض حتى صار المذكَّر به كأنه منسي، لا ذهاب المعلومة من الذاكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص28، تحت «بلاغة المجاز في قوله فلما نسوا ما ذكروا به»","url":""}]},{"id":"s7-1171","number":1171,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا بُني ﴿ذُكّروا﴾ للمجهول؟","answer":"بني للمجهول لأن العناية بالموعظة التي أعرضوا عنها، لا باسم الواعظ، وقد عرف من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص29، تحت «نكتة مجيء جملة صلة الموصول بالفعلية المبنية لما لم يسم فاعله»","url":""}]},{"id":"s7-1172","number":1172,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿أنجينا الذين ينهون عن السوء﴾، فوصفهم بالمضارع؟","answer":"المضارع ﴿ينهون﴾ يبين أنهم داوموا على النهي عن السوء ولم تكن موعظتهم موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص29–30، تحت «نكتة مجيء الاسم الموصول وصلته الذين ينهون»","url":""}]},{"id":"s7-1173","number":1173,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا سمّى فعل المعتدين ﴿السوء﴾؟","answer":"سماه سوءًا لجمع قبائح العدوان والتحايل والمعصية في وصف يظهر شدة قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص31، تحت عنوان «معنى أل في السوء»","url":""}]},{"id":"s7-1174","number":1174,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا نصت الآية على نجاة الناهين وعذاب الظالمين وسكتت عن الفرقة التي قالت: ﴿لم تعظون﴾؟","answer":"يعرض المصدر خلاف المفسرين في مصير هذه الفرقة: فمنهم من ألحقها بالهالكين لترك النهي، ومنهم من عدها ناجية، ومنهم من رأى أن السكوت عنها يفيد التبكيت والتقليل من شأنها لسكوتها عن الحق. لذلك لا يحمل هذا الموضع على قول واحد بوصفه محل اتفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص30، تحت «بلاغة الحذف أو الذكر لجزاء الفريق الثالث القائل لم تعظون قومًا»","url":""}]},{"id":"s7-1175","number":1175,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا قابل ﴿أنجينا﴾ بـ﴿وأخذنا﴾؟","answer":"الإنجاء إبعاد أهل النهي عن العذاب، والأخذ استيلاء العقوبة على الظالمين؛ فتقابلت النجاة والإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص31، تحت عنوان «بلاغة العطف في وأخذنا»","url":""}]},{"id":"s7-1176","number":1176,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"لماذا أعيد وصف المعتدين بـ﴿الذين ظلموا﴾؟","answer":"أعاد الموصول لتسجيل سبب الأخذ عليهم وإبراز أن العدوان ظلم مستحق للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص32–33، تحت عنوان «نكتة التعبير بالاسم الموصول في الذين ظلموا»","url":""}]},{"id":"s7-1177","number":1177,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿بعذاب بئيس﴾، وما معنى «بئيس»؟","answer":"﴿بئيس﴾ شديد موجع ذو بؤس، فجاء الوصف ملائمًا لأخذ لا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص33–34، تحت عنوان «معاني القراءات في بئيس»","url":""}]},{"id":"s7-1178","number":1178,"surah":7,"verses":[165],"references":[{"surah":7,"verses":[165]}],"verseLabel":"الأعراف: 165","question":"ما أثر القراءات المتعددة في لفظ ﴿بئيس﴾؟","answer":"تتنوع أوجه القراءة في اللفظ مع تقاربها في وصف العذاب بالشدة والإيلام. ويبين المصدر أنها ترجع، مع اختلاف الألسنة واللهجات، إلى تفظيع هذا العذاب؛ فتتكامل دلالتها ولا تتعارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص33–34، تحت «معاني القراءات في بئيس»","url":""}]},{"id":"s7-1180","number":1180,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما عتوا عما نهوا عنه﴾ لا «لما عصوا»؟","answer":"العتو تجاوز الحد باستكبار وصلابة، فهو أبلغ من مطلق العصيان، ويصور إصرارهم بعد النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص45، تحت عنوان «العتو والعثو»","url":""}]},{"id":"s7-1182","number":1182,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"لماذا بُني ﴿نهوا﴾ للمجهول؟","answer":"بني للمجهول لأن المقصود عتوهم عن النهي نفسه بعد قيامه عليهم، لا تعيين من باشره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص38، تحت «نكتة مجيء جملة صلة الموصول بالفعلية لما لم يسم فاعله»","url":""}]},{"id":"s7-1183","number":1183,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿كونوا قردة﴾ بفعل الكون؟","answer":"الأمر التكويني بـ﴿كونوا﴾ أنشأ تحولهم فورًا إلى الحال المذكورة، لا أنه تكليف يملكون رفضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص39–40، تحت عنوان «دلالة الأمر بكونوا»","url":""}]},{"id":"s7-1184","number":1184,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"لماذا نُكرت ﴿قردة﴾؟","answer":"التنكير للتحقير والتهوين من شأنهم؛ إذ انتهوا بسبب عصيانهم إلى هذه الحال المهينة. فهو يبرز ما لحقهم من الصغار بعد تمردهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص40، تحت «نكتة تنكير قردة»","url":""}]},{"id":"s7-1185","number":1185,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"لماذا وُصفوا بـ﴿خاسئين﴾ بعد مسخهم قردة؟","answer":"﴿خاسئين﴾ أي مبعدين أذلاء صاغرين؛ فالمسخ لم يكن تغير صورة فقط، بل عقوبة مهينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص40–41، تحت «غرض الوصف بخاسئين»","url":""}]},{"id":"s7-1186","number":1186,"surah":7,"verses":[166],"references":[{"surah":7,"verses":[166]}],"verseLabel":"الأعراف: 166","question":"ما الفرق بين هذا السياق وقوله في البقرة: ﴿كونوا قردة خاسئين﴾؟","answer":"البقرة تذكر المسخ عقب بيان علم المخاطبين بالقصة ضمن تعداد النعم والنقم، والأعراف تفصّل مقدماته من الابتلاء والوعظ والعتو؛ أما عبارة الحكم فواحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص41–42، تحت «بلاغة المتشابه اللفظي في قصة أصحاب السبت»","url":""}]},{"id":"s7-1187","number":1187,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ تأذن ربك﴾ لا «وإذ أذن»؟","answer":"﴿تأذن﴾ بمعنى أعلم إعلامًا مؤكدًا أو عزم وقضى، وصيغة التفعل تشعر بإظهار الإعلان وتحققه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص49–50، تحت «بلاغة التعبير بتأذن»","url":""}]},{"id":"s7-1188","number":1188,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا أضيف الرب إلى النبي ﷺ: ﴿ربك﴾ في خبر بني إسرائيل؟","answer":"إضافة الرب إلى النبي ﷺ تسلية له وبيان أن مدبر تاريخ بني إسرائيل هو ربه الذي يتولى أمر رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص50، تحت «نكتة مجيء وصف الربوبية وإضافته إلى ضميره ﷺ»","url":""}]},{"id":"s7-1189","number":1189,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا أكد الوعيد باللام والنون: ﴿ليبعثن عليهم﴾؟","answer":"اللام ونون التوكيد الثقيلة تقرران حتمية استمرار هذا الوعيد وعدم تخلفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص50، تحت «بلاغة توالي المؤكدات في ليبعثن»","url":""}]},{"id":"s7-1190","number":1190,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا اختير ﴿ليبعثن﴾ لا «ليسلطن»؟","answer":"البعث إرسال وإثارة متجددة؛ يفيد أن الله يقيم عليهم في أزمنة مختلفة من يسومهم العذاب، وهو أوسع من تسليط واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص50–51، تحت «معنى البعث وغرض تعديته بعلى»","url":""}]},{"id":"s7-1191","number":1191,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما فائدة مجيء القيد إلى يوم القيامة في قوله تعالى: ﴿إلى يوم القيامة﴾؟","answer":"يفيد استمرار أثر الوعيد في تاريخهم إلى قيام الساعة، لا حادثة منقطعة في زمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص51–52، تحت عنوان «فائدة مجيء القيد إلى يوم القيامة»","url":""}]},{"id":"s7-1192","number":1192,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿من يسومهم سوء العذاب﴾ ولم يذكر الفاعل؟","answer":"أبهم الفاعل ليعم كل من يبعثه الله عليهم في العصور المختلفة، فالعبرة بدوام سنة العقوبة لا باسم أمة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص51–52، تحت عنوان «معنى من في من يسومهم»","url":""}]},{"id":"s7-1193","number":1193,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما دلالة الاستعارة في التعبير عن معاملتهم بالسوم؟","answer":"يصور السوم دوام الإذلال والتسخير، ويشبّه معاملتهم بمعاملة الأنعام التي يسوقها صاحبها لما يريد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص52–53، تحت عنوان «بلاغة الاستعارة في التعبير عن معاملتهم بالسوم»","url":""}]},{"id":"s7-1622","number":1622,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سر التعبير بالسوم مادة وصيغة؟","answer":"يستحضر المضارع تجدد هذه المعاملة واستمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص52–53، تحت عنوان «بلاغة التعبير بالسوم مادة وصيغة»","url":""}]},{"id":"s7-1194","number":1194,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا ختم الوعيد بـ﴿إن ربك لسريع العقاب وإنه لغفور رحيم﴾؟","answer":"جمع بين سرعة العقاب لمن أصر، والمغفرة والرحمة لمن تاب، حتى لا يأمن العاصي ولا ييأس الراجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص55، تحت عنوان «غرض تتابع وصفين في سياق الوعد إزاء وصف واحد في سياق الوعيد»","url":""}]},{"id":"s7-1195","number":1195,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿سريع العقاب﴾ مع امتداد العقوبة إلى القيامة؟","answer":"تدل السرعة على نفاذ أمر الله من غير تردد أو عجز، ويذكر المصدر أيضًا أنها تفيد تحقق الوقوع؛ فما هو آت محقق لا يخرجه تأخر وقته عن ذلك. فلا تعارض بين سرعة النفاذ والتحقق وبين امتداد زمن الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54، تحت «نكتة وصف العقاب بالسرعة»","url":""}]},{"id":"s7-1196","number":1196,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"لماذا أظهر ﴿ربك﴾ أولًا ثم أضمر في ﴿وإنه﴾؟","answer":"أظهر ﴿ربك﴾ لإبراز وصف الربوبية وتثبيت النبي ﷺ، ثم عاد الضمير لاتضاح المرجع وتجنب التكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54–55، تحت عنوان «نكتة الإضمار بعد الإظهار في وإنه»","url":""}]},{"id":"s7-1197","number":1197,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما غرض تتابع وصفين في سياق الوعد إزاء وصف واحد في سياق الوعيد؟","answer":"زاد في الوعد وصفين في مقابل وصف واحد في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54–55، تحت عنوان «غرض تتابع وصفين في سياق الوعد إزاء وصف واحد في سياق الوعيد»","url":""}]},{"id":"s7-1623","number":1623,"surah":7,"verses":[167],"references":[{"surah":7,"verses":[167]}],"verseLabel":"الأعراف: 167","question":"ما غرض تقديم الوعيد على الوعد؟","answer":"قدم الوعيد موافقة لما سبق من ذكر العقوبة، ثم أعقبه بالمغفرة والرحمة ترغيبًا في التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص54–55، تحت عنوان «غرض تقديم الوعيد على الوعد»","url":""}]},{"id":"s7-1198","number":1198,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿وقطعناهم في الأرض أممًا﴾، واستعار التقطيع للتفريق؟","answer":"صور تفريقهم في نواحي الأرض كتقطيع الشيء الواحد إلى قطع متباعدة، فدل على شدة التفرق بعد اجتماع الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص60–61، تحت «بلاغة الاستعارة في قوله وقطعناهم»","url":""}]},{"id":"s7-1199","number":1199,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿في الأرض﴾، وفي الآية 160: ﴿اثنتي عشرة أسباطًا أممًا﴾؟","answer":"في الآية 160 كان التقسيم المنظم إلى اثنتي عشرة جماعة، أما هنا فالكلام على تفريقهم في أقطار الأرض أممًا شتى؛ فزاد قيد المكان لبيان الانتشار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص61، تحت عنوان «بلاغة الاستعارة في قوله وقطعناهم»","url":""}]},{"id":"s7-1200","number":1200,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا جُمعت ﴿أممًا﴾؟","answer":"جُمعت لاختلاف جماعاتهم ومواطنهم وأحوالهم بعد تفريقهم في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص62، تحت عنوان «نكتة تنكير أممًا»","url":""}]},{"id":"s7-1201","number":1201,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا قدّم ﴿منهم الصالحون﴾ على ﴿ومنهم دون ذلك﴾؟","answer":"بدأ بالصالحين إنصافًا لهم وتنويهًا بشأنهم، حتى لا يعمم الذم على بني إسرائيل كلهم، ثم ذكر من انحط عن درجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص62، تحت عنوان «الموقع البياني والنحوي لقوله منهم الصالحون ومنهم دون ذلك»","url":""}]},{"id":"s7-1202","number":1202,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿ومنهم دون ذلك﴾، دون أن يقال: ومنهم الفاسقون؟","answer":"التعبير يجعل الصلاح منزلة عليا وما عداه دونها؛ فيبرز علو مرتبة الصالحين، مهما كان لغيرهم من قوة أو مال. وهو أوسع من تسمية وصف واحد للمخالفين، إذ يجمعهم هنا كونهم أدنى من منزلة الصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص63–64، تحت عنوان «سر المقابلة بين الصالحون ودون ذلك»","url":""}]},{"id":"s7-1203","number":1203,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا استعمل اسم الإشارة ﴿ذلك﴾ في ﴿دون ذلك﴾؟","answer":"يشير ذلك إلى مقام الصالحين، واستعمل البعد الحسي للدلالة على بعد المنزلة وعلوها. فالصلاح مرتبة رفيعة، ومن خالفه دونها مهما تفاوتت أحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص64، تحت «نكتة التعبير باسم الإشارة للبعيد ذلك»","url":""}]},{"id":"s7-1204","number":1204,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما معنى أل في الحسنات والسيئات في قوله تعالى: ﴿وبلوناهم بالحسنات والسيئات﴾؟","answer":"اختبرهم الله بالنعم والنقم معًا؛ فالحسنات تمتحن الشكر، والسيئات تمتحن الصبر وتدعو إلى التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص65، تحت عنوان «معنى أل في الحسنات والسيئات»","url":""}]},{"id":"s7-1205","number":1205,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا عُدّي البلاء بالباء في ﴿بالحسنات والسيئات﴾؟","answer":"الباء للسببية على توجيه المصدر؛ فبالحسنات والسيئات تحقق اختبارهم وظهرت أحوالهم. فالنعم والنقم وسيلتان يتبين بهما الشكر والصبر أو خلافهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص64–65، تحت «معنى الباء في بالحسنات»","url":""}]},{"id":"s7-1206","number":1206,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا قدّم الحسنات على السيئات هنا، وقدمت الشدة في مواضع أخرى؟","answer":"قدم الحسنات هنا لأن السياق يذكر نعم الله عليهم، ولملاءمة تقديم الصالحين قبل قوله ﴿ومنهم دون ذلك﴾. أما الموضع الذي قدم فيه الشر على الخير فمقامه مختلف، وقد تقدم فيه ذكر الموت؛ فترتيب طرفي الابتلاء يتبع السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص65، تحت «نكتة تقديم البلاء بالحسنات على السيئات»","url":""}]},{"id":"s7-1207","number":1207,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"لماذا خُتم بـ﴿لعلهم يرجعون﴾؟","answer":"جعل غاية تنويع الابتلاء رجوعهم عن العصيان إلى الطاعة، فليس المقصود مجرد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص65–66، تحت عنوان «نكتة فصل لعلهم يرجعون عن سابقتها»","url":""}]},{"id":"s7-1208","number":1208,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما نكتة حذف متعلق يرجعون؟","answer":"حذف متعلقه ليشمل الرجوع عن المعاصي وما يندرج فيها، وتفيد المضارعة تجدد الدعوة إلى ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص66–67، تحت عنوان «نكتة حذف متعلق يرجعون»","url":""}]},{"id":"s7-1624","number":1624,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما غرض التعبير بيرجعون؟","answer":"الرجوع تحول عن الحال التي هم عليها إلى التوبة والصلاح، فيصور مفارقة المعصية والعودة إلى الامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص66–67، تحت عنوان «غرض التعبير بيرجعون»","url":""}]},{"id":"s7-1209","number":1209,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما نكتة تنكير خلف؟","answer":"﴿الخَلْف﴾ بسكون اللام يكثر في الخلف السيئ، بخلاف الخَلَف الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص73، تحت عنوان «نكتة تنكير خلف»","url":""}]},{"id":"s7-1625","number":1625,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما معنى خلف في السياق؟","answer":"اختيار اللفظ يشعر بسوء من جاء بعد الصالحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص69، تحت عنوان «شرح المفردات: خلف»","url":""}]},{"id":"s7-1210","number":1210,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعدهم﴾ مع أن الخلافة تقتضي التأخر؟","answer":"يبين القيد ابتداء مجيء هذا الخلف بعد أسلافه وصلته بهم، ويذكر المصدر أنهم من ذريتهم. أما سرعة التعاقب فيدل عليها عطف ﴿فخلف﴾ بالفاء؛ فلكل جزء من التركيب دلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص72، تحت عنوان «فائدة مجيء القيد من بعدهم ومعنى من»","url":""}]},{"id":"s7-1211","number":1211,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا وصفهم بأنهم ﴿ورثوا الكتاب﴾ لا «أوتوا الكتاب»؟","answer":"شبه انتقال الكتاب والعلم به إليهم بانتقال الميراث، فصاروا خلفاء لأسلافهم في حيازته والقيام عليه. وفي ذلك إقامة للحجة: فقد ورثوا الكتاب وعلموه ثم خالفوا ما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص73، تحت عنوان «بلاغة الاستعارة في التعبير بالإرث»","url":""}]},{"id":"s7-1212","number":1212,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿يأخذون عرض هذا الأدنى﴾، دون أن يقال: متاع الدنيا؟","answer":"العَرَض متاع زائل يعرض ثم يذهب، و﴿هذا الأدنى﴾ تحقير للدنيا القريبة؛ فالتعبير يفضح استبدال الباقي بالعاجل الزهيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص70، تحت عنوان «شرح المفردات: عرض هذا الأدنى»","url":""}]},{"id":"s7-1213","number":1213,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا سمى الدنيا ﴿هذا الأدنى﴾؟","answer":"الإشارة تحضر متاع الدنيا القريب، و﴿الأدنى﴾ تجمع معنى الأقرب والأحقر في مقابل الدار الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص87، تحت عنوان «الأدنى والأقرب»","url":""}]},{"id":"s7-1214","number":1214,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لم بُني ﴿سيُغفر لنا﴾ للمجهول؟","answer":"حذف الفاعل للعلم به؛ فالمغفرة المقصودة لا تكون إلا من الله. ويركز البناء على دعواهم وقوع المغفرة لأنفسهم، وهي الدعوى التي تكشف غرورهم مع إصرارهم على الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص76، تحت «سر بناء الفعل سيغفر لما لم يسم فاعله»","url":""}]},{"id":"s7-1215","number":1215,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا عبروا بالسين: ﴿سيغفر لنا﴾؟","answer":"السين تخلص الفعل للاستقبال، فتحكي قولهم إن المغفرة ستقع لهم لاحقًا مع إصرارهم على المعصية. فموضع الذم ثقتهم بهذا الوعد الذي ادعوه لأنفسهم من غير توبة، لا أن السين بذاتها توجب قرب الزمن أو ضمان المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص75–76، تحت «نكتة مجيء حرف التنفيس في سيغفر»","url":""}]},{"id":"s7-1216","number":1216,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما دلالة الواو في قوله وإن يأتهم؟","answer":"يكشف تكرر الجشع: كلما جاءهم متاع حرام مماثل أخذوه، مع استمرارهم في دعوى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص76، تحت عنوان «دلالة الواو في قوله وإن يأتهم»","url":""}]},{"id":"s7-1217","number":1217,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما نكتة التعبير بالمضارع في يأخذون؟","answer":"يأخذون العرض أولًا ثم يعاودون أخذه متى تجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص74، تحت عنوان «نكتة التعبير بالمضارع في يأخذون»","url":""}]},{"id":"s7-1626","number":1626,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سر التعبير بالجملة الشرطية؟","answer":"تكرار اللفظين يجسد تكرر السلوك نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص77، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s7-1218","number":1218,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا وبخهم باستفهام: ﴿ألم يؤخذ عليهم ميثاق الكتاب﴾؟","answer":"الاستفهام تقريري توبيخي؛ يثبت أن الميثاق أُخذ عليهم بالفعل، فلا عذر لهم في القول على الله بغير الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص78–79، تحت «غرض الاستفهام ونوعه»","url":""}]},{"id":"s7-1219","number":1219,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا أضيف الميثاق إلى الكتاب؟","answer":"لأن مضمون الميثاق ثابت في الكتاب الذي ورثوه ودرسوه؛ فهو عهد مرتبط بحفظ أحكامه وعدم تحريفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص80، تحت «نكتة إضافة الميثاق إلى الكتاب»","url":""}]},{"id":"s7-1220","number":1220,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما الموقع البياني لقوله ألم يؤخذ عليهم؟","answer":"هذا تفسير للميثاق: ألا ينسبوا إلى الله إلا ما ثبت حقًا، وفيه تعريض بأن دعوى ﴿سيغفر لنا﴾ قول بلا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص78، تحت عنوان «الموقع البياني لقوله ألم يؤخذ عليهم»","url":""}]},{"id":"s7-1221","number":1221,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا عقب بقوله: ﴿ودرسوا ما فيه﴾؟","answer":"ذكّر بأنهم قرؤوا ما في الكتاب وعرفوه، فمخالفتهم ليست عن جهل بل بعد درس وعلم، وهو أبلغ في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص82، تحت «غرض التعبير بقوله ﴿ودرسوا ما فيه﴾»","url":""}]},{"id":"s7-1222","number":1222,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما الموقع البياني لجملة ﴿والدار الآخرة خير﴾؟","answer":"متاع الآخرة أبقى وأعظم من العرض الأدنى الذي يأخذونه، فالمقابلة ترد ميزانهم من العاجل الزائل إلى الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص82–83، تحت «الموقع البياني لجملة ﴿والدار الآخرة خير﴾».","url":""}]},{"id":"s7-1223","number":1223,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا قيد خيرية الآخرة بـ﴿للذين يتقون﴾؟","answer":"لأن خير الآخرة لا يناله من آثر الحرام واغتر بالمغفرة، وإنما ينتفع به من اتقى الله ووفى بميثاق الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص83–84، تحت عنوان «معنى اللام في للذين»","url":""}]},{"id":"s7-1224","number":1224,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا ختم بـ﴿أفلا تعقلون﴾، وفي قراءة ﴿يعقلون﴾؟","answer":"الاستفهام يحض على إدراك التفاوت الواضح بين عرض الدنيا والآخرة. وفي قراءة الخطاب مواجهة لهم، وفي الغيبة حكاية لحالهم وتعجيب السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص85، تحت عنوان «فائدة الالتفات في قوله أفلا تعقلون»","url":""}]},{"id":"s7-1225","number":1225,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170؛ قراءة التخفيف والتشديد","question":"ما دلالة التوجيه البلاغي للقراءات في يمسكون؟","answer":"قراءة التخفيف من أمسك تدل على التعلق بالكتاب وحفظه والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص91–92، تحت عنوان «التوجيه البلاغي للقراءات في يمسكون»","url":""}]},{"id":"s7-1627","number":1627,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170؛ قراءة التخفيف والتشديد","question":"ما سر مجيء جملة صلة الموصول بمادتها وصيغتها؟","answer":"قراءة التشديد من مسّك تزيد معنى شدة الحرص والمبالغة والتكرير في التمسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص91–92، تحت عنوان «سر مجيء جملة صلة الموصول بمادتها وصيغتها»","url":""}]},{"id":"s7-1226","number":1226,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿يمسكون بالكتاب﴾ لا «يقرؤون الكتاب»؟","answer":"التمسك هو الأخذ الجاد بما في الكتاب علمًا وعملًا، لا مجرد تلاوته بلا امتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص91–92، تحت عنوان «بلاغة المجاز في قوله يمسكون بالكتاب»","url":""}]},{"id":"s7-1227","number":1227,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"لماذا عطف ﴿وأقاموا الصلاة﴾ بالماضي على المضارع ﴿يمسكون﴾؟","answer":"المضارع يستحضر دوام تمسكهم، والماضي في ﴿أقاموا﴾ يقرر تحقق إقامة الصلاة وثباتها منهم؛ فجمع الاستمرار والتحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص93، تحت «غرض التغاير بين الجمل المعطوفة»","url":""}]},{"id":"s7-1228","number":1228,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"لماذا خُصت الصلاة بعد التمسك بالكتاب؟","answer":"خُصت لأنها عماد العمل وأظهر ما يدل على صدق التمسك بالكتاب، وتجمع صلة العبد بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص93–94، تحت عنوان «نكتة عطف وأقاموا الصلاة على ما تقدمها»","url":""}]},{"id":"s7-1229","number":1229,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"ما أثر توكيد الوعد في ﴿إنا لا نضيع أجر المصلحين﴾؟","answer":"أكد الوعد بإن والجملة الاسمية ليطمئن المتمسكين بالكتاب والمصلحين إلى حفظ أجرهم، ويحثهم على الاستمرار في العمل. فلا يذهب إصلاحهم سدى عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص94–95، تحت عنوان «بلاغة تتابع المؤكدات في فاصلة الآية»","url":""}]},{"id":"s7-1230","number":1230,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿لا نضيع أجر المصلحين﴾، دون أن يقال: أجرهم؟","answer":"أظهر وصف ﴿المصلحين﴾ بدل الضمير ليبين علة حفظ الأجر، ويعم الوعد كل من تحقق بالإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص96، تحت عنوان «معنى أل في المصلحين»","url":""}]},{"id":"s7-1231","number":1231,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"لماذا وصفهم بـ﴿المصلحين﴾ لا «الصالحين»؟","answer":"المصلح يتعدى صلاحه إلى إقامة الكتاب والصلاة وإصلاح غيره، وهو أبلغ من الصالح الذي قد يقتصر خيره على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص96، تحت عنوان «غرض إضافة الأجر إلى المصلحين»","url":""}]},{"id":"s7-1233","number":1233,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ نتقنا الجبل﴾، وما دلالة «نتقنا»؟","answer":"النتق اقتلاع الشيء من أصله ورفعه بقوة، فصوّر رفع الجبل بعد اقتلاعه فوقهم تصويرًا مهيبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص110، تحت عنوان «نتقنا ورفعنا»","url":""}]},{"id":"s7-1234","number":1234,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما دلالة حذف الجار من في قوله فوقهم؟","answer":"يبين أنه صار معلقًا في جهة العلو مباشرة فوق رؤوسهم، فكان التهديد حاضرًا لا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص102، تحت عنوان «دلالة حذف الجار من في قوله فوقهم»","url":""}]},{"id":"s7-1235","number":1235,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا شُبّه الجبل بـ﴿ظلة﴾ مع أنه أعظم منها؟","answer":"التشبيه من جهة كونه ساترًا معلقًا فوقهم كالسحابة المظلة، لا من جهة الحجم؛ فهو يصف هيئته بالنسبة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص102–103، تحت عنوان «الدلالة البلاغية لموقع كأنه ظلة بعد فوقهم»","url":""}]},{"id":"s7-1236","number":1236,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما أثر تشبيه الجبل بظلة من الغمام وهو مرفوع فوقهم؟","answer":"يصور الجبل مرفوعًا فوقهم من غير عمد كالغمام، فيبرز هيئة الارتفاع المحيطة بهم. ويذكر المصدر أن صورة الغمام المعتادة للرحمة صارت هنا صورة تهديد بالعذاب؛ فزاد المشهد رهبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص103، تحت «بلاغة الصورة التشبيهية في قوله كأنه ظلة»","url":""}]},{"id":"s7-1237","number":1237,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أنه واقع بهم﴾ مع رؤيتهم الجبل فوقهم؟","answer":"يذكر المصدر وجهين: أن الظن بمعنى اليقين لقوة أمارات وقوع الجبل، أو أنه باقٍ على معناه لأنهم شاهدوا رفعه ولم يقع بهم بعد، فغلب على نفوسهم توقع سقوطه. والوجهان يبرزان شدة الخوف الذي أحدثه المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص104–105، تحت «بلاغة التعبير بفعل الظن في وظنوا»","url":""}]},{"id":"s7-1238","number":1238,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿واقع بهم﴾ لا «واقع عليهم»؟","answer":"الباء تفيد الإلصاق والوقوع المتلبس بهم، فتشعر بأنه سيصيبهم ويحيط بهم، لا مجرد سقوط في جهة فوقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص106–107، تحت «سر التعبير بحرف الباء في بهم»","url":""}]},{"id":"s7-1239","number":1239,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا حُذف فعل القول قبل ﴿خذوا ما آتيناكم بقوة﴾؟","answer":"حذف القول للإيجاز وسرعة الانتقال من مشهد التهديد إلى الأمر المقصود؛ والتقدير: وقلنا خذوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص107، تحت «موقع جملة خذوا ما آتيناكم بقوة مما قبله وبلاغته»","url":""}]},{"id":"s7-1240","number":1240,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا تكرر الأمر بالأخذ بقوة لقوم موسى بعد أن سبق توجيهه إلى موسى؟","answer":"لأن تكليف موسى كان أشد: يأخذ الكتاب بعزم ثم يبلغه ويؤديه، أما قومه فيأخذون ما بلغهم به قبولًا والتزامًا وطاعة؛ فاختلاف المخاطب ووظيفته اقتضى تجديد الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص513، تحت «فائدة التفريق بين أخذ موسى ﷺ، وأخذ قومه»","url":""}]},{"id":"s7-1241","number":1241,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿واذكروا ما فيه﴾ بعد ﴿خذوا﴾؟","answer":"عقب الأخذ بالذكر تنبيهًا إلى الحفظ والتدبر والعمل، ودفعًا للنسيان والغفلة. فالمطلوب ملازمة مضمون الكتاب علمًا وامتثالًا؛ والذكر يعين على دوام الأخذ به بقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص108، تحت «سر العطف بالأمر بالذكر»","url":""}]},{"id":"s7-1242","number":1242,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا ختم بـ﴿لعلكم تتقون﴾؟","answer":"غاية الأخذ الجاد والذكر أن تنشأ التقوى، فيحجزهم الكتاب عن المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص108–109، تحت عنوان «بلاغة الختم بجملة الإنشاء غير الطلبي في قوله لعلكم تتقون»","url":""}]},{"id":"s7-1243","number":1243,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وإذ نتقنا الجبل فوقهم﴾، وفي البقرة: ﴿ورفعنا فوقكم الطور﴾؟","answer":"﴿نتقنا﴾ في الأعراف يلائم تفصيل مشهد التهديد واقتلاع الجبل، أما ﴿رفعنا﴾ في البقرة فيوجز الحدث ضمن تعداد النعم والمواثيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص110، تحت عنوان «نتقنا ورفعنا»","url":""}]},{"id":"s7-1244","number":1244,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما الفرق الدلالي بين التعبير بـ﴿نتقنا الجبل﴾ في الأعراف و﴿رفعنا فوقكم الطور﴾ في البقرة؟","answer":"الرَّفع أعمّ، فهو نقل الشيء إلى أعلى، أما النَّتق فيدل على اقتلاع الشيء من أصله ثم رفعه؛ لذلك يصوّر لفظ ﴿نتقنا﴾ شدة اقتلاع الجبل ورفعه فوقهم تصويرًا أخص وأقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص555، تحت «الرَّفع والنَّتق»","url":""}]},{"id":"s7-1245","number":1245,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ أخذ ربك من بني آدم﴾، دون أن يقال: من آدم؟","answer":"يعم التعبير ذرية بني آدم المتناسلة من ظهور آبائها، فيشمل البشر جيلًا بعد جيل. ويبين المصدر أن ذكر بني آدم وظهورهم يقرر عموم الأخذ للنسل، ولا يحصر الحجة في شخص آدم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص116، تحت عنوان «سر التعبير بعبارة بني آدم للذكور»","url":""}]},{"id":"s7-1246","number":1246,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا أضيف الرب إلى النبي ﷺ: ﴿ربك﴾؟","answer":"إضافة الرب إلى النبي ﷺ تستحضر عنايته وتربيته وهو يقص عليه أصل الحجة على البشر، وتثبت أن آخذ الميثاق هو ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص115–116، تحت عنوان «نكتة إضافة كلمة الرب إلى ضمير الخطاب ربك»","url":""}]},{"id":"s7-1247","number":1247,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿من ظهورهم ذريتهم﴾ فكرر معنى النسل؟","answer":"﴿من ظهورهم﴾ يبين موضع خروج النسل من الآباء، و﴿ذريتهم﴾ يبين المأخوذ؛ فليس تكرارًا بل تفصيل للمصدر والمستخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص116–117، تحت عنوان «بلاغة التعبير بالبدل من ظهورهم»","url":""}]},{"id":"s7-1248","number":1248,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا جمع ﴿ظهورهم﴾ وأفرد جنس ﴿ذريتهم﴾؟","answer":"جُمعت الظهور لتعدد الآباء، وجاءت الذرية اسم جنس أو جمعًا يدل على مجموع النسل الخارج منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص117–118، تحت «تنوع القراءة القرآنية وأثره في المعنى»","url":""}]},{"id":"s7-1249","number":1249,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"إلى ماذا يعود الضمير في قوله وأشهدهم على أنفسهم؟","answer":"جعلهم شاهدين على حقيقة مستقرة في فطرهم، فلا يستطيع المرء أن يدفع إقرار نفسه بربوبية خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص118–119، تحت عنوان «مرجع الضمير في قوله وأشهدهم على أنفسهم»","url":""}]},{"id":"s7-1250","number":1250,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا جاء التقرير باستفهام: ﴿ألست بربكم﴾؟","answer":"الاستفهام تقريري يلزمهم بالإجابة التي لا يسع الفطرة إنكارها، فيتحول العلم بالربوبية إلى شهادة صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص120، تحت «إيثار الاستفهام التقريري على التقرير المباشر»","url":""}]},{"id":"s7-1251","number":1251,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لم قررت الآية الربوبية في ﴿ألست بربكم﴾؟","answer":"تذكر الربوبية المخاطبين بخلق الله لهم وتربيته وإحسانه وتدبيره، فتقوم هذه النعم دليلًا على استحقاقه الإقرار والطاعة. فالمقرر به وصف يجمع الحجة والتذكير بالإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص121، تحت «بلاغة التعبير بالربوبية في تعيين المقرر به بربكم»","url":""}]},{"id":"s7-1252","number":1252,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما دلالة جوابهم: ﴿بلى شهدنا﴾ وجمعه بين الإقرار والشهادة؟","answer":"﴿بلى﴾ تبطل النفي وتثبت الربوبية، و﴿شهدنا﴾ يوثق الإقرار ويحمّلهم تبعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص122، تحت عنوان «سر اصطفاء الجواب بلى»","url":""}]},{"id":"s7-1253","number":1253,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا حُذف متعلق ﴿شهدنا﴾ أو المشهود به؟","answer":"حذف لدلالة السؤال عليه؛ أي شهدنا أنك ربنا، فالإيجاز يثبت الجواب من غير إعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص123، تحت «بلاغة كمال الاتصال أو الاستئناف بين حكاية قول البشر أو الملائكة»","url":""}]},{"id":"s7-1254","number":1254,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما وجه البلاغة في القيد بالظرف يوم القيامة في قوله تعالى: ﴿أن تقولوا يوم القيامة إنا كنا عن هذا غافلين﴾؟","answer":"بيّن غاية الإشهاد: قطع عذر الغفلة يوم القيامة، فلا يقولوا إن أصل معرفة الرب لم يقم في فطرتهم ولم تبلغهم دلائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص125، تحت عنوان «بلاغة القيد بالظرف يوم القيامة»","url":""}]},{"id":"s7-1255","number":1255,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"إلى ماذا يشير ﴿هذا﴾؟","answer":"يشير إلى التوحيد والإقرار بربوبية الله، أو إلى الميثاق والإشهاد المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص126، تحت «سر التعبير باسم الإشارة هذا في عن هذا غافلين»","url":""}]},{"id":"s7-1256","number":1256,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا قيل في ميثاق النبيين: ﴿وإذ أخذ الله ميثاق النبيين﴾، وفي ميثاق ذرية آدم: ﴿وإذ أخذ ربك من بني آدم﴾؟","answer":"أُسند ميثاق النبيين إلى الاسم الأعظم ﴿الله﴾ لما فيه من المهابة والجلال، ولأن الميثاق تكليف عام للأنبياء. وأُسند ميثاق الذرية إلى ﴿ربك﴾ لمناسبة معنى الربوبية والإنعام والتربية، مع ما في الإضافة إلى ضمير النبي ﷺ من تشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص368، تحت «توجيه المتشابه اللفظي بين قوله: ﴿وإذ أخذ الله﴾ وقوله: ﴿وإذ أخذ ربك﴾»","url":""}]},{"id":"s7-1628","number":1628,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير بضمير العظمة في قوله تعالى: ﴿وإذ أخذنا ميثاقكم﴾؟","answer":"إضافة فعل الأخذ إلى ضمير العظمة ﴿نا﴾ تُشعر بقوة الآخذ وعظمة الميثاق، وتؤكد وجوب الوفاء به؛ فالذي تولّى أخذَه هو الله تعالى، وقد أخذه بقوة على بني إسرائيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص549، تحت «بلاغة التعبير بمادة (أخذ) المضافة إلى ضمير العظمة (نا)»","url":""}]},{"id":"s7-1257","number":1257,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا عطف العذر الثاني بـ﴿أو تقولوا﴾؟","answer":"العطف يعرض عذرًا آخر مغايرًا للأول: بعد دعوى الغفلة تأتي دعوى تقليد الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص131–132، تحت «دلالة أو في أو تقولوا»","url":""}]},{"id":"s7-1258","number":1258,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا جاء القصر: ﴿إنما أشرك آباؤنا من قبل﴾؟","answer":"القصر يجعلون أصل الشرك محصورًا في الآباء السابقين، محاولين نفي المسؤولية عن أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص132–133، تحت عنوان «سر التعبير بأسلوب القصر في إنما أشرك آباؤنا»","url":""}]},{"id":"s7-1259","number":1259,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"ما دلالة قولهم: ﴿من قبل﴾ مع وضوح سبق الآباء؟","answer":"زادوه لتأكيد سبق الآباء وبعد العهد، وبناء حجتهم على أنهم لم يكونوا مبتدئي الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص133، تحت «دلالة التعبير بالظرف»","url":""}]},{"id":"s7-1260","number":1260,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا وصفوا أنفسهم بـ﴿ذرية من بعدهم﴾؟","answer":"صوروا أنفسهم نسلًا تابعًا جاء بعد الآباء، ليجعلوا التقليد قدَرًا ورثوه لا اختيارًا يحاسبون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص133، تحت عنوان «دلالة الإيجاز في قوله وكنا ذرية من بعدهم»","url":""}]},{"id":"s7-1261","number":1261,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا سألوا: ﴿أفتهلكنا بما فعل المبطلون﴾؟","answer":"الاستفهام استعطاف احتجاجي بلسانهم: أتؤاخذنا بفعل من أبطل قبلنا؟ وقد قطع الميثاق هذا العذر لأن كل نفس مسؤولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص135–136، تحت عنوان «علاقة جملة الاستفهام أفتهلكنا بما قبلها»","url":""}]},{"id":"s7-1262","number":1262,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا سمى الآباء ﴿المبطلون﴾ لا «المشركون»؟","answer":"الإبطال يشمل الشرك ونقض العهد وإبطال أثر العقول وأقوال الرسل باتباع الباطل. فهو أوسع من وصف الشرك وحده، ويلائم مقام دفع العذر بالتقليد الذي أبطلوا به مقتضى الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص136، تحت «دلالة التعبير بلفظ المبطلون»","url":""}]},{"id":"s7-1263","number":1263,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما وجه البلاغة في أسلوب التشبيه في قوله وكذلك نفصل الآيات؟","answer":"أي مثل هذا التفصيل الواضح لحجة الفطرة وأعذار البشر نفصل سائر الآيات؛ فالكاف تشير إلى البيان السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص139–140، تحت عنوان «بلاغة أسلوب التشبيه في قوله وكذلك نفصل الآيات»","url":""}]},{"id":"s7-1264","number":1264,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما دلالة إيثار التعبير بالتفصيل بدل البيان؟","answer":"التفصيل يميز المعاني بعضها من بعض ويبين أجزاءها وجهاتها، فيكون البيان أوضح وأبعد عن الاختلاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص140، تحت عنوان «إيثار التعبير بالتفصيل بدل البيان»","url":""}]},{"id":"s7-1629","number":1629,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما دلالة التفصيل والبيان؟","answer":"كل حجة تعرض بما يكشف مدلولها ويتيح النظر في وجوهها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص143، تحت عنوان «التفصيل والبيان»","url":""}]},{"id":"s7-1265","number":1265,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"لماذا جمع ﴿الآيات﴾؟","answer":"الجمع لتعدد الدلائل المبينة للتوحيد والمسؤولية وبطلان الأعذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص139–140، تحت عنوان «بلاغة أسلوب التشبيه في قوله وكذلك نفصل الآيات»","url":""}]},{"id":"s7-1266","number":1266,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿ولعلهم يرجعون﴾ لا «لعلهم يؤمنون»؟","answer":"الرجوع أنسب لأن معرفة الرب مركوزة في الفطرة؛ فالمطلوب عودتهم إلى أصل أقروا به، لا إيمان مبتدأ لا سابقة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص141–142، تحت «بلاغة المجاز بالاستعارة في التعبير بالفعل يرجعون»","url":""}]},{"id":"s7-1267","number":1267,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"لماذا عطف غاية الرجوع بالواو؟","answer":"الواو تجمع غايتين للتفصيل: إقامة الحجة وفتح طريق الرجوع، أو تعطف الرجاء على محذوف مفهوم كالتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص141، تحت «دلالة عطف الإنشاء على الخبر»","url":""}]},{"id":"s7-1268","number":1268,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا أمر النبي ﷺ: ﴿واتل عليهم نبأ الذي آتيناه آياتنا﴾؟","answer":"أمره أن يتلو القصة للعبرة والتحذير من عالم عرف الآيات ثم تركها؛ فهي مثال حي لمن لا ينتفع بالعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص146، تحت عنوان «سر التعبير بالفعل واتل»","url":""}]},{"id":"s7-1269","number":1269,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]},{"surah":9,"verses":[70]}],"verseLabel":"الأعراف: 175؛ التوبة: 70","question":"لماذا عبّر القرآن بـ﴿نبأ﴾ في قوله: ﴿واتل عليهم نبأ الذي آتيناه آياتنا﴾، ولم يقل: خبره؟","answer":"لأن النبأ خبر عظيم ظاهر ذو أهمية يلتفت إليه أولو الألباب، وهذه القصة جسيمة العبرة والعاقبة؛ أما الخبر فقد يطلق على ما لا يبلغ هذا القدر من الشأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص147، تحت «إيثار التعبير بالنبأ دون الخبر»","url":""}]},{"id":"s7-1270","number":1270,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا لم يسمِّ الرجل فقال: ﴿الذي آتيناه آياتنا﴾؟","answer":"عبر عنه بالموصول ليبرز الوصف الذي تقوم عليه العبرة: إيتاؤه الآيات ثم انسلاخه منها. فالمقصود عرض حاله وفعله، وتكفي الصلة للتعريف به من غير التصريح باسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص148–149، تحت «سر التعبير بالاسم الموصول الخاص الذي»","url":""}]},{"id":"s7-1271","number":1271,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿آتيناه آياتنا﴾ لا «علمناه»؟","answer":"الإيتاء تمليك وتمكين من الآيات والحجج، وهو أبلغ من مجرد تعليمه معلومة؛ فقد صارت في حوزته ثم نبذها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149–150، تحت عنوان «بلاغة إسناد الفعل إلى نون العظمة في قوله آتيناه»","url":""}]},{"id":"s7-1272","number":1272,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا أضاف الآيات إلى الله؟","answer":"لتشريفها وتعظيم جرم الانسلاخ منها؛ فهي آيات الله لا معارف بشرية عادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149، تحت «بلاغة إسناد الفعل إلى نون العظمة في قوله آتيناه»","url":""}]},{"id":"s7-1273","number":1273,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما دلالة الاستعارة في قوله فانسلخ منها؟","answer":"صوّر الآيات كأنها كانت محيطة به ثم نزع نفسه منها نزعًا كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149، تحت عنوان «بلاغة الاستعارة في قوله فانسلخ منها»","url":""}]},{"id":"s7-1630","number":1630,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما دلالة إيثار التعبير بالانسلاخ على الانقطاع؟","answer":"الانسلاخ خروج الشيء من جلده الملتصق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151، تحت عنوان «إيثار التعبير بالانسلاخ على الانقطاع»","url":""}]},{"id":"s7-1274","number":1274,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا عُدّي الانسلاخ بـ﴿منها﴾؟","answer":"﴿منها﴾ تبين أنه خرج من داخل محيط الآيات الذي كان متلبسًا به، فاشتد معنى المفارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149–150، تحت «بلاغة الاستعارة في قوله فانسلخ منها»","url":""}]},{"id":"s7-1275","number":1275,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا عطف ﴿فأتبعه الشيطان فكان من الغاوين﴾ بفاءين؟","answer":"الفاء الأولى تبين أن ملاحقة الشيطان ترتبت سريعًا على انسلاخه، والثانية أن دخوله في الغاوين كان نتيجة تلك الملاحقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151–152، تحت عنوان «ترتيب أفعال الانسلاخ والاتباع والكون من الغاوين بفاء العطف»","url":""}]},{"id":"s7-1276","number":1276,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتبعه الشيطان﴾ لا «فتبعه الشيطان»؟","answer":"﴿أتبعه﴾ بمعنى لحقه وأدركه بعد طلب، فيصور الشيطان مطاردًا له حتى استحوذ عليه؛ وهو أقوى من مجرد المصاحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151–152، تحت «بلاغة التعبير بالفعل فأتبعه»","url":""}]},{"id":"s7-1277","number":1277,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما دلالة الشيطان والجن وإبليس؟","answer":"يبين أن مفارقة الآيات مكنت الشيطان منه فأدركه واستولى على أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص155، تحت عنوان «الشيطان والجن وإبليس»","url":""}]},{"id":"s7-1631","number":1631,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سر التعبير بالفعل فأتبعه؟","answer":"لفظ الشيطان يدل على التمرد والبعد عن الخير، فيناسب ما آل إليه حال المنسلخ من الغواية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151، تحت عنوان «بلاغة التعبير بالفعل فأتبعه»","url":""}]},{"id":"s7-1278","number":1278,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فكان من الغاوين﴾ لا «فغوى»؟","answer":"﴿كان من الغاوين﴾ تدخله في زمرة استقر فيها الغي وصار وصفًا لها، وهو أبلغ من وقوع غي عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص152–153، تحت عنوان «سر التعبير بقوله من الغاوين»","url":""}]},{"id":"s7-1279","number":1279,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو شئنا لرفعناه بها﴾، وعلّق الرفع بالمشيئة؟","answer":"يعلق الرفع بمشيئة الله ليبين أن إيتاء الآيات وحده لا يستلزم الرفعة، بل تكون بالاهتداء والعمل بها بتوفيقه. ثم يذكر إخلاده إلى الأرض واتباعه الهوى سببًا في حرمانه من هذه الرفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص159، تحت عنوان «دلالة حذف مفعول المشيئة»","url":""}]},{"id":"s7-1280","number":1280,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا عُدّي الرفع بالباء: ﴿بها﴾؟","answer":"الباء للسببية؛ أي لرفعناه بالعمل بالآيات واتباع الحق الذي تدل عليه. فالرفعة ليست بمجرد حيازة العلم، وإنما بالانتفاع به والعمل بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161، تحت «دلالة الباء في قوله لرفعناه بها»","url":""}]},{"id":"s7-1281","number":1281,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة الباء في قوله لرفعناه بها؟","answer":"لأنه اختار الإخلاد إلى الأرض واتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «دلالة الباء في قوله لرفعناه بها»","url":""}]},{"id":"s7-1632","number":1632,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة الاستدراك بعد المشيئة في قوله ولكنه أخلد؟","answer":"الآيات لا ترفع من ينخلع منها ويعطل مقتضاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «دلالة الاستدراك بعد المشيئة في قوله ولكنه أخلد»","url":""}]},{"id":"s7-1282","number":1282,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما وجه البلاغة في الاستعارة التمثيلية أخلد إلى الأرض في قوله تعالى: ﴿ولكنه أخلد إلى الأرض﴾؟","answer":"الإخلاد شدة الميل مع الركون والدوام، والأرض كناية عن الدنيا وشهواتها؛ فصوّر نفسه ملتصقة بالسفول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص162، تحت عنوان «بلاغة الاستعارة التمثيلية أخلد إلى الأرض»","url":""}]},{"id":"s7-1283","number":1283,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا عُدّي ﴿أخلد﴾ بـ﴿إلى﴾؟","answer":"﴿إلى﴾ تصور اتجاه ميله وقصده نحو الأرض حتى ركن إليها واستقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص162، تحت عنوان «بلاغة الاستعارة التمثيلية أخلد إلى الأرض»","url":""}]},{"id":"s7-1284","number":1284,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما وجه البلاغة في الاستعارة التمثيلية أخلد إلى الأرض؟","answer":"قوبل العلو الذي تمنحه الآيات بالسقوط إلى الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «بلاغة الاستعارة التمثيلية أخلد إلى الأرض»","url":""}]},{"id":"s7-1633","number":1633,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة الاستعارة في جواب الشرط لرفعناه بها؟","answer":"المقابلة تجسد التفاوت بين طريق الوحي وطريق الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «بلاغة الاستعارة في جواب الشرط لرفعناه بها»","url":""}]},{"id":"s7-1285","number":1285,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبع هواه﴾ بعد ﴿أخلد إلى الأرض﴾؟","answer":"الإخلاد يصف تعلقه بالدنيا، واتباع الهوى يبين القائد الداخلي لهذا التعلق؛ فاختار رغباته على الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص163–164، تحت عنوان «بلاغة الاستعارة في واتبع هواه»","url":""}]},{"id":"s7-1286","number":1286,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا شُبّه بالكلب تحديدًا؟","answer":"لأن الكلب يلهث في حالتي الطرد والترك، فضرب به مثل من استولى عليه الطمع والهوى فلا يهدأ بالموعظة ولا بتركها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص166، تحت عنوان «سر التعبير عن وصف سفالة المكذب بتشبيهه بالكلب»","url":""}]},{"id":"s7-1287","number":1287,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة تقييد حال الكلب بجملة شرطية إن تحمل ودلالة الحمل عليه في قوله تعالى: ﴿إن تحمل عليه يلهث أو تتركه يلهث﴾؟","answer":"المعنى أن حاله واحدة: إن تزجره أو تعظه يظل تابعًا لهواه، وإن تتركه يظل كذلك؛ كدوام لهث الكلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص167، تحت عنوان «تقييد حال الكلب بجملة شرطية إن تحمل ودلالة الحمل عليه»","url":""}]},{"id":"s7-1288","number":1288,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ تقديم الحمل عليه على تركه؟","answer":"قدم الحمل لأنه صورة أشد تكشف لهث الكلب أولًا، ثم جاء الترك ليثبت أن اللهث طبع ملازم لا أثر تعب عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص167، تحت «دلالة تقديم الحمل على الترك»","url":""}]},{"id":"s7-1289","number":1289,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا كرر ﴿يلهث﴾؟","answer":"كرر الفعل لإثبات تساوي الحالتين واستقلال كل شرط بنتيجته؛ فهو يلهث في الشدة والراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص166–167، تحت عنوان «تقييد حال الكلب بجملة شرطية إن تحمل ودلالة الحمل عليه»","url":""}]},{"id":"s7-1290","number":1290,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك مثل القوم الذين كذبوا بآياتنا﴾ بعد مثل الفرد؟","answer":"نقل المثل من الرجل الواحد إلى كل قوم يكذبون بالآيات؛ فحاله نموذج متكرر لا حادثة فردية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص167–168، تحت عنوان «دلالة التعبير باسم الإشارة ذلك»","url":""}]},{"id":"s7-1291","number":1291,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا أمر: ﴿فاقصص القصص لعلهم يتفكرون﴾؟","answer":"أمره بعرض القصص وضرب الأمثال لتقريب العبرة وتحريك التفكر في أسباب الانحراف وعواقبه. فالتمثيل بصورة محسوسة يعين السامع على فهم الحال والاتعاظ بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص169، تحت عنوان «دلالة قوله فاقصص القصص»","url":""}]},{"id":"s7-1292","number":1292,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا خُتمت بـ﴿لعلهم يتفكرون﴾ لا «يتذكرون»؟","answer":"التفكر هو النظر في تركيب المثل وأسبابه ومآله واستخراج العبرة، وهو أنسب من مجرد تذكر معلومة سابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص171، تحت عنوان «يتفكرون ويتذكرون»","url":""}]},{"id":"s7-1293","number":1293,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"لماذا افتتحت بـ﴿ساء مثلًا﴾؟","answer":"بدأ بفعل الذم ليواجه السامع فورًا بقبح هذا المثل قبل إعادة وصف أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص174–175، تحت عنوان «بلاغة الجملة الاستئنافية»","url":""}]},{"id":"s7-1294","number":1294,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"ما سرّ تقديم ﴿مثلًا﴾ على ﴿القوم﴾؟","answer":"﴿مثلًا﴾ تمييز يفسر الضمير المبهم في فعل الذم، وبه يتوجه السوء إلى المثل والحال قبل تعيين أصحابه. والتقدير في أحد الأوجه: ساء مثلًا مثل القوم، فحذف المضاف وأقيم القوم مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص175–176، تحت «سر الحذف والتقديم في قوله مثلًا القوم»","url":""}]},{"id":"s7-1295","number":1295,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"لماذا أظهر ﴿القوم الذين كذبوا بآياتنا﴾ بدل الضمير؟","answer":"أظهر الموصول بدل الضمير لتكرير سبب الذم في السمع: تكذيبهم بآيات الله هو الذي جعل مثلهم سيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص176، تحت «فائدة ذكر لفظة القوم موصوفًا بالموصول»","url":""}]},{"id":"s7-1298","number":1298,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"ما دلالة الجمع بين ﴿كانوا﴾ و﴿يظلمون﴾؟","answer":"تدل ﴿كانوا﴾ مع المضارع على أن ظلمهم كان شأنًا ثابتًا يتجدد منهم، لا حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص178، تحت عنوان «بلاغة التعبير بالماضي في كانوا»","url":""}]},{"id":"s7-1299","number":1299,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ الإفراد في ﴿فهو المهتدي﴾ والجمع في ﴿فأولئك هم الخاسرون﴾؟","answer":"في ﴿فهو المهتدي﴾ روعي لفظ من المفرد، وفي ﴿فأولئك هم الخاسرون﴾ روعي معناها العام. ويذكر المصدر مناسبة أخرى: طريق المهتدين واحد في مقابل تعدد طرق الضلال، مع تشريف الفرد المهتدي وإدراج الضالين في زمرة الخاسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص186، تحت «بلاغة التعبير بالجمع مقابل المفرد المهتدي والخاسرون»","url":""}]},{"id":"s7-1300","number":1300,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ إظهار اسم الله في ﴿من يهد الله﴾؟","answer":"أُظهر الاسم الجليل لتشريف الهداية والتنويه بأن مصدرها الله وحده، مع زيادة التقرير والوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص183، تحت «بلاغة إسناد الفعل إلى اسم الجلالة الله»","url":""}]},{"id":"s7-1301","number":1301,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما دلالة اسم الفاعل المعرّف في ﴿فهو المهتدي﴾؟","answer":"يفيد أن من هداه الله هو المتحقق بالهداية الكاملة الثابتة، وأنه المختص بحقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص183، تحت «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s7-1302","number":1302,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ عدم إعادة اسم الله في قوله تعالى: ﴿ومن يضلل﴾؟","answer":"اكتفى بالضمير المستتر في ﴿يضلل﴾ لظهور مرجعه من ﴿من يهد الله﴾، وربطت الواو بين الحالتين المتقابلتين. فالمعنى متصل واضح من غير حاجة إلى إعادة الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص183–184، تحت «دلالة العطف بحرف الواو في قوله ومن يضلل»","url":""}]},{"id":"s7-1303","number":1303,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ الانتقال إلى الجمع في جواب الشرط: ﴿فأولئك﴾؟","answer":"انتقل إلى الجمع مراعاةً لمعنى ﴿من﴾؛ فهي وإن أفرد لفظها تشمل كل من وقع في الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص186، تحت «بلاغة التعبير بالجمع مقابل المفرد المهتدي والخاسرون»","url":""}]},{"id":"s7-1304","number":1304,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما دلالة ضمير الفصل ﴿هم﴾ في ﴿أولئك هم الخاسرون﴾؟","answer":"يفيد تقوية الحكم وقصر جنس الخسران الكامل عليهم؛ إذ خسروا أنفسهم والهداية والمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص184–185، تحت عنوان «ورود ضمير الفصل هم ودلالته على التأكيد»","url":""}]},{"id":"s7-1305","number":1305,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما مناسبة مقابلة الهداية بالخسران بدل الضلال؟","answer":"لأن الضلال سبب، وعاقبته الجامعة هي الخسران؛ فالمقابلة انتقلت من الطريق الصحيح إلى نتيجة فقده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص185، تحت «بلاغة حذف التقابل في المغايرة بين فعل الشرط وجوابه»","url":""}]},{"id":"s7-1306","number":1306,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة الواو في قوله ولقد ذرأنا؟","answer":"ي الواو فتصل هذا البيان بما قبله، وليست بذاتها أداة التوكيد هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص191–192، تحت عنوان «دلالة الواو في قوله ولقد ذرأنا»","url":""}]},{"id":"s7-1634","number":1634,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما وجه البلاغة في استخدام الإنشاء غير الطلبي في القسم المسوق؟","answer":"أكد الخبر بالقسم المقدر واللام وقد لغرابة مضمونه وشدة أثره: أن كثيرًا ممن أوتوا المدارك لم ينتفعوا بها فصاروا إلى هذا المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص191–192، تحت عنوان «بلاغة استخدام الإنشاء غير الطلبي في القسم المسوق»","url":""}]},{"id":"s7-1307","number":1307,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ التعبير بـ﴿ذرأنا﴾ بدل «خلقنا»؟","answer":"الذرء هو الخلق مع معنى الإيجاد والبث والتكثير، فناسب ذكر الكثير من الجن والإنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188، تحت عنوان «شرح المفردات: ذرأنا»","url":""}]},{"id":"s7-1308","number":1308,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة اللام في قوله لجهنم؟","answer":"يذكر المصدر وجهين: لام الصيرورة والعاقبة، أو التعليل باعتبار الأفعال التي تفضي إلى جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص193، تحت عنوان «دلالة اللام في قوله لجهنم»","url":""}]},{"id":"s7-1635","number":1635,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما وجه البلاغة في استخدام المجاز المرسل في قوله لجهنم؟","answer":"في الوجه الثاني يراد السبب المؤدي إليها، ويؤكد السياق إصرارهم على الباطل وعدم انتفاعهم بآلات الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص193، تحت عنوان «بلاغة استخدام المجاز المرسل في قوله لجهنم»","url":""}]},{"id":"s7-1309","number":1309,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ تقديم الجن على الإنس؟","answer":"قُدموا لتقدم خلقهم، ولأن المقام يستوعب الصنفين المكلفين مبتدئًا بالأسبق وجودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص195–196، تحت «بلاغة تقديم الجن على الإنس»","url":""}]},{"id":"s7-1310","number":1310,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة إسناد الفقه إلى القلوب في ﴿لهم قلوب لا يفقهون بها﴾؟","answer":"القلب في الاستعمال القرآني موضع الإدراك والتدبر والاعتبار؛ فنفي الفقه عنه نفي للانتفاع العقلي بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص189، تحت عنوان «شرح المفردات: قلوب»","url":""}]},{"id":"s7-1311","number":1311,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ تكرار ﴿لهم﴾ في ذكر القلوب والأعين والآذان؟","answer":"التكرار يفصل كل نعمة ويقرر قيام الحجة بها مستقلة؛ فقد عطلوا القلب والبصر والسمع جميعًا عن غاياتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص198، تحت «نكتة الإطناب بإعادة الخبر لهم مع القلوب والأعين والآذان»","url":""}]},{"id":"s7-1312","number":1312,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"كيف يُفهم نفي الفقه والإبصار والسماع مع سلامة الجوارح؟","answer":"المنفي هو الانتفاع بهذه الجوارح في إدراك آيات الحق وقبولها، لا أصل وظائفها الحسية؛ فهي موجودة ولكنها معطلة عن غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص197، تحت عنوان «وجه حذف المفعول به في مقام الفقه والبصر والسمع»","url":""}]},{"id":"s7-1313","number":1313,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ ترتيب القلوب ثم الأعين ثم الآذان؟","answer":"بدأ بالقلب لأنه محل الفقه والحكم، ثم ذكر العين والأذن لأنهما طريقا وصول المشاهدات والمسموعات إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص196–197، تحت عنوان «سر تقديم الأعين على الآذان»","url":""}]},{"id":"s7-1314","number":1314,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما وجه تشبيههم بالأنعام في ﴿أولئك كالأنعام﴾؟","answer":"لأنهم حصروا مداركهم في المحسوس والشهوة ولم يستعملوها في معرفة الحق، فشابهوا الأنعام في الاقتصار على مطالب الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص201–202، تحت «براعة التشبيه المجمل في قوله أولئك كالأنعام»","url":""}]},{"id":"s7-1315","number":1315,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة الترقي من ﴿كالأنعام﴾ إلى ﴿بل هم أضل﴾؟","answer":"هم أضل لأن الأنعام لم تُعطَ وسائل التكليف والتمييز ثم تعطلها، أما هؤلاء فأوتوا المدارك والحجة وأعرضوا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص202–203، تحت «معنى بل في قوله بل هم أضل»","url":""}]},{"id":"s7-1316","number":1316,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ تكرار اسم الإشارة ﴿أولئك﴾؟","answer":"أعيد للتنبيه عليهم بعد تمام وصفهم، ولتثبيت حكم جديد مستقل: أنهم الغافلون حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص201، تحت عنوان «دقيقة التعبير باسم الإشارة الدال على البعد»","url":""}]},{"id":"s7-1317","number":1317,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما مناسبة ختم الآية بـ﴿أولئك هم الغافلون﴾؟","answer":"الغفلة هي الجامع الذي نشأ عنه تعطيل القلب والعين والأذن، فجاء الختام كاشفًا أصل ضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص204–205، تحت عنوان «سر التعبير بلفظ الغافلون دون الضالون»","url":""}]},{"id":"s7-1318","number":1318,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة تقديم ﴿ولله﴾ في ﴿ولله الأسماء الحسنى﴾؟","answer":"التقديم يفيد الاختصاص: الأسماء البالغة غاية الحسن مختصة بالله على وجه الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص211–212، تحت «فائدة القصر بتقديم ما حقه التأخير في مفتتح الآية»","url":""}]},{"id":"s7-1319","number":1319,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة جمع ﴿الأسماء﴾؟","answer":"الجمع يدل على تعدد الأسماء الدالة على صفات الكمال، مع وحدة المسمى سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص213، تحت عنوان «معنى أل الاستغراقية في الأسماء»","url":""}]},{"id":"s7-1320","number":1320,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما سرّ وصف الأسماء بـ﴿الحسنى﴾ بدل «الحسنة»؟","answer":"﴿الحسنى﴾ مؤنث الأحسن، فتدل على بلوغ أسماء الله الغاية العليا في الحسن والكمال، لا مجرد اتصافها بالحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص213–214، تحت «سر اختيار كلمة الحسنى»","url":""}]},{"id":"s7-1321","number":1321,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما مناسبة تفريع ﴿فادعوه بها﴾ على قوله تعالى: ﴿ولله الأسماء الحسنى﴾؟","answer":"لما ثبت اختصاصه بالأسماء الحسنى ترتب عليه أن يُدعى ويُثنى عليه بها، باختيار الاسم المناسب للمطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص214، تحت عنوان «معنى الفاء في قوله فادعوه بها»","url":""}]},{"id":"s7-1322","number":1322,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما معنى الفاء في قوله فادعوه بها؟","answer":"الدعاء بها يجمع الطلب وتعظيم الله بما له من الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص214، تحت عنوان «معنى الفاء في قوله فادعوه بها»","url":""}]},{"id":"s7-1636","number":1636,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما معنى فادعوه في السياق؟","answer":"يدعى الله ويثنى عليه بأسمائه الحسنى، فيذكر الداعي منها ما يناسب مطلوبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص210، تحت عنوان «شرح المفردات: فادعوه»","url":""}]},{"id":"s7-1323","number":1323,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما سرّ الأمر بـ﴿وذروا الذين يلحدون في أسمائه﴾؟","answer":"المعنى: دعوا من يصرون على الإلحاد بعد قيام الحجة، ولا تتبعوا طريقتهم؛ فقد تولى الوعيد بيان جزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص217، تحت عنوان «علة الإظهار في قوله في أسمائه»","url":""}]},{"id":"s7-1324","number":1324,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة الاستعارة في قوله يلحدون؟","answer":"تصور انحرافهم واقعًا في شأن الأسماء نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص215، تحت عنوان «بلاغة الاستعارة في قوله يلحدون»","url":""}]},{"id":"s7-1637","number":1637,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما وجه البلاغة في استعمال حرف الظرفية «في» في قوله تعالى: ﴿يُلْحِدُونَ فِي أَسْمَائِهِ﴾؟","answer":"بتغييرها أو تحريف معانيها أو إطلاق ما لا يليق بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص217، تحت عنوان «بلاغة استعمال حرف الظرفية في»","url":""}]},{"id":"s7-1325","number":1325,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما سر التعبير بـ﴿سيُجزون ما كانوا يعملون﴾ بدل التصريح بالعذاب؟","answer":"حذفت الباء من معنى المجازاة بما كانوا يعملون، فصور الجزاء كأنه العمل نفسه لشدة موافقته له. وفي الإبهام وعيد وتهويل، مع بيان أن الجزاء عدل مطابق لأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص218–219، تحت عنوان «سر التعبير بقوله ما كانوا يعملون»","url":""}]},{"id":"s7-1326","number":1326,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة السين في ﴿سيجزون ما كانوا يعملون﴾؟","answer":"تفيد السين تأكيد وقوع الجزاء في المستقبل، وفي السياق وعيد للمُلحدين في أسماء الله يردعهم عن إلحادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص218، تحت «علة التعبير بحرف السين»","url":""}]},{"id":"s7-1327","number":1327,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما مناسبة قوله تعالى: ﴿وممن خلقنا أمة﴾ بعد ذكر من ذُرئوا لجهنم؟","answer":"جاءت مقابلةً للفريق الغافل؛ فكما وُجد الكثير المعرض، وُجدت جماعة مهتدية تقيم الحق والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص225، تحت «عطف المقابلة بجملته وزبدته، بين الآية وما قبلها»","url":""}]},{"id":"s7-1328","number":1328,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما دلالة إسناد الخلق إلى ضمير العظمة في ﴿وممن خلقنا أمة﴾؟","answer":"يبرز عظمة الربوبية، ويؤكد أن وجود أمة مهتدية داعية إلى الحق نعمة من الله وتأييد منه، فلا يخلو خلقه من هداة مهديين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص226–227، تحت عنوان «بلاغة إسناد الفعل إلى ضمير العظمة: خلقنا»","url":""}]},{"id":"s7-1329","number":1329,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما سر اختيار ﴿أمة﴾ في وصف الجماعة التي تهدي بالحق وتعدل به؟","answer":"يلائم لفظ الأمة جماعة تجتمع على الدين والحق وتقوم بهما في الناس، وفيه معنى الخيرية والكمال. أما الطائفة فتدل على قطعة من الجماعة، وقد تطلق على العدد القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص229–230، تحت «أمة وطائفة»","url":""}]},{"id":"s7-1330","number":1330,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما سر عدم التصريح باسم الأمة الخاتمة في قوله: ﴿وممن خلقنا أمة يهدون بالحق﴾؟","answer":"أُبهمت الأمة تفخيمًا لها وإعلاءً لشأنها؛ وأكثر المفسرين على أنها أمة محمد ﷺ، ولم تُعيّن باسمها ليبقى الوصف بالهداية والعدل هو العلامة البارزة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص227، تحت «سر عدم التصريح بأن المراد بالأمة، الأمة الخاتمة»","url":""}]},{"id":"s7-1638","number":1638,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما دلالة التعبير بـ﴿قوم موسى﴾ دون «بني إسرائيل» أو «أهل الكتاب»؟","answer":"للدلالة على أنهم أتباع موسى المتمسكون بدينه قبل بعثة محمد ﷺ؛ فالإضافة إلى موسى تشعر باتباع رسالته والاقتداء به، لا بمجرد النسب إلى بني إسرائيل أو الانتساب العام إلى أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص723، تحت «دلالة التعبير بـ﴿قوم موسى﴾ دون (بني إسرائيل)، أو (أهل الكتاب)»","url":""}]},{"id":"s7-1331","number":1331,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما وجه البلاغة في معنى الباء في قوله بالحق وبه؟","answer":"الباء تفيد ملابسة الحق والاستعانة به، فالحق مصاحب لهدايتهم وعدلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص227–228، تحت عنوان «بلاغة معنى الباء في قوله بالحق وبه»","url":""}]},{"id":"s7-1639","number":1639,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما دلالة وجه التعبير بالضمير موضع الظاهر؟","answer":"يعود الضمير في ﴿به﴾ إلى الحق نفسه، فيربط الحكم بالهداية إلى أصل واحد لا يتعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص227–228، تحت عنوان «وجه التعبير بالضمير موضع الظاهر»","url":""}]},{"id":"s7-1332","number":1332,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما مناسبة استئناف الوعيد بقوله تعالى: ﴿والذين كذبوا بآياتنا سنستدرجهم﴾؟","answer":"بعد ذكر الأمة القائمة بالحق عاد السياق إلى المكذبين ليبين أن إمهالهم ليس نجاة، بل استدراج يعقبه الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–232، تحت عنوان «دلالة العطف في الآية الكريمة»","url":""}]},{"id":"s7-1333","number":1333,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما الصورة التي يرسمها فعل ﴿سنستدرجهم﴾؟","answer":"يصور نقلهم درجة بعد درجة إلى الهلاك، مع توالي النعم والإمهال حتى يزدادوا اغترارًا وهم لا يشعرون بالمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص233–234، تحت عنوان «سر التعبير بكلمة سنستدرجهم»","url":""}]},{"id":"s7-1334","number":1334,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما دلالة صيغة الاستفعال في ﴿سنستدرجهم﴾؟","answer":"تفيد المعالجة والتدرج؛ أي أخذهم شيئًا فشيئًا ودرجة بعد درجة، لا بالعقوبة الفجائية أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص233–234، تحت «سر التعبير بكلمة سنستدرجهم»","url":""}]},{"id":"s7-1335","number":1335,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما دلالة السين في ﴿سنستدرجهم﴾؟","answer":"تدل السين على الاستقبال؛ ويدخل الإملاء المعطوف على الاستدراج في هذا الحكم على وجه العطف الذي يذكره المصدر. وفي السياق وعيد للمكذبين بما يستقبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص237–238، تحت «معنى الواو في الآية»","url":""}]},{"id":"s7-1336","number":1336,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما سرّ التعبير بـ﴿من حيث لا يعلمون﴾؟","answer":"يأتيهم الاستدراج من جهة لا يدركونها؛ إذ يحسبون النعم والإمهال إكرامًا، وهي طريق خفي إلى أخذهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص234، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s7-1337","number":1337,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما دلالة نفي العلم في ﴿لا يعلمون﴾؟","answer":"نفي العلم أعمق من نفي الإحساس العابر؛ فهم لا يفهمون حقيقة ما يجري ولا عاقبته، وإن شاهدوا ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص234–235، تحت «يعلمون ويشعرون»","url":""}]},{"id":"s7-1338","number":1338,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما سر اختيار ﴿وأملي لهم﴾ في سياق الوعيد؟","answer":"الإملاء يدل على إطالة المدة، أما الإمهال فقد يكون طويلًا أو قصيرًا وفيه معنى الإبطاء برفق. فاختير الإملاء لتهديد من طال تماديهم في المعاصي واغتروا بتأخير العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص239–240، تحت «الإملاء والإمهال»","url":""}]},{"id":"s7-1339","number":1339,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما وجه عطف ﴿وأملي لهم﴾ على ﴿سنستدرجهم﴾؟","answer":"يذكر المصدر وجهين: أن يكون الإملاء معطوفًا داخلًا في الاستقبال الذي تدل عليه السين، أو معطوفًا خارجًا عن حكمها؛ لأن الإملاء إمهال وإطالة، بخلاف الاستدراج الذي يتتابع شيئًا فشيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص237–238، تحت «معنى الواو في الآية»","url":""}]},{"id":"s7-1340","number":1340,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما سرّ الانتقال من ﴿سنستدرجهم﴾ إلى ﴿وأملي﴾ بالإفراد؟","answer":"في الانتقال تنويع للخطاب وإيقاظ للسامع مع بقاء معنى التعظيم المفهوم من ﴿سنستدرجهم﴾. ويذكر المصدر أن الاستدراج قد يقع بواسطة وغيرها، أما تأخير الآجال وطول الإمهال فمن الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص238–239، تحت «بلاغة الالتفات من ضمير التكلم بالجمع إلى ضمير التكلم بالمفرد»","url":""}]},{"id":"s7-1341","number":1341,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما دلالة التوكيد في ﴿إن كيدي متين﴾؟","answer":"يؤكد أن الإمهال ليس عجزًا ولا إفلاتًا، وأن التدبير الذي ينتهي بأخذهم ثابت لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص239، تحت «بلاغة التذييل التعليلي التأكيدي في ختام الآية»","url":""}]},{"id":"s7-1342","number":1342,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما معنى كيدي في السياق؟","answer":"لأن ظاهر الإمهال وتوالي النعم إحسان، وعاقبته للمكذب المصر خذلان وأخذ من حيث لا يحتسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236، تحت عنوان «شرح المفردات: كيدي»","url":""}]},{"id":"s7-1640","number":1640,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما وجه البلاغة في التذييل التعليلي التأكيدي في ختام الآية؟","answer":"سمى هذا التدبير كيدًا، ووصفه بالمتانة لشدة إحكامه وعدم الإفلات منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص239، تحت عنوان «بلاغة التذييل التعليلي التأكيدي في ختام الآية»","url":""}]},{"id":"s7-1343","number":1343,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما دلالة وصف الكيد بـ﴿متين﴾؟","answer":"﴿متين﴾ أي شديد قوي محكم لا يُدفع ولا يُنقض؛ فناسب حتمية الأخذ بعد الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص237، تحت عنوان «شرح المفردات: متين»","url":""}]},{"id":"s7-1344","number":1344,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة التوبيخ في ﴿أولم يتفكروا﴾؟","answer":"ينكر عليهم ترك التفكر الذي يكشف بطلان دعوى الجنون، مع وضوح سيرة النبي بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص243، تحت «بلاغة الاستفهام في قوله أولم يتفكروا»","url":""}]},{"id":"s7-1345","number":1345,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما سرّ اختيار ﴿يتفكروا﴾ بدل «يعلموا»؟","answer":"المطلوب أن يعملوا النظر في سيرته ودعوته حتى يصلوا بأنفسهم إلى انتفاء الجنون، لا أن يتلقوا مجرد خبر بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص243–244، تحت عنوان «سر تعليق الفعل يتفكروا ودلالته في السياق»","url":""}]},{"id":"s7-1346","number":1346,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة وصف النبي ﷺ بأنه ﴿صاحبهم﴾؟","answer":"يذكرهم بطول صحبته ومخالطته لهم، فقد عرفوا عقله وصدقه قبل الرسالة؛ وذلك أقطع لدعوى الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص246، تحت «سر التعبير بالصحبة في قوله صاحبهم»","url":""}]},{"id":"s7-1347","number":1347,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة ﴿من﴾ في ﴿ما بصاحبهم من جنة﴾؟","answer":"زيدت بعد النفي لاستغراق الجنس؛ أي ليس به أدنى شيء من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص246–247، تحت «دلالة التأكيد بمن الداخلة على نكرة منفية»","url":""}]},{"id":"s7-1348","number":1348,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة التنكير في لفظ جنة؟","answer":"جاءت ﴿جنة﴾ نكرة في سياق النفي المؤكد بـ﴿من﴾، لنفي أي نوع أو قدر من الجنون عنه ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص247، تحت عنوان «دلالة التنكير في لفظ جنة»","url":""}]},{"id":"s7-1641","number":1641,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما معنى جنة في السياق؟","answer":"أصل مادة الجن الستر، والجنون ستر للعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص242، تحت عنوان «شرح المفردات: جنة»","url":""}]},{"id":"s7-1349","number":1349,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة القصر في ﴿إن هو إلا نذير مبين﴾؟","answer":"يقصر شأنه في هذا المقام على الرسالة والإنذار الواضح، وينفي عنه ما افتروه من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص247، تحت «بلاغة الختم بجملة القصر»","url":""}]},{"id":"s7-1350","number":1350,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما مناسبة وصفه ﷺ هنا بـ﴿نذير﴾؟","answer":"لأن المقام مواجهة المكذبين وتحديد مهمة الرسول في الإنذار والبلاغ، وفي لفظ النذير تنويه بشدة إنذاره ووضوحه وإظهار كمال رأفته بهم إذ ينذرهم بالعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص247–248، تحت عنوان «دلالة التنكير في وصف النبي المرسل بأنه نذير»","url":""}]},{"id":"s7-1351","number":1351,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة وصف النذير بـ﴿مبين﴾؟","answer":"هو بيّن الرسالة، مظهر لما ينذر به بعبارة واضحة تقوم بها الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص248، تحت «دلالة الصفة في لفظ مبين»","url":""}]},{"id":"s7-1352","number":1352,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما مناسبة الانتقال من ﴿أولم يتفكروا﴾ إلى ﴿أولم ينظروا﴾؟","answer":"دعاهم أولًا إلى التفكر في الرسول الذي يعرفونه، ثم وسع مجال النظر إلى ملكوت السماوات والأرض وسائر المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص252، تحت «دلالة الجملة على الترقي في الإنكار والتعجيب من حالهم»","url":""}]},{"id":"s7-1353","number":1353,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿ملكوت﴾ بدل «ملك»؟","answer":"صيغة ﴿ملكوت﴾ تفيد عظمة الملك وسعته وإحكام السلطان، فتدعو إلى تدبر دلائل القدرة في الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص253–254، تحت «إيثار استخدام الملكوت على الملك»","url":""}]},{"id":"s7-1354","number":1354,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿في﴾ في ﴿ينظروا في ملكوت السماوات والأرض﴾؟","answer":"تجعل الملكوت مجالًا يتعمق فيه النظر والتدبر، لا مجرد شيء يمر عليه البصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص253، تحت «دلالة التعبير بالفعل المضارع وتعديته بحرف الجر في»","url":""}]},{"id":"s7-1355","number":1355,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما سرّ الجمع بين ﴿ملكوت السماوات والأرض﴾ و﴿ما خلق الله من شيء﴾؟","answer":"جمع بين النظر في النظام الكوني العظيم والنظر في كل مخلوق مفرد؛ لتعم دلائل القدرة الكليات والجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص254، تحت عنوان «معنى العطف بالواو في قوله وما خلق»","url":""}]},{"id":"s7-1356","number":1356,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة الاسم الموصول ما؟","answer":"تؤكد ﴿من﴾ شمول النظر لكل ما يصدق عليه اسم الشيء من خلق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص255–256، تحت عنوان «دلالة الاسم الموصول ما»","url":""}]},{"id":"s7-1642","number":1642,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة التأكيد بمن الداخلة على النكرة؟","answer":"لا تختص الدلالة بعظائم السماوات والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص255–256، تحت عنوان «دلالة التأكيد بمن الداخلة على النكرة»","url":""}]},{"id":"s7-1357","number":1357,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما مناسبة عطف ﴿وأن عسى أن يكون قد اقترب أجلهم﴾؟","answer":"أضاف إلى حجة الكون باعثًا شخصيًا عاجلًا: قد يدنو موتهم فلا تبقى لهم مهلة للإيمان والتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص256–257، تحت «معنى العطف في قوله وأن عسى»","url":""}]},{"id":"s7-1358","number":1358,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة استخدام قد ودخولها على الماضي ومعناها بما بعدها؟","answer":"جاءت ﴿قد﴾ مع الماضي لإفادة التحقيق في مضمون هذا التوقع، حتى يستحضروا قرب الموت أمرًا جديًا يحملهم على المبادرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص257–258، تحت عنوان «دلالة استخدام قد ودخولها على الماضي ومعناها بما بعدها»","url":""}]},{"id":"s7-1643","number":1643,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة حذف اسم أن ودلالته؟","answer":"يدعو السياق إلى توقع قرب الأجل والاستعداد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص257–258، تحت عنوان «حذف اسم أن ودلالته»","url":""}]},{"id":"s7-1359","number":1359,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة الاستفهام في ﴿فبأي حديث بعده يؤمنون﴾؟","answer":"استفهام إنكاري يقرر أنه إذا لم يحملهم القرآن على الإيمان، فلا حديث بعده أحق أن يؤمنوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص259–260، تحت «دلالة الاستفهام بالأداة أي»","url":""}]},{"id":"s7-1360","number":1360,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما مرجع الضمير في ﴿بعده﴾؟","answer":"من وجوه عود الضمير القرآن، أي أي حديث أحق منه بالإيمان؟ ويذكر المصدر أيضًا عوده إلى الرسول بتقدير بعد خبره وقصته، أو إلى الأجل؛ فليس العود إلى القرآن الوجه الوحيد المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص260–261، تحت «مرجع الضمير في بعده ودلالته»","url":""}]},{"id":"s7-1361","number":1361,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما مناسبة قوله تعالى: ﴿من يضلل الله فلا هادي له﴾ بعد الدعوة إلى النظر؟","answer":"يبين أن من أعرض عن دلائل الهداية حتى خُذل لا تنفعه كثرة الآيات، ولا يستطيع أحد أن يهديه من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–265، تحت عنوان «موقع الجملة مما قبلها ودلالته في السياق»","url":""}]},{"id":"s7-1362","number":1362,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة ﴿لا﴾ النافية للجنس في ﴿فلا هادي له﴾؟","answer":"تنفي وجود أي هادٍ له نفيًا شاملًا، فتقرر انفراد الله بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص266–267، تحت «دلالة استخدام لا النافية للجنس في جواب الشرط»","url":""}]},{"id":"s7-1363","number":1363,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة إفراد ﴿هادي﴾؟","answer":"جاء نكرة في سياق النفي فيعم كل فرد من جنس الهداة؛ فلا يوجد له هادٍ واحد أيًا كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص266–267، تحت عنوان «معنى اللام في له من الآية الكريمة»","url":""}]},{"id":"s7-1364","number":1364,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما سرّ التعبير بـ﴿ويذرهم﴾ بدل «ويتركهم»؟","answer":"﴿يذرهم﴾ أدل على الإهمال والتخلية بعد الإعراض، وفيها وعيد بأنهم يُتركون لعاقبة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص269، تحت «يذرهم ويتركهم»","url":""}]},{"id":"s7-1365","number":1365,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما الصورة في قوله تعالى: ﴿في طغيانهم﴾؟","answer":"صُور الطغيان ظرفًا يحيط بهم ويستغرقهم؛ فهم مغمورون في مجاوزة الحد لا يخرجون منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص268، تحت «لطيفة الاستعارة في الحرف في»","url":""}]},{"id":"s7-1366","number":1366,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة إضافة الطغيان إليهم في ﴿طغيانهم﴾؟","answer":"تدل الإضافة على تمكّن الطغيان منهم واستمراره وملازمته لهم، حتى صار وصفًا معروفًا بهم في حياتهم وأحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص268، تحت «فائدة الإضافة في طغيانهم»","url":""}]},{"id":"s7-1367","number":1367,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة يعمهون ويعمون؟","answer":"العمه هو التحير والتردد مع عمى البصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص270، تحت عنوان «يعمهون ويعمون»","url":""}]},{"id":"s7-1644","number":1644,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما معنى يعمهون في السياق؟","answer":"هو يصور اضطرابهم داخل الطغيان، لا مجرد مفارقة الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264، تحت عنوان «شرح المفردات: يعمهون»","url":""}]},{"id":"s7-1368","number":1368,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة المضارع في ﴿يسألونك عن الساعة﴾؟","answer":"يصور تجدد سؤالهم وتكراره، سواء كان سؤال اختبار أو استهزاء أو استعلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص274–275، تحت «دلالة استخدام الفعل المضارع يسألونك»","url":""}]},{"id":"s7-1370","number":1370,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما الصورة في سؤالهم: ﴿أيان مرساها﴾؟","answer":"شُبهت الساعة بسفينة مضطربة لا يعلم الناس متى تستقر وترسو؛ فالسؤال عن وقت ثبوت وقوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص277، تحت «بلاغة الاستعارة في مرساها»","url":""}]},{"id":"s7-1371","number":1371,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما سر تقديم ﴿أيان﴾ وتأخير ﴿مرساها﴾ في سؤالهم عن الساعة؟","answer":"لأن ﴿أيان﴾ اسم استفهام عن الوقت له الصدارة، فقدم على المبتدأ ﴿مرساها﴾. والسؤال عن وقت وقوع الساعة، فجيء بالاستفهام الذي يحدد جهة سؤالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص277، تحت «علة تأخير المسند إليه مرساها»","url":""}]},{"id":"s7-1372","number":1372,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة القصر في ﴿إنما علمها عند ربي﴾؟","answer":"يقصر علم وقت الساعة على الله وحده، وينفيه عن الرسول وعن كل مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص278، تحت «فائدة الجواب بأسلوب القصر»","url":""}]},{"id":"s7-1373","number":1373,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة المغايرة في المقصور عليه عند ربي وعند الله؟","answer":"جاء ﴿عند الله﴾ في جواب السؤال المتوهم فيه الإحاطة بحقيقة الساعة وشدتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص286، تحت عنوان «دلالة المغايرة في المقصور عليه عند ربي وعند الله»","url":""}]},{"id":"s7-1645","number":1645,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة لطيفة التعريف باسم الرب مضافًا ربي؟","answer":"جاء ﴿عند ربي﴾ جوابًا عن وقت وقوعها، وفي إضافة الرب إلى الرسول إشارة إلى التربية والإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص279، تحت عنوان «لطيفة التعريف باسم الرب مضافًا ربي»","url":""}]},{"id":"s7-1374","number":1374,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما الصورة في قوله تعالى: ﴿لا يجليها لوقتها إلا هو﴾؟","answer":"شُبه خفاء الساعة بشيء مستور لا يكشفه ويظهره في موعده إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص280، تحت عنوان «وجه كمال الاتصال بين قوله لا يجليها لوقتها إلا هو وما قبله»","url":""}]},{"id":"s7-1375","number":1375,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة تقديم ﴿لوقتها﴾ في ﴿لا يجليها لوقتها إلا هو﴾؟","answer":"يبرز أن تجليها مرتبط بوقتها المقدر تحديدًا، ثم يقصر كشفها في ذلك الوقت على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص280، تحت «دلالة تقديم لوقتها على فاعل الفعل يجليها»","url":""}]},{"id":"s7-1376","number":1376,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما الغرض البلاغي من الاستعارة في قوله ثقلت؟","answer":"عظُم أمرها وخفي علمها على أهل السماوات والأرض، وثقل ما يصاحبها من أهوال وتبدل للنظام الكوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص281–282، تحت عنوان «غرض الاستعارة في قوله ثقلت»","url":""}]},{"id":"s7-1377","number":1377,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما سرّ الجمع بين السماوات والأرض في ثقل الساعة؟","answer":"يفيد عموم شأنها لجميع العالم العلوي والسفلي، وأن علم وقتها محجوب عن الخلق كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص281، تحت «دلالة التعبير بالقيد في السماوات والأرض»","url":""}]},{"id":"s7-1378","number":1378,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة القصر في ﴿لا تأتيكم إلا بغتة﴾؟","answer":"يقصر مجيئها على المباغتة؛ فلا تسبقها معرفة بوقتها تتيح الاستعداد عند حلوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص282، تحت «نكتة التعبير بأسلوب القصر»","url":""}]},{"id":"s7-1379","number":1379,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما سرّ تكرار ﴿يسألونك﴾ في الآية؟","answer":"الأول حكاية لسؤالهم عن وقت الساعة، والثاني يكشف هيئة سؤالهم كأنهم يظنون النبي بالغ الاستقصاء في علمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص282–283، تحت «كمال الاتصال بين قوله يسألونك كأنك حفي عنها وقوله يسألونك عن الساعة»","url":""}]},{"id":"s7-1380","number":1380,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما معنى ﴿حفي﴾ في ﴿كأنك حفي عنها﴾؟","answer":"من معاني ﴿حفي﴾ المبالغ في السؤال والاستقصاء حتى يصير عالمًا بما يسأل عنه، وكأنهم يتوهمون أنه أحاط بعلم الساعة. ويذكر المصدر وجوهًا أخرى، منها العالم بها والمحب لهم؛ فلا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص284–285، تحت «تنوع معنى حفي في هذا السياق وأثره في المعنى»","url":""}]},{"id":"s7-1381","number":1381,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما مناسبة ختم الآية بـ﴿ولكن أكثر الناس لا يعلمون﴾؟","answer":"أكثر الناس لا يعلمون أن وقت الساعة مما استأثر الله بعلمه، ولا يدركون حكمة إخفائه؛ لذلك يكررون السؤال عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص288، تحت «بلاغة الختم بقوله ﴿ولكن اكثر الناس لا يعلمون﴾»","url":""}]},{"id":"s7-1382","number":1382,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة نفي العلم عن أكثر الناس بعد قصر علم الساعة على الله؟","answer":"يقرر أن جهلهم ليس بموعدها وحده، بل بحقيقة اختصاص الله بعلمها وبالحكمة من إخفائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص287–288، تحت عنوان «بلاغة الختم بقوله ولكن أكثر الناس لا يعلمون»","url":""}]},{"id":"s7-1383","number":1383,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما علة فصل الآية عما قبلها؟","answer":"يرد توهم أن الرسالة تستلزم امتلاك الغيب أو التصرف المستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص293، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s7-1646","number":1646,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة تخصيص المقول بذكر حال الرسول؟","answer":"الرسول عبد لا يملك لنفسه شيئًا إلا بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص295، تحت عنوان «دلالة تخصيص المقول بذكر حال الرسول»","url":""}]},{"id":"s7-1384","number":1384,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما سرّ تقديم ﴿نفعًا﴾ على ﴿ضرًا﴾ في هذا الموضع؟","answer":"ناسب ترتيب السياق؛ فقد تقدم ذكر الهداية قبل الضلال، ثم جاء بعده الاستكثار من الخير قبل مس السوء، فجرى النفع والضر على هذا النسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص296، تحت عنوان «نكتة تقديم النفع على الضر»","url":""}]},{"id":"s7-1385","number":1385,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة الاستثناء ونوعه في قوله إلا ما شاء الله؟","answer":"ي مباشرة الأسباب فواقعة بما أقدر الله عليه وتحت مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص301، تحت عنوان «دلالة الاستثناء ونوعه في قوله إلا ما شاء الله»","url":""}]},{"id":"s7-1647","number":1647,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما سر ذكر ملك النفع والضر؟","answer":"المنفي هو الملك المستقل والقدرة الذاتية النافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص295، تحت عنوان «سر ذكر ملك النفع والضر»","url":""}]},{"id":"s7-1386","number":1386,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة الاستثناء في ﴿إلا ما شاء الله﴾؟","answer":"يثبت أن ما يحصل للنبي من نفع أو دفع ضر إنما يكون بما شاءه الله وأقدره عليه، لا بملك مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص300–301، تحت «دلالة الاستثناء ونوعه في قوله إلا ما شاء الله»","url":""}]},{"id":"s7-1387","number":1387,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة الشرط في ﴿ولو كنت أعلم الغيب لاستكثرت من الخير﴾؟","answer":"أقام برهانًا عمليًا على انتفاء علم الغيب المستقل: لو علم المستقبل لطلب وجوه الخير كلها قبل فواتها وتجنب السوء قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص301–302، تحت «فائدة التعبير بالجملة الشرطية ودلالتها»","url":""}]},{"id":"s7-1388","number":1388,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة ﴿استكثرت﴾ بدل «أخذت كثيرًا»؟","answer":"صيغة الاستفعال تدل على طلب الزيادة وتحصيل أكبر قدر ممكن من الخير، وهو الأليق بفرض العلم بالغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–292، تحت «شرح المفردات: لاستكثرت»","url":""}]},{"id":"s7-1389","number":1389,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة تعريف ﴿الخير﴾؟","answer":"يفيد جنس الخير واستيعاب وجوهه التي يمكن تحصيلها لو عُلم الغيب، لا خيرًا واحدًا محدودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص303، تحت «معنى أل في الخير ودلالتها»","url":""}]},{"id":"s7-1390","number":1390,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما سرّ التعبير بـ﴿وما مسني السوء﴾ بدل «ولدفعت الضر»؟","answer":"جعل عدم إصابة السوء نتيجة لازمة لعلم الغيب المفترض، وصوّر السلامة تامة حتى إن السوء لا يقع منه أدنى مس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص304–305، تحت «سر اصطفاء مس السوء بدل دفع المضار»","url":""}]},{"id":"s7-1391","number":1391,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة اختيار ﴿مسني﴾؟","answer":"المس أخف درجات الإصابة، فنفيه أبلغ في نفي كل ما فوقه من حلول السوء والضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص309، تحت عنوان «المس والإصابة»","url":""}]},{"id":"s7-1392","number":1392,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة القصر في ﴿إن أنا إلا نذير وبشير﴾؟","answer":"يقصر وظيفته في هذا المقام على تبليغ الإنذار والبشارة، وينفي ما توهموه من علم الغيب أو التصرف المستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص305–306، تحت «بلاغة أسلوب القصر بالاستثناء بعد النفي ونوعه»","url":""}]},{"id":"s7-1393","number":1393,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]},{"surah":11,"verses":[2]}],"verseLabel":"الأعراف: 188؛ هود: 2","question":"ما سر تقديم وصف الإنذار على البشارة في قوله: ﴿إن أنا إلا نذير وبشير﴾؟","answer":"لأن المقام خطاب للمكذبين، فالإنذار أعلق بحالهم وأسبق في إيقاظهم من عاقبة التكذيب، ثم جاءت البشارة للمؤمن الذي يثبت على إيمانه؛ كما أن سياق السورة يغلب عليه الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص307، تحت «فائدة تقديم الإنذار على البشارة»","url":""}]},{"id":"s7-1394","number":1394,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة تقييد الإنذار والبشارة بـ﴿لقوم يؤمنون﴾؟","answer":"الرسالة عامة، لكن المؤمنين هم الذين ينتفعون بالإنذار والبشارة ويصدقون بمقتضاهما؛ فالقيد للانتفاع لا لعموم البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص308–309، تحت «دلالة تخصيص المؤمنين بالبشارة والنذارة على غيرهم»","url":""}]},{"id":"s7-1395","number":1395,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة المضارع في ﴿قوم يؤمنون﴾؟","answer":"يفيد إمكان تجدد حدوث الإيمان، ترغيبًا للكافرين في إحداثه بدل الإصرار على الكفر. ويحتمل أن يراد به الحال والاستقبال معًا، فالوصف يشمل من آمن ومن يؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص308، تحت «فائدة التعبير بالمضارع في وصف القوم»","url":""}]},{"id":"s7-1396","number":1396,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]},{"surah":10,"verses":[49]}],"verseLabel":"الأعراف: 188؛ يونس: 49","question":"ما سرّ تقديم النفع على الضر في الأعراف، وتقديم الضر على النفع في يونس؟","answer":"في الأعراف سبق تقديم الهداية على الضلال، ولحق الآية تقديم الخير على السوء، فناسب ﴿نفعًا ولا ضرًا﴾. وفي يونس سبق تكرار ذكر الضر، فجرى قوله ﴿ضرًا ولا نفعًا﴾ على الأصل وعلى نسق سياق السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص297–298، تحت «توجيه المتشابه اللفظي في تقديم النفع على الضر وتأخيره»","url":""}]},{"id":"s7-1397","number":1397,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما مناسبة افتتاح الآية بقوله تعالى: ﴿هو الذي خلقكم﴾؟","answer":"لما سبق سؤالهم عن الساعة وإنكار بعضهم البعث، ذُكّروا ببدء خلق الإنسان؛ فمن قدر على الإنشاء أولًا قدر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s7-1398","number":1398,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿من نفس واحدة﴾؟","answer":"يقرر وحدة الأصل الإنساني؛ فالناس جميعًا متفرعون من آدم، وفي ذلك إظهار لقدرة الله ووحدة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص315–316، تحت «معنى من في قوله من نفس واحدة»","url":""}]},{"id":"s7-1399","number":1399,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة تنكير ﴿نفس﴾ ووصفها بـ﴿واحدة﴾؟","answer":"التنكير ثم الوصف يبرزان أن هذا الجنس البشري الكثير نشأ من نفس واحدة لا من أصول متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص316–317، تحت «نكتة تنكير النفس ووصفها بالواحدة بطريق الإدماج»","url":""}]},{"id":"s7-1400","number":1400,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿وجعل منها زوجها﴾ بدل «وخلق زوجًا آخر»؟","answer":"﴿منها﴾ تبين اتحاد الأصل والجنس، و﴿جعل﴾ يبرز تهيئتها لتكون زوجًا وسكنًا، لا مجرد إيجاد مخلوق آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص319، تحت عنوان «معنى من ودلالتها في منها»","url":""}]},{"id":"s7-1401","number":1401,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة إضافة الزوج إلى النفس في ﴿زوجها﴾؟","answer":"تفيد شدة الاختصاص والاقتران؛ فهي الزوج الملائم لهذه النفس، ومن جنسها، والمهيأ لسكونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص319، تحت «نكتة إضافة الزوج إلى النفس في زوجها»","url":""}]},{"id":"s7-1402","number":1402,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما الفرق بين ﴿ليسكن إليها﴾ و«ليسكن معها»؟","answer":"السكون إليها هو الميل والأنس والطمأنينة والركون، أما السكن معها فلا يتجاوز الدلالة على الاجتماع في مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص320–321، تحت «بلاغة الاستعارة في التعبير بالسكن عن الطمأنينة والأنس»","url":""}]},{"id":"s7-1403","number":1403,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ إسناد السكون إلى الرجل في ﴿ليسكن إليها﴾؟","answer":"عاد الضمير إلى ﴿نفس واحدة﴾ باعتبار المراد بها آدم، وذكر علة جعل الزوج؛ ولا ينفي ذلك سكون كل من الزوجين إلى الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص321–322، تحت «علة استخدام التذكير في الضمير المستكن في قوله ليسكن»","url":""}]},{"id":"s7-1404","number":1404,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما بلاغة الكناية في قوله تعالى: ﴿فلما تغشاها﴾؟","answer":"كنى عن اتصال الزوج بزوجته بلفظ الغشيان، وهو الستر والتغطية؛ صونًا للعبارة وتصويرًا لشدة القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص322–323، تحت «بلاغة الكناية بصيغة التفعل في قوله تغشاها»","url":""}]},{"id":"s7-1405","number":1405,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة ﴿لما﴾ في ﴿فلما تغشاها حملت حملًا خفيفًا﴾؟","answer":"هي ظرفية بمعنى حين متضمنة معنى الشرط، فتربط الحمل بالتغشي وتبين ترتيب طور الحمل على اتصال الزوجين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص322، تحت «معنى الفاء ودلالتها في فلما»","url":""}]},{"id":"s7-1406","number":1406,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة الجمع بين الفعل والمصدر في ﴿حملت حملًا﴾؟","answer":"يذكر المصدر وجهين: أن يكون ﴿حملًا﴾ مصدرًا، فيلاحظ فيه تصوير فعل الحمل وما يناسبه من الخفة، أو مفعولًا به بمعنى المحمول من النطفة والجنين قبل أن يكبر ويثقل. فلا يجزم بنفي المصدرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص323–324، تحت «نكتة التعبير بحملًا بعد حملت»","url":""}]},{"id":"s7-1407","number":1407,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة وصف الحمل أولًا بـ﴿خفيفًا﴾؟","answer":"يصور أول الحمل حين لا تجد المرأة ثقله ولا يشق عليها، تمهيدًا للمقابلة مع قوله: ﴿فلما أثقلت﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص324، تحت «غرض وصف الحمل بالخفة»","url":""}]},{"id":"s7-1408","number":1408,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة المرور في قوله تعالى: ﴿فمرت به﴾؟","answer":"أي استمرت بالحمل في شؤونها، تقوم وتقعد من غير أن يثقلها؛ فالمرور يصور مضي هذا الطور بسهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص324–325، تحت «بلاغة الاستعارة في قوله فمرت به»","url":""}]},{"id":"s7-1409","number":1409,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما نكتة الكناية في أثقلت؟","answer":"﴿أثقلت﴾ كناية عن كبر الجنين وثقل الحمل، والهمزة للصيرورة أو الدخول في زمان الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص326، تحت عنوان «نكتة الكناية في أثقلت»","url":""}]},{"id":"s7-1648","number":1648,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة الهمزة في أثقلت؟","answer":"أي صارت ذات حمل ثقيل أو دخلت طور ثقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص326، تحت عنوان «دلالة الهمزة في أثقلت»","url":""}]},{"id":"s7-1410","number":1410,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ الانتقال إلى التثنية في ﴿دعوا الله ربهما﴾؟","answer":"لأن ثقل الحمل وسلامة الولد يعنيان الأبوين معًا، فاشتركا في الخوف والدعاء بعد أن كان وصف الحمل خاصًا بالأم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص327، تحت «دلالة لفظ دعوا وعود الضمير فيها»","url":""}]},{"id":"s7-1411","number":1411,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة الجمع بين اسم الجلالة ووصف الربوبية في ﴿دعوا الله ربهما﴾؟","answer":"يستحضر اسم الله كمال قدرته على ما يسألانه، ويستحضر وصف الربوبية تربيته ورزقه وإحسانه إليهما؛ ففي الجمع إظهار الافتقار إليه في إتمام الحمل وصلاح المولود.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص327–328، تحت «فائدة الجمع بين وصف الألوهية والربوبية في دعوا الله ربهما»","url":""}]},{"id":"s7-1412","number":1412,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة تنكير ﴿صالحًا﴾ في ﴿لئن آتيتنا صالحًا﴾؟","answer":"حُذف الموصوف، أي ولدًا صالحًا، والتنكير يعم وجوه الصلاح: سلامة الخلق والعقل والفطرة والدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص329–330، تحت «غرض تنكير صالحًا وحذف الموصوف»","url":""}]},{"id":"s7-1413","number":1413,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة توكيد ﴿لنكونن من الشاكرين﴾؟","answer":"لام جواب القسم ونون التوكيد الثقيلة تدلان على شدة الرغبة في إجابة الدعاء وقوة التزامهما بالشكر إن رُزقا الولد الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص330، تحت «دلالة تتابع المؤكدات في ﴿لنكونن﴾»","url":""}]},{"id":"s7-1414","number":1414,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما سرّ إعادة ﴿صالحًا﴾ في قوله تعالى: ﴿فلما آتاهما صالحًا﴾؟","answer":"يثبت تمام إجابة الدعاء بعين المطلوب الذي سألاه؛ فقد آتاهما ولدًا مستوفيًا وصف الصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص331، تحت عنوان «معنى لما ودلالتها في قوله فلما آتاهما»","url":""}]},{"id":"s7-1415","number":1415,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"من المراد بقوله تعالى: ﴿جعلا له شركاء فيما آتاهما﴾؟","answer":"الآية تضرب مثلًا للوالدين من ذرية آدم اللذين يشركان بعد أن يسألا الله الولد؛ فلا يصح نسبة الشرك إلى آدم وحواء، وهو ما يؤيده انتقال السياق إلى جمع ﴿يشركون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص334، تحت عنوان «غرض تقديم شبه الجملة جعلا له شركاء»","url":""}]},{"id":"s7-1416","number":1416,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما سر تنكير شركاء وجمعها؟","answer":"الجمع يلائم عموم شرك المشركين وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص334–335، تحت عنوان «سر تنكير شركاء وجمعها»","url":""}]},{"id":"s7-1649","number":1649,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة توجيه القراءات المتواترة في شركاء ودلالاتها؟","answer":"كإشراكهم غير الله في التسمية أو العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص334–335، تحت عنوان «توجيه القراءات المتواترة في شركاء ودلالاتها»","url":""}]},{"id":"s7-1417","number":1417,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة قوله تعالى: ﴿فيما آتاهما﴾ بعد سبق ذكر العطاء؟","answer":"يعيد ربط الشرك بالنعمة نفسها؛ فموضع التوبيخ أنهم جعلوا لله شركاء في الولد الذي علموا أنه عطاء منه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص335–336، تحت «دلالة التعبير بالاسم الموصول ما دون من»","url":""}]},{"id":"s7-1418","number":1418,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما سرّ الانتقال من التثنية إلى الجمع في ﴿عما يشركون﴾؟","answer":"انتقل من مثال الأبوين إلى عموم المشركين الموجودين؛ فالجملة نتيجة تعم أصناف شركهم، وتدل على أن المراد ليس آدم وحواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص337–338، تحت «دلالة عود ضمير الجمع في يشركون»","url":""}]},{"id":"s7-1419","number":1419,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة الفاء في ﴿فتعالى الله﴾؟","answer":"تفيد أن تنزيه الله مترتب على ما فُصل من انفراده بالخلق والعطاء، وهي دلائل تبطل الشرك وتوجب التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص336–337، تحت «معنى الفاء في قوله فتعالى»","url":""}]},{"id":"s7-1420","number":1420,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة اختيار ﴿تعالى﴾ في تنزيه الله عن شركهم؟","answer":"يدل على علو الله وتنزهه وتقدسه عن أن يكون له شريك؛ وهو أبلغ من مجرد إعلان البراءة من فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص337، تحت «دلالة قوله فتعالى»","url":""}]},{"id":"s7-1421","number":1421,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما دلالة الاستفهام في ﴿أيشركون ما لا يخلق شيئًا﴾؟","answer":"استفهام إنكاري للتوبيخ والتعجيب من تسويتهم المخلوق العاجز بالخالق القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص344، تحت «بلاغة الاستفهام ودلالته في أيشركون»","url":""}]},{"id":"s7-1422","number":1422,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما سرّ التعبير عن الأصنام بـ﴿ما﴾؟","answer":"استُعملت ﴿ما﴾ لأنها لغير العاقل، وفي ذلك كشف لحقيقة الأصنام الجمادية وإبطال لما رفعها إليه عابدوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص345، تحت «معنى ما في ما لا يخلق»","url":""}]},{"id":"s7-1423","number":1423,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما دلالة ﴿شيئًا﴾ في ﴿لا يخلق شيئًا﴾؟","answer":"جاءت نكرة في سياق النفي فعمّت؛ أي لا تخلق شيئًا مهما صغر، فانتفى عنها أصل القدرة على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص346–347، تحت «نكتة تنكير شيئًا»","url":""}]},{"id":"s7-1424","number":1424,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما سرّ جمع ضمير الأصنام في ﴿وهم يُخلقون﴾ بعد التعبير عنها بـ﴿ما﴾؟","answer":"روعي في ﴿ما﴾ حقيقتها غير العاقلة، ثم روعي في ضمير الجمع ما نزله المشركون منزلة العقلاء حين عبدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص348، تحت «دلالة الإشارة إلى الأصنام بضمير العقلاء في وهم يخلقون»","url":""}]},{"id":"s7-1425","number":1425,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما دلالة بناء ﴿يُخلقون﴾ للمجهول؟","answer":"لأن المصنوع لا يكون صانعًا؛ فالمقام لإبراز كونها مخلوقة عاجزة، مع الاستغناء عن ذكر الفاعل لتعينه والعلم به. فالاهتمام منصب على وصفها الذي يبطل عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص347، تحت «نكتة بناء يخلقون لما لم يسم فاعله»","url":""}]},{"id":"s7-1426","number":1426,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما معنى الواو ودلالتها في وهم يخلقون؟","answer":"تقيم مقابلة قاطعة بين العجز عن خلق أي شيء والافتقار إلى من يخلقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص347، تحت عنوان «معنى الواو ودلالتها في وهم يخلقون»","url":""}]},{"id":"s7-1650","number":1650,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما وجه البلاغة في البديع من خلال المقابلات في الآيات؟","answer":"من كان مخلوقًا عاجزًا لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص360، تحت عنوان «بلاغة البديع من خلال المقابلات في الآيات»","url":""}]},{"id":"s7-1427","number":1427,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما الفرق بين ﴿ولا يستطيعون لهم نصرًا﴾ و«ولا ينصرونهم»؟","answer":"نفي الاستطاعة ينفي أصل القدرة على النصر قبل وقوعه، فهو أبلغ من نفي فعل النصر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص352، تحت «فائدة المجاز المرسل في التعبير عن العجز والاحتياج بنفي الاستطاعة»","url":""}]},{"id":"s7-1428","number":1428,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما دلالة تقديم ﴿لهم﴾ على ﴿نصرًا﴾؟","answer":"يقدم العابدين موضع العناية؛ فالأصنام لا تملك لهم خصوصًا أدنى نصر، مع أنهم اتخذوها طلبًا لذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص350، تحت «غرض تقديم شبه الجملة لهم»","url":""}]},{"id":"s7-1429","number":1429,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما دلالة تنكير ﴿نصرًا﴾؟","answer":"التنكير في سياق النفي يعم كل نوع وكل قدر من النصر؛ فلا يستطيعون نصرًا قليلًا ولا كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص350–351، تحت «نكتة تنكير نصرًا»","url":""}]},{"id":"s7-1430","number":1430,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما دلالة الانتقال إلى ﴿ولا أنفسهم ينصرون﴾؟","answer":"ترقٍ في بيان العجز: من لا يستطيع حماية نفسه من الكسر والإهانة أعجز عن حماية عابديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص351، تحت «دلالة الواو في ولا أنفسهم ينصرون»","url":""}]},{"id":"s7-1431","number":1431,"surah":7,"verses":[192,197],"references":[{"surah":7,"verses":[192,197]}],"verseLabel":"الأعراف: 192؛ الأعراف: 197","question":"ما دلالة تقديم ﴿أنفسهم﴾ في ﴿ولا أنفسهم ينصرون﴾؟","answer":"في الأعراف: 192: للتخصيص والعناية بأشد مواضع العجز: لا يملكون النصر حتى لأنفسهم، فضلًا عن غيرهم.\n\nفي الأعراف: 197: يبرز موضع العجز الأشد: لا يقدرون على دفع الأذى عن ذواتهم التي هي أولى بالنصر، فغيرهم أعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص351–352، تحت عنوان «نكتة تقديم المفعول به على الفعل»","url":""}]},{"id":"s7-1432","number":1432,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما دلالة الشرط في ﴿وإن تدعوهم إلى الهدى لا يتبعوكم﴾؟","answer":"يقرر عجز الأصنام في كل حال؛ فحتى لو دعاها عابدوها إلى طريق تهتدي إليه لم تسمع ولم تتبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص354، تحت «نكتة التعبير بالجملة الشرطية مع أن دعوتهم محققة»","url":""}]},{"id":"s7-1433","number":1433,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما دلالة الاستعارة في يتبعوكم؟","answer":"شبهت الطاعة بالاتباع الذي يتضمن الملازمة وعدم المفارقة، فنفي الاتباع نفي لاستجابتها وطاعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص355–356، تحت عنوان «بلاغة الاستعارة في يتبعوكم»","url":""}]},{"id":"s7-1651","number":1651,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما وجه البلاغة في توجيه القراءات المتواترة في يتبعوكم؟","answer":"يذكر المصدر في القراءة المخففة معنى اقتفاء الأثر، وفي المشددة معنى اتباع الهدى المدعوة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص355–356، تحت عنوان «بلاغة توجيه القراءات المتواترة في يتبعوكم»","url":""}]},{"id":"s7-1434","number":1434,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما دلالة ﴿سواء عليكم أدعوتموهم أم أنتم صامتون﴾؟","answer":"يستوي دعاؤهم الأصنام وسكوتهم عنها؛ لأنها لا تسمع ولا تستجيب في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص356–357، تحت عنوان «الموقع البياني لجملة سواء عليكم»","url":""}]},{"id":"s7-1435","number":1435,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما سرّ مجيء الطرف الأول فعلًا ﴿أدعوتموهم﴾ والثاني اسمًا ﴿أنتم صامتون﴾؟","answer":"الدعاء فعل متجدد قد يقع وقد يترك، أما الصمت فصُور حالة ثابتة؛ ومع اختلاف الصورتين فالنتيجة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص357، تحت عنوان «بلاغة العدول من الفعلية إلى الاسمية»","url":""}]},{"id":"s7-1436","number":1436,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما الفرق بين الصمت والسكوت، وما ملاءمة ﴿أم أنتم صامتون﴾؟","answer":"السكوت ترك الكلام مع القدرة عليه، أما الصمت فيطلق على الإمساك عن النطق مطلقًا وقد يكون مع عدم القدرة. فالصمت أعم، وتساوي الدعاء والصمت هنا يؤكد أن الأصنام لا تستجيب في أي حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص360، تحت «الصمت والسكوت»","url":""}]},{"id":"s7-1437","number":1437,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة تسمية ما يُدعى من دون الله ﴿عبادًا أمثالكم﴾؟","answer":"كل ما سوى الله مملوك مربوب خاضع له، فسماهم عبادًا لإسقاط دعوى ألوهيتهم، سواء كانوا أصنامًا أو من عُبد من العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص367، تحت عنوان «نكتة النكرة بقوله عباد أمثالكم»","url":""}]},{"id":"s7-1438","number":1438,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما المقصود بقوله تعالى: ﴿أمثالكم﴾؟","answer":"المماثلة في العبودية لله والافتقار إليه، لا في جميع الصفات؛ بل أنتم أكمل من الأصنام بما أوتيتم من حياة وإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص366–367، تحت «نكتة النكرة بقوله عباد أمثالكم»","url":""}]},{"id":"s7-1439","number":1439,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة الأمر في فادعوهم؟","answer":"الأول يتحدى العابدين أن يدعوا معبوداتهم، والثاني يعجز المعبودات عن الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص368، تحت عنوان «دلالة الأمر في فادعوهم»","url":""}]},{"id":"s7-1652","number":1652,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة الأمر في فليستجيبوا؟","answer":"الدعاء منهم ممكن، وإنما يظهر عجزها عن تحقيق مطلوبهم واستحالة استجابتها على النحو الذي يزعمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص370، تحت عنوان «دلالة الأمر في فليستجيبوا»","url":""}]},{"id":"s7-1440","number":1440,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة لام الأمر في ﴿فليستجيبوا﴾؟","answer":"هي للأمر التعجيزي التهكمي؛ إذ طُلب منها ما لا قدرة لها عليه ليظهر بطلان عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص369–370، تحت «معنى اللام في فليستجيبوا»","url":""}]},{"id":"s7-1441","number":1441,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة توجيه الأمر بصيغة الغائب في ﴿فليستجيبوا لكم﴾؟","answer":"أمر الغائب يدل على توجيه الطلب بواسطة مبلّغ، وفيه هنا تهكم بالأصنام وعابديها؛ فهي عاجزة عن الإجابة، بل عن تلقي الأمر وفهمه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص369، تحت «دلالة الأمر في فليستجيبوا»","url":""}]},{"id":"s7-1442","number":1442,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة الشرط في ﴿إن كنتم صادقين﴾؟","answer":"يعلق صدق دعواهم ألوهية المعبودات على استجابتها، وهي عاجزة عنها؛ فيثبت كذب الدعوى بطريق التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص370، تحت «معنى إن ودلالة التعبير بالشرطية والغرض منها»","url":""}]},{"id":"s7-1443","number":1443,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما مناسبة تفصيل الجوارح بعد التحدي العام؟","answer":"فصّل وجوه عجز الأصنام في الحركة والعمل والإبصار والسماع؛ لتقوم الحجة المحسوسة على أنها دون عابديها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص373، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s7-1444","number":1444,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة تكرار الاستفهام في تعداد الجوارح؟","answer":"يجعل كل جارحة موضع إنكار مستقل، ويقرر العجز وجهًا بعد وجه حتى لا يبقى لمعبوداتهم وصف كمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص374–375، تحت «فائدة توجيه الإنكار إلى كل واحدة من هذه الجوارح الأربعة»","url":""}]},{"id":"s7-1445","number":1445,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة ﴿أم﴾ بين أسئلة الجوارح؟","answer":"يذكر المصدر احتمال كونها منقطعة بمعنى بل والهمزة، فيتجدد الإنكار مع كل جارحة. ويحتمل اتصالها بعد همزة الاستفهام؛ فلا يصح حصرها في وجه الانقطاع وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص375، تحت «معنى أم في المواضع الثلاثة»","url":""}]},{"id":"s7-1446","number":1446,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ تقديم الأرجل على الأيدي؟","answer":"بدأ بآلة الانتقال التي توصل إلى المقصود، ثم آلة البطش والعمل به؛ فجرى الترتيب على تسلسل الحركة والفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376–377، تحت «بلاغة ترتيب الجوارح الأربعة»","url":""}]},{"id":"s7-1447","number":1447,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة قوله تعالى: ﴿أرجل يمشون بها﴾ مع أن للأصنام صور أرجل؟","answer":"العبرة بوظيفة الجارحة لا بصورتها؛ فلها أرجل مصورة لا تمشي بها، فظهرت مفارقة الاسم للحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص374–375، تحت عنوان «نكتة تنكير الأرجل والأيدي والأعين والآذان»","url":""}]},{"id":"s7-1448","number":1448,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة اختيار ﴿يبطشون﴾ للأيدي؟","answer":"البطش هو الأخذ والعمل بقوة، وهو أنسب بمقام التحدي والتهديد من مطلق العمل؛ فإذا عجزت عنه بطلت رهبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371، تحت عنوان «شرح المفردات: يبطشون»","url":""}]},{"id":"s7-1449","number":1449,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ تأخير الأعين والآذان عن الأرجل والأيدي؟","answer":"رتبت الجوارح بحسب غرض النصرة والنجدة: الأرجل للسعي، ثم الأيدي للبطش، ثم الأعين والآذان بوصفهما وسيلتين لذلك. فالتأخير يوافق دور الإدراك في تحصيل الفعل المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376–377، تحت «بلاغة ترتيب الجوارح الأربعة»","url":""}]},{"id":"s7-1450","number":1450,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما مناسبة تقديم الأعين على الآذان في هذا الموضع؟","answer":"جاء الترتيب بطريق الترقي في أسباب الضرر المخوف: المشي، ثم البطش، ثم البصر الذي قد يترتب عليه الضرر من بعيد، ثم السمع الذي يدرك به ما لم يصل إليه البصر. فهذا من وجوه الترتيب التي يذكرها المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376–377، تحت «بلاغة ترتيب الجوارح الأربعة»","url":""}]},{"id":"s7-1451","number":1451,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ استعمال ضمائر العقلاء في ﴿يمشون... يبطشون... يبصرون... يسمعون﴾؟","answer":"جرى الخطاب على زعم المشركين الذين نزّلوا الأصنام منزلة العقلاء، وفي ذلك تهكم؛ لأنها لا تؤدي شيئًا من أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376، تحت «سر وصف معبوداتهم بأوصاف العقلاء»","url":""}]},{"id":"s7-1452","number":1452,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما فائدة وصف الجوارح بأفعالها في ﴿يمشون بها﴾ و﴿يبطشون بها﴾ و﴿يبصرون بها﴾ و﴿يسمعون بها﴾؟","answer":"يسجل الوصف عجز الأصنام عما يحتاج إليه عابدوها؛ فصور الأرجل والأيدي والأعين والآذان لا تنفع ما دامت وظائفها منتفية. فالحجة تتعلق بالعمل الذي يراد من الجارحة، لا بمجرد شكلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص375، تحت «دلالات وصف الجوارح الأربعة»","url":""}]},{"id":"s7-1453","number":1453,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة الأمر في ﴿قل ادعوا شركاءكم﴾ بعد ثبوت عجزهم؟","answer":"أمر تعجيزي يبالغ في إظهار الثقة بالله: استنصروا بكل من تزعمونهم شركاء وحاولوا الكيد مجتمعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص377–378، تحت «دلالة توالي الأمرين في قل ادعوا»","url":""}]},{"id":"s7-1454","number":1454,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة إضافة الشركاء إليهم في ﴿شركاءكم﴾؟","answer":"نسبتهم إليهم تكشف أنهم شركاء في زعم المشركين وحدهم، لا شركاء لله في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص378–379، تحت «نكتة إضافة الشركاء إلى ضميرهم»","url":""}]},{"id":"s7-1455","number":1455,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة ﴿ثم﴾ في ﴿ثم كيدون﴾؟","answer":"تفيد التراخي الرتبي: بعد دعوة الشركاء والاستمداد بهم انتقلوا إلى ما هو أشد في زعمهم، وهو اجتماعهم على الكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص379، تحت «دلالة العطف بثم»","url":""}]},{"id":"s7-1456","number":1456,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ حذف ياء المتكلم في ﴿كيدون﴾؟","answer":"حذف الياء في قراءة من يحذفها يوافق تشابه الفواصل، مع دلالة الكسرة عليها. ويذكر المصدر قراءة إثبات الياء أيضًا؛ فالحذف وجه قراءة، وليس الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص379–380، تحت «التوجيه البلاغي للقراءات المتواترة في كيدون وتنظرون»","url":""}]},{"id":"s7-1457","number":1457,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة النهي في فلا تنظرون في قوله تعالى: ﴿فلا تنظرون﴾؟","answer":"أي لا تمهلوني لحظة، وهو غاية في التحدي وعدم المبالاة بهم وبشركائهم؛ لليقين بعجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص379، تحت «دلالة النهي في فلا تنظرون»","url":""}]},{"id":"s7-1458","number":1458,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما مناسبة تعليل التحدي بقوله تعالى: ﴿إن وليي الله﴾؟","answer":"لا يبالي بكيدهم لأن ناصره وحافظه هو الله؛ فمن كان في ولايته لم يضره تألب المعبودات العاجزة وعابديها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص383، تحت «علة فصل قوله إن وليي الله»","url":""}]},{"id":"s7-1459","number":1459,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة قوله تعالى: ﴿إن وليي الله﴾ بإضافة الولي وإظهار اسم الجلالة؟","answer":"إضافة ﴿ولي﴾ إلى ياء المتكلم تشرف النبي بخصوص الولاية، وإظهار اسم الله يصرح بمنفرد الولاية والنصر ويزيد الثقة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص386، تحت عنوان «بلاغة قصر الولاية الحقيقي على الله»","url":""}]},{"id":"s7-1460","number":1460,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما مناسبة وصف الله بـ﴿الولي﴾ بعد تحدي الشركاء؟","answer":"قابل أولياءهم المزعومين العاجزين بالولي الحق الذي يتولى الحفظ والنصر والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص391، تحت عنوان «الولي والنصير»","url":""}]},{"id":"s7-1461","number":1461,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما مناسبة وصف الله بقوله: ﴿الذي نزل الكتاب﴾ في مقام الحماية؟","answer":"من أنزل على رسوله الكتاب واصطفاه لتبليغه لا يتركه لكيد أعدائه، والكتاب نفسه ناطق بولايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص389، تحت عنوان «إيثار اسم الكتاب على القرآن»","url":""}]},{"id":"s7-1462","number":1462,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة التشديد في ﴿نزّل الكتاب﴾؟","answer":"من وجوه الصيغة الدلالة على التكثير والتدرج في التنزيل بما يواكب الأحوال، وفيه توكيد وبناء للعناية على امتداد الزمن. ويذكر المصدر أيضًا احتمال التقوية والتعظيم؛ فلا يحصر التشديد في التنجيم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص387–388، تحت «دلالة صيغة فعل في قوله نزل الكتاب»","url":""}]},{"id":"s7-1463","number":1463,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة تعريف ﴿الكتاب﴾؟","answer":"للعهد؛ أي القرآن المعروف المنزل على النبي، وفي التعريف تعظيم له بوصفه الكتاب الكامل الحاضر في مقام الاحتجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص388، تحت «دلالة أل في لفظ الكتاب»","url":""}]},{"id":"s7-1464","number":1464,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما سرّ الانتقال من ﴿وليي﴾ إلى ﴿وهو يتولى الصالحين﴾؟","answer":"عمم بعد الخصوص؛ فولاية الله ليست للنبي وحده، بل سنته أن ينصر عباده الصالحين ويحفظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص390، تحت «بلاغة التذييل في الآية»","url":""}]},{"id":"s7-1465","number":1465,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة المضارع في ﴿يتولى الصالحين﴾؟","answer":"يدل على تجدد ولايته واستمرارها؛ فهو يعين الصالحين وينصرهم في شؤونهم كلما تجددت حاجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص389–390، تحت «نكتة مجيء المسند جملة فعلية فعلها مضارع»","url":""}]},{"id":"s7-1466","number":1466,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة وصف أولياء الله بـ﴿الصالحين﴾؟","answer":"الصلاح سلامة الباطن بالإخلاص وظهور أثره في العمل النافع؛ وهو الوصف الذي يؤهل صاحبه للولاية والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382، تحت عنوان «شرح المفردات: الصالحين»","url":""}]},{"id":"s7-1467","number":1467,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما فائدة إعادة عجز المعبودات عن النصر بعد ذكره في الآية 192؟","answer":"أعيد بعد تقرير ولاية الله لتكتمل المقابلة: الله يتولى الصالحين، أما ما يدعونه فلا ينصر عابديه ولا نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص395، تحت عنوان «دلالة الواو في قوله والذين تدعون»","url":""}]},{"id":"s7-1468","number":1468,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما سرّ التعبير هنا بـ﴿من دونه﴾ وقبلها بـ﴿من دون الله﴾؟","answer":"يرجع الضمير إلى اسم الله المتقدم في تقرير ولايته ونصره للصالحين؛ فتأتي الإحالة إليه لتقابل نصرته بعجز ما يدعونه من دونه، وتنهي دعوى الولاية لتلك المعبودات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص397–398، تحت «فائدة إضافة كلمة دون إلى ضمير اسم الجلالة»","url":""}]},{"id":"s7-1469","number":1469,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما نكتة استعمال اسم الموصول الذين؟","answer":"يستحضر الموصول مع صلته المعبودات التي يدعونها ويجعلها موضوعًا للحكم بعجزها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص395–396، تحت عنوان «نكتة استعمال اسم الموصول الذين»","url":""}]},{"id":"s7-1653","number":1653,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما دلالة الاسم الموصول؟","answer":"ي اختيار ﴿الذين﴾ مجاراة لاعتقاد المشركين في أصنامهم وإنزالها منزلة العقلاء، تمهيدًا لإظهار بطلان اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص395–396، تحت عنوان «دلالة الاسم الموصول»","url":""}]},{"id":"s7-1470","number":1470,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما الفرق بين ﴿لا يستطيعون نصركم﴾ و﴿لا يستطيعون لهم نصرًا﴾ في الآية 192؟","answer":"الأولى واجهت العابدين مباشرة بعد تحديهم فناسب ﴿نصركم﴾، أما السابقة فكانت في حكاية حالهم بضمير الغيبة ونكّرت النصر لاستغراق أنواعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص399، تحت عنوان «نكتة إضافة نصر إلى ضمير المخاطبين»","url":""}]},{"id":"s7-1471","number":1471,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما سرّ تقديم عجزهم عن نصر العابدين على عجزهم عن نصر أنفسهم؟","answer":"بدأ بإبطال الغرض الذي عبدوهم لأجله، وهو طلب نصرهم، ثم ذكر الدليل الأقوى عليه: عجزهم عن نصر أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص399، تحت «دلالة عطف جملة ولا أنفسهم ينصرون على ما قبلها»","url":""}]},{"id":"s7-1473","number":1473,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما فائدة إعادة ﴿وإن تدعوهم إلى الهدى﴾ بعد الآية 193؟","answer":"في الموضع الأول بيان لعجزها عن النصرة والإرشاد يبطل عبادتها، وفي هذا الموضع بيان لعجزها حتى عن السماع، يبطل تخويف النبي بها بعد تحديه لهم؛ فتختلف جهة الحجة مع تقارب العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص407، تحت «سر المخالفة بين قوله لا يسمعوا وقوله قبل لا يتبعوكم»","url":""}]},{"id":"s7-1474","number":1474,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما سر المخالفة بين قوله لا يسمعوا وقوله قبل لا يتبعوكم؟","answer":"نفي السماع يثبت فقد أداة تلقي الدعوة، ونفي الاتباع يثبت فقد الاستجابة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص406–407، تحت عنوان «سر المخالفة بين قوله لا يسمعوا وقوله قبل لا يتبعوكم»","url":""}]},{"id":"s7-1654","number":1654,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما سر العدول عن عبارة لا يهتدوا؟","answer":"الثاني نتيجة ممتنعة لأن الأول غير موجود أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص406–407، تحت عنوان «سر العدول عن عبارة لا يهتدوا»","url":""}]},{"id":"s7-1475","number":1475,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما الصورة في قوله تعالى: ﴿وتراهم ينظرون إليك وهم لا يبصرون﴾؟","answer":"تبدو الأصنام بعيونها المصورة كأنها تنظر إلى الناظر، ثم تكشف الحال أنها لا تبصر شيئًا؛ فالمشهد يهدم خداع الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص411، تحت عنوان «دلالة الواو في قوله وهم لا يبصرون وأثرها في المعنى»","url":""}]},{"id":"s7-1476","number":1476,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما وجه إسناد النظر إلى الأصنام؟","answer":"أُسند إليها بحسب هيئة أعينها المقابلة للناظر، لا على الحقيقة؛ ولذلك أتبع بنفي الإبصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص408، تحت عنوان «دلالة التشبيه البليغ في الآية»","url":""}]},{"id":"s7-1477","number":1477,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما دلالة تعدية النظر بـ﴿إلى﴾؟","answer":"تفيد توجيه العين نحو المرئي، وهو القدر الظاهري الذي توهمه هيئة الأصنام، من غير تحقق الرؤية والإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص410–411، تحت «فائدة الجار والمجرور إليك ودلالته الإعرابية»","url":""}]},{"id":"s7-1478","number":1478,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما سرّ نفي الإبصار بعد إثبات النظر؟","answer":"النظر توجيه العين وقد يوجد بلا رؤية، أما الإبصار فهو حصول الإدراك؛ فأثبت هيئة النظر ونفى غايته وحقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص412، تحت عنوان «النظر والبصر»","url":""}]},{"id":"s7-1479","number":1479,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما دلالة مجيء ﴿وهم لا يبصرون﴾ جملة حالية؟","answer":"تكشف حالهم في اللحظة التي يوهم ظاهرها النظر: تراهم متجهين إليك، والحقيقة المقارنة لذلك أنهم لا يبصرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص411، تحت «دلالة الواو في قوله وهم لا يبصرون وأثرها في المعنى»","url":""}]},{"id":"s7-1480","number":1480,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما مناسبة افتتاح الوصايا الجامعة بـ﴿خذ العفو﴾؟","answer":"بدأ بإصلاح معاملة الداعي للناس: يقبل ما سهل من أخلاقهم ولا يستقصي حقوقه، فيتهيأ بعد ذلك للأمر بالخير واحتمال الجاهلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص418–419، تحت «الترقي في المعاني وبيان بعضها بعضًا من خلال الآية»","url":""}]},{"id":"s7-1481","number":1481,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما المراد بـ﴿العفو﴾ في قوله تعالى: ﴿خذ العفو﴾؟","answer":"هو ما سهل وتيسر من أخلاق الناس وأعمالهم من غير استقصاء، ويتضمن المسامحة وترك المؤاخذة؛ وهذه المعاني متقاربة وليست متعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415، تحت عنوان «شرح المفردات: العفو»","url":""}]},{"id":"s7-1482","number":1482,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة إيثار الفعل خذ على ما يرادفه؟","answer":"استعير الأخذ للقبول والرضا بما سهل من أخلاق الناس وأعمالهم، من غير تكليفهم ما يشق عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص419، تحت عنوان «إيثار الفعل خذ على ما يرادفه»","url":""}]},{"id":"s7-1655","number":1655,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة جمال الاستعارة المكنية في قوله خذ العفو؟","answer":"ي التعبير تصوير للعفو كأنه شيء محسوس يؤخذ ويجعل حظًا من معاملة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص421، تحت عنوان «جمال الاستعارة المكنية في قوله خذ العفو»","url":""}]},{"id":"s7-1483","number":1483,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة التعبير بـ﴿العرف﴾ بدل «المعروف»؟","answer":"يذكر المصدر أن ﴿العرف﴾ أخف لفظًا وأنسب بمقام الدعوة قبل الهجرة، حين كان المؤمنون في ضعف؛ ويشمل ما تتقبله النفوس من الخير ولا ترده الشريعة. أما «المعروف» فكثيرًا ما يرد مقترنًا بالنهي عن المنكر في مقام بيان التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص424–425، تحت «إيثار لفظ العرف دون المعروف»","url":""}]},{"id":"s7-1484","number":1484,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة تعريف ﴿العرف﴾؟","answer":"يستغرق جنس الخير المعروف الموافق للشرع والفطرة السليمة، لا خصلة واحدة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص425، تحت «دلالة أل في لفظ العرف»","url":""}]},{"id":"s7-1485","number":1485,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما سرّ ترتيب العفو ثم الأمر بالعرف ثم الإعراض عن الجاهلين؟","answer":"بدأ بتهذيب معاملة النفس، ثم انتقل إلى إصلاح الناس بالأمر بالخير، ثم بيّن ما يحفظ الداعي من سفه من لا يستجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص418–419، تحت «الترقي في المعاني وبيان بعضها بعضًا من خلال الآية»","url":""}]},{"id":"s7-1486","number":1486,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة الأمر بـ﴿وأعرض عن الجاهلين﴾ بدل مقابلتهم بالعقوبة؟","answer":"المطلوب ترك مجاراتهم في السفه وعدم الاشتغال بانتقام النفس، لا ترك بيان الحق ولا تعطيل العقوبة المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص426، تحت «إيثار الفعل وأعرض دون غيره»","url":""}]},{"id":"s7-1487","number":1487,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة وصف المؤذين بـ﴿الجاهلين﴾؟","answer":"سماهم بما يكشف منشأ سفههم؛ فالجهل هنا سوء التصرف ومجاوزة الحلم، ووصفهم به يهيئ للإعراض عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص416، تحت عنوان «شرح المفردات: الجاهلين»","url":""}]},{"id":"s7-1488","number":1488,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما سر اختيار جمع المذكر السالم ﴿الجاهلين﴾ دون «الجهلاء»؟","answer":"يربط المصدر الاختيار بمناسبة مقام الحلم والعفو والقلة في هذا السياق، وبانسجام اللفظ مع الفاصلة. فليس المقصود الحث على استقصاء مقابلة أهل الجهل أو تكثيرها، بل تجاوز سفههم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص427، تحت «سر العدول عن جمع التكسير إلى جمع المذكر السالم»","url":""}]},{"id":"s7-1489","number":1489,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما وجه جمع الآية مكارم الأخلاق في ألفاظ قليلة؟","answer":"جمعت بذل السماحة في ﴿خذ العفو﴾، وإيصال الخير في ﴿وأمر بالعرف﴾، وكف الشر في ﴿وأعرض عن الجاهلين﴾؛ فاستوعبت حسن الخلق فعلًا وتركًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص417–418، تحت عنوان «بلاغة الإيجاز بالقصر»","url":""}]},{"id":"s7-1490","number":1490,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما مناسبة قوله تعالى: ﴿وإما ينزغنك من الشيطان نزغ﴾ بعد الأمر بالإعراض عن الجاهلين؟","answer":"لما كان أذى الجاهلين قد يحرك الغضب ويدعو إلى مقابلتهم، نبه إلى أن هذا النزغ من الشيطان، وبيّن علاجه بالاستعاذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–432، تحت عنوان «دلالة الواو في قوله وإما ينزغنك وأثرها في المعنى»","url":""}]},{"id":"s7-1491","number":1491,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة دخول ﴿ما﴾ على ﴿إن﴾ في ﴿وإما﴾؟","answer":"﴿ما﴾ زائدة للتوكيد، ودخولها هيأ ﴿إن﴾ الشرطية لاتصال نون التوكيد بالفعل ﴿ينزغنك﴾، فقوّى التنبيه إلى احتمال النزغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص434، تحت عنوان «نكتة تأكيد الفعل بنون التوكيد في قوله وإما ينزغنك»","url":""}]},{"id":"s7-1492","number":1492,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة النزغ والمس والوسوسة؟","answer":"النزغ أدنى حركة من الشيطان وإثارة إلى الشر، وأكثر ما يكون عند الغضب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص441، تحت عنوان «النزغ والمس والوسوسة»","url":""}]},{"id":"s7-1656","number":1656,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما وجه البلاغة في استعمال النزغ دون المس؟","answer":"هو من درجات الوسوسة التي قد تهيج النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص433، تحت عنوان «بلاغة استعمال النزغ دون المس»","url":""}]},{"id":"s7-1493","number":1493,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما وجه البلاغة في إسناد النزغ إلى المصدر نزغ؟","answer":"المصدر فاعل للفعل، أي إن يصبك من الشيطان نزغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص435–436، تحت عنوان «بلاغة إسناد النزغ إلى المصدر نزغ»","url":""}]},{"id":"s7-1657","number":1657,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة لطيفة جناس الاشتقاق في قوله ينزغنك ونزغ؟","answer":"ي اشتقاق الفعل والفاعل من مادة واحدة تجنيس يركز معنى الحركة المفسدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص435–436، تحت عنوان «لطيفة جناس الاشتقاق في قوله ينزغنك ونزغ»","url":""}]},{"id":"s7-1494","number":1494,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة تقديم ﴿من الشيطان﴾ على ﴿نزغ﴾؟","answer":"يبادر بتعيين مصدر النزغ قبل تسميته، تنفيرًا منه وتنبيهًا إلى أن هذه الحركة المفسدة من الشيطان خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص435–436، تحت «فائدة قوله من الشيطان وتقديمه على الفاعل نزغ»","url":""}]},{"id":"s7-1495","number":1495,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما مناسبة جواب الشرط: ﴿فاستعذ بالله﴾؟","answer":"لأن الشيطان عدو خفي لا يدفع نزغه إلا الالتجاء إلى الله القادر عليه؛ فكانت الاستعاذة العلاج المباشر عند وقوع سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص436–437، تحت عنوان «فائدة الاستعاذة عند نزغ الشيطان»","url":""}]},{"id":"s7-1496","number":1496,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما سر اختيار ﴿فاستعذ﴾ بدل «فاستعن»؟","answer":"الاستعاذة أصرح في الالتجاء والاحتماء بالله، وفيها إظهار ضعف المستعيذ وافتقاره وانكساره وتعظيم ربه، والتبرؤ من الحول والقوة والالتجاء إلى غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص436–437، تحت «العدول عن فاستعن وإيثار الفعل فاستعذ»","url":""}]},{"id":"s7-1497","number":1497,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما سرّ إظهار اسم الله في ﴿فاستعذ بالله﴾؟","answer":"دفع الإضمار لبس عود الضمير إلى الشيطان، واستحضر اسم الجلالة الجامع لمعاني الكمال والمهابة في مقام الاحتماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص437–438، تحت «دلالة الباء في قوله بالله وفائدة التصريح باسم الجلالة»","url":""}]},{"id":"s7-1498","number":1498,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما مناسبة ختم الآية بـ﴿إنه سميع عليم﴾؟","answer":"تعليل للأمر بالاستعاذة: الله يسمع التجاء المستعيذ ويعلم نزغ الشيطان وحال من احتمى به، فيكفيه ويحميه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص438، تحت «بلاغة فصل جملة ﴿انه سميع عليم﴾ عما قبلها»","url":""}]},{"id":"s7-1499","number":1499,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما سرّ تقديم ﴿سميع﴾ على ﴿عليم﴾؟","answer":"لأن المقام مقام استعاذة ودعاء ملفوظ، فناسب تقديم سماع القول، ثم عمم بالعلم المحيط بالسر والحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص438–439، تحت عنوان «علاقة الفاصلة بسياق الآية»","url":""}]},{"id":"s7-1500","number":1500,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما مناسبة قوله تعالى: ﴿إن الذين اتقوا﴾ بعد أمر النبي ﷺ بالاستعاذة؟","answer":"عمم العلاج بعد توجيهه إلى النبي؛ فشأن المتقين جميعًا أنهم إذا مسهم الشيطان رجعوا إلى الله، والتقوى وقاية من تمكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص444–445، تحت «علة أسلوب الفصل في قوله إن الذين اتقوا»","url":""}]},{"id":"s7-1501","number":1501,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة ﴿مسهم﴾ بدل «أصابهم»؟","answer":"المس أخف الإصابة، فيدل على أن وسوسة الشيطان لا تتمكن من المتقين، بل تلامسهم عارضة ثم تزول بالتذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص447–448، تحت عنوان «الاستعارة في الفعل مسهم»","url":""}]},{"id":"s7-1502","number":1502,"surah":7,"verses":[200,201],"references":[{"surah":7,"verses":[200,201]}],"verseLabel":"الأعراف: 200–201","question":"ما الفرق بين ﴿نزغ من الشيطان﴾ و﴿طائف من الشيطان﴾؟","answer":"النزغ حركة مفسدة تهيج إلى الشر، والطائف خاطر أو وسوسة تطوف بالقلب ولا تستقر؛ فالأول يصور الدفع، والثاني سرعة المرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص449، تحت عنوان «إيثار استعمال لفظ طائف دون غيره»","url":""}]},{"id":"s7-1503","number":1503,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة تنكير ﴿طائف﴾؟","answer":"للتحقير والتقليل؛ فأدنى خاطر من الشيطان ينبه المتقين إلى التذكر، ولا يتمكن منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص448–449، تحت «إيثار استعمال لفظ طائف دون غيره»","url":""}]},{"id":"s7-1504","number":1504,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة التعبير عن تعرض المتقين للوسوسة بـ﴿مسهم طائف من الشيطان﴾؟","answer":"يصور المس إصابة غير متمكنة؛ فقد يعرض لهم خاطر من الشيطان، لكنهم لا يتركونه يستقر ويتحول إلى عمل. وإسناده إلى الطائف يصور مبادرته وسرعة مروره ومحاولته الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص447، تحت عنوان «سر استعمال الفعل مسهم دون غيره»","url":""}]},{"id":"s7-1505","number":1505,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما مناسبة جواب مس الشيطان بقوله تعالى: ﴿تذكروا﴾؟","answer":"لأن الغفلة منفذ الشيطان، فإذا تذكروا أمر الله ونهيه وثوابه وعقابه انكشف الخاطر وانقطع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص451–452، تحت «إيثار مجيء جواب الشرط تذكروا دون غيره»","url":""}]},{"id":"s7-1506","number":1506,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة حذف مفعول ﴿تذكروا﴾؟","answer":"لإفادة العموم؛ تذكروا ما يردعهم من أمر الله ومراقبته ووعده ووعيده، فلا يحصر التذكر في شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص452–453، تحت «بلاغة الإيجاز في حذف المفعول»","url":""}]},{"id":"s7-1507","number":1507,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة الفاء وأثرها في المعنى؟","answer":"تصور سرعة انكشاف وسوسة الشيطان عقب التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص453، تحت عنوان «دلالة الفاء وأثرها في المعنى»","url":""}]},{"id":"s7-1658","number":1658,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما نكتة استعمال إذا ومعناها؟","answer":"ما إن يتذكروا حتى تعود بصيرتهم فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص453، تحت عنوان «نكتة استعمال إذا ومعناها»","url":""}]},{"id":"s7-1508","number":1508,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة ﴿مبصرون﴾ بدل «يعلمون»؟","answer":"يصور الحق بعد التذكر كأنه مشهد واضح تراه البصيرة، لا مجرد معلومة ذهنية؛ فيميزون طريق الرشد من الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص454–455، تحت عنوان «دقة استعمال مبصرون دون غيره»","url":""}]},{"id":"s7-1509","number":1509,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة الجملة الاسمية في ﴿هم مبصرون﴾؟","answer":"تفيد تحقق الإبصار وثباته فيهم عقب التذكر، وجاء الضمير لزيادة تقرير حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص453–454، تحت عنوان «سر التعبير بالجملة الاسمية»","url":""}]},{"id":"s7-1510","number":1510,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة بيان عائد الضمير المتصل في قوله وإخوانهم؟","answer":"يعرض المصدر أوجهًا أخرى في عود الضمير، فلا ينحصر في هذا الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص464، تحت عنوان «بيان عائد الضمير المتصل في قوله وإخوانهم»","url":""}]},{"id":"s7-1511","number":1511,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما نكتة ذكر لفظ إخوان دون إخوة؟","answer":"الأخوة هنا أخوة الموالاة والموافقة في الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص460–461، تحت عنوان «نكتة ذكر لفظ إخوان دون إخوة»","url":""}]},{"id":"s7-1659","number":1659,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما فائدة إضافة إخوان إلى ضمير الغائبين؟","answer":"هي تصور قوة الصلة بين الشياطين ومن يستجيبون لإغوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص460–461، تحت عنوان «فائدة إضافة إخوان إلى ضمير الغائبين»","url":""}]},{"id":"s7-1512","number":1512,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما سر إيثار يمدونهم والعدول عن يغوونهم؟","answer":"المد يدل على الإطالة والزيادة والاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص461–462، تحت عنوان «سر إيثار يمدونهم والعدول عن يغوونهم»","url":""}]},{"id":"s7-1660","number":1660,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة إيثار الفعل يمدونهم دون مرادفاته؟","answer":"الشياطين لا تبدأ الغي فحسب، بل تزيد أولياءها فيه وتمده لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص461–462، تحت عنوان «إيثار الفعل يمدونهم دون مرادفاته»","url":""}]},{"id":"s7-1513","number":1513,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما الصورة في قوله تعالى: ﴿يمدونهم في الغي﴾؟","answer":"صُور الغي مكانًا عميقًا يتغلغلون فيه، والشياطين تطيل لهم حبل الضلال حتى يزدادوا بعدًا ولا يفلتوا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص464–465، تحت «فائدة الجار والمجرور في الغي»","url":""}]},{"id":"s7-1514","number":1514,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة ﴿ثم﴾ في ﴿ثم لا يقصرون﴾؟","answer":"تفيد التراخي الرتبي؛ فبعد إمدادهم في الغي يبلغ الأمر رتبة أشد، وهي استمرارهم فيه من غير كف ولا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص465، تحت «دلالة الحرف ثم في الآية»","url":""}]},{"id":"s7-1515","number":1515,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"إلى من يعود فاعل ﴿لا يقصرون﴾؟","answer":"يعود في المعنى الأول إلى الشياطين؛ فلا يكفون عن إمداد إخوانهم في الغي، ويحتمل الغاوين أيضًا؛ فلا يكفون عن قبول الإغواء والتمادي فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص466–467، تحت عنوان «سر استعمال الفعل لا يقصرون دون غيره»","url":""}]},{"id":"s7-1516","number":1516,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة المضارع المنفي في ﴿لا يقصرون﴾؟","answer":"يدل على تجدد عدم الكف واستمراره؛ فالإمداد بالغي والتمادي فيه ديدن متواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص466، تحت «دلالة استعمال صيغة المضارع»","url":""}]},{"id":"s7-1517","number":1517,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة إيثار لفظ آية في قوله وإذا لم تأتهم بآية؟","answer":"المراد آية يقترحونها أو وحي جديد يوافق أهواءهم، لا انتفاء آيات القرآن الموجودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474، تحت عنوان «إيثار لفظ آية في قوله وإذا لم تأتهم بآية»","url":""}]},{"id":"s7-1661","number":1661,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما وجه البلاغة في جملة الشرط وإذا لم تأتهم والمراد منها؟","answer":"قد كانوا يطلبون من الرسول اختراع الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص472، تحت عنوان «بلاغة جملة الشرط وإذا لم تأتهم والمراد منها»","url":""}]},{"id":"s7-1518","number":1518,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة استعمال ﴿إذا﴾ في ﴿وإذا لم تأتهم بآية﴾؟","answer":"لأن عدم مجيء الرسول بكل آية يقترحونها أمر متحقق متكرر، فناسبته ﴿إذا﴾ الدالة على تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص472، تحت «إيثار التعبير بإذا دون إن»","url":""}]},{"id":"s7-1519","number":1519,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة لولا وأثرها في المعنى؟","answer":"أي هلا اخترعتها أو اخترتها وجمعتها من عند نفسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474–475، تحت عنوان «دلالة لولا وأثرها في المعنى»","url":""}]},{"id":"s7-1662","number":1662,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة إيثار الفعل اجتبيتها ودلالته؟","answer":"هو قول يكشف توهمهم أن الرسول يملك إنشاء الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474–475، تحت عنوان «إيثار الفعل اجتبيتها ودلالته»","url":""}]},{"id":"s7-1520","number":1520,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة اختيار ﴿اجتبيتها﴾ بدل «أتيت بها»؟","answer":"الاجتباء يتضمن الاختيار والجمع والاصطفاء، فيصور باطل ظنهم أن النبي ينتقي الآية من عنده، لا أنه مجرد يأتي بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474، تحت عنوان «إيثار الفعل اجتبيتها ودلالته»","url":""}]},{"id":"s7-1521","number":1521,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة القصر في ﴿إنما أتبع ما يوحى إلي﴾؟","answer":"يقصر شأن الرسول على اتباع الوحي، وينفي أن يخترع آية أو يغيرها استجابة لاقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص476، تحت «بلاغة القصر بـ﴿انما﴾»","url":""}]},{"id":"s7-1522","number":1522,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة المضارع في ﴿أتبع﴾ و﴿يوحى﴾؟","answer":"يدل على تجدد نزول الوحي وتجدد اتباع الرسول له؛ فكلما أوحي إليه شيء بلغه واتّبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص476، تحت عنوان «سر التعبير بصيغة المضارع أتبع»","url":""}]},{"id":"s7-1523","number":1523,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"كيف يبين السياق مصدر الوحي بعد ﴿يوحى إلي﴾؟","answer":"جاء الفعل مبنيًا للمفعول، ثم صرح ﴿من ربي﴾ بأن الوحي من الله، فدفع توهم أن الرسول ينشئه من عند نفسه، وأكد أنه متلقٍ تابع لما ينزل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص477–478، تحت عنوان «فائدة قوله من ربي ومتعلقه»","url":""}]},{"id":"s7-1524","number":1524,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما فائدة قوله من ربي ومتعلقه؟","answer":"﴿إلي﴾ تثبت أن الرسول متلقٍ لا منشئ، و﴿من ربي﴾ تعين مصدر الوحي وتستحضر التربية والرعاية بالتنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص478، تحت عنوان «فائدة قوله من ربي ومتعلقه»","url":""}]},{"id":"s7-1525","number":1525,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة الإشارة إلى القرآن في ﴿هذا بصائر﴾؟","answer":"تشير إلى القرآن الحاضر المتلو، وتواجه اقتراحهم بآية أخرى بأن بين أيديهم آيات واضحة تكفي من طلب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص479–480، تحت عنوان «دلالة الإشارة في قوله هذا بصائر»","url":""}]},{"id":"s7-1526","number":1526,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما سرّ جمع ﴿بصائر﴾ مع الإشارة إلى القرآن المفرد؟","answer":"القرآن واحد، لكن آياته ودلائله المتعددة كل واحدة منها بصيرة تكشف وجهًا من الحق؛ فجمع آثار أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص480–481، تحت «سر جمع لفظ بصائر وإفراد لفظي هدى ورحمة»","url":""}]},{"id":"s7-1527","number":1527,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة تسمية القرآن ﴿بصائر﴾ بدل «أبصارًا»؟","answer":"البصائر نور القلب الذي يدرك به الحق، أما الأبصار فحاسة العين؛ والقرآن يكشف المعاني والهداية للبصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص480، تحت «إيثار التعبير بلفظ بصائر ودلالته»","url":""}]},{"id":"s7-1528","number":1528,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما سرّ الانتقال من ﴿من ربي﴾ إلى ﴿من ربكم﴾؟","answer":"الأول يبين مصدر ما يتلقاه الرسول، والثاني يواجه المخاطبين بأن القرآن عناية من ربهم هم، أقام بها حجتهم وهدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص481، تحت «نكتة تلوين الخطاب في قوله ربكم بعد قوله ربي»","url":""}]},{"id":"s7-1529","number":1529,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة الجمع بين ﴿بصائر وهدى ورحمة﴾؟","answer":"البصائر تكشف الحق، والهدى يقود إلى طريقه، والرحمة ثمرة اتباعه؛ فجمعت الآية البيان والدلالة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص481، تحت عنوان «دلالة عطف قوله وهدى ورحمة على قوله بصائر»","url":""}]},{"id":"s7-1530","number":1530,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة تقييد الهدى والرحمة بـ﴿لقوم يؤمنون﴾؟","answer":"القرآن بصائر للناس، لكن المؤمنين هم الذين يقبلون دلالته فيتحقق لهم الهدى والرحمة؛ فالقيد للانتفاع لا لعموم الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص482، تحت عنوان «سر اختصاص المؤمنين بالذكر في قوله لقوم يؤمنون»","url":""}]},{"id":"s7-1531","number":1531,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما دلالة بناء ﴿قُرئ القرآن﴾ للمجهول؟","answer":"يوجه البناء للمفعول الانتباه إلى القراءة نفسها وما يجب لها من الاستماع، من غير انشغال بشخص القارئ. فالمقام لتعظيم القرآن وتوجيه السامعين إلى تلقيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص490، تحت «سر مجيء الفعل الماضي المبني للمفعول»","url":""}]},{"id":"s7-1532","number":1532,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما سر التصريح بلفظ ﴿القرآن﴾ في ﴿وإذا قرئ القرآن﴾ بعد الحديث عنه؟","answer":"هو إظهار في مقام الإضمار ينوه بشأن القرآن، ويجعل الأمر بالاستماع إليه دالًا بنفسه لا يتوقف على استحضار مرجع ضمير؛ فيزداد الاهتمام بالكلام وبحق القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص490–491، تحت «نكتة وضع المظهر موضع المضمر في ذكر لفظ القرآن»","url":""}]},{"id":"s7-1533","number":1533,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما الفرق بين ﴿فاستمعوا له﴾ و﴿أنصتوا﴾؟","answer":"الاستماع قصد السمع وإقبال القلب على المقروء، والإنصات ترك الكلام والشاغل؛ فجمع بين فعل التلقي وإزالة ما يمنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص495، تحت عنوان «الاستماع والإنصات»","url":""}]},{"id":"s7-1534","number":1534,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما سرّ تقديم الاستماع على الإنصات؟","answer":"يراعي الترتيب مراتب تلقي القرآن: يبدأ المستمع بإلقاء السمع إلى ما يتلى، ثم يكمل ذلك بالإنصات والتفرغ للنظر والفهم والاهتداء. فالإنصات أعلى مراتب التلقي في هذا البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص492–493، تحت «سر تقديم الاستماع على الإنصات في قوله فاستمعوا له وأنصتوا»","url":""}]},{"id":"s7-1535","number":1535,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما سر الأمر بـ﴿فاستمعوا﴾ بدل الاكتفاء بطلب السماع؟","answer":"الاستماع إقبال مقصود وعقد للقلب على تلقي المقروء، أما السماع فقد يحصل من غير قصد. فالمطلوب الإصغاء الواعي الذي يقود إلى فهم القرآن والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص491–492، تحت «إيثار صيغة الأمر بالاستماع لا بالسماع»","url":""}]},{"id":"s7-1536","number":1536,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"كيف يؤكد الأمر بـ﴿وأنصتوا﴾ حسن تلقي القرآن؟","answer":"الإنصات استماع مع ترك الكلام، فيؤكد الإقبال على القرآن وترك ما يشغل عنه. ويذكر المصدر احتمال حمل الاستماع على الامتثال أيضًا، فيجمع الأمر بين حسن التلقي والاستجابة للهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص492، تحت «دلالة عطف قوله وأنصتوا على الجملة التي قبله»","url":""}]},{"id":"s7-1537","number":1537,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما دلالة عطف الإنصات بالواو؟","answer":"يدل على أن الاستماع والإنصات مطلوبان مجتمعين، من غير جعل أحدهما نتيجة زمنية لازمة للآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص492، تحت «دلالة عطف قوله وأنصتوا على الجملة التي قبله»","url":""}]},{"id":"s7-1538","number":1538,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما فائدة قوله لعلكم ترحمون؟","answer":"جعل الرحمة ثمرة مرجوة للاستماع والإنصات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص493–494، تحت عنوان «فائدة قوله لعلكم ترحمون»","url":""}]},{"id":"s7-1663","number":1663,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما دلالة إيثار ذكر الرحمة دون الفلاح أو غيره؟","answer":"لأنهما طريق فهم القرآن وقبول هدايته والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص493–494، تحت عنوان «إيثار ذكر الرحمة دون الفلاح أو غيره»","url":""}]},{"id":"s7-1539","number":1539,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما سر الأمر بالذكر دون غيره؟","answer":"بعد تلقي كلام الله أمر باستدامة الصلة به بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص498، تحت عنوان «سر الأمر بالذكر دون غيره»","url":""}]},{"id":"s7-1664","number":1664,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة الواو وتوجيه الخطاب في قوله واذكر ربك؟","answer":"الاستماع غذاء من الوحي، والذكر استجابة قلبية تحفظ أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496، تحت عنوان «دلالة الواو وتوجيه الخطاب في قوله واذكر ربك»","url":""}]},{"id":"s7-1540","number":1540,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة اختيار ﴿ربك﴾ في ﴿واذكر ربك﴾؟","answer":"يستحضر التربية والرعاية والإنعام، ويضيف الرب إلى النبي تشريفًا وتقريبًا يحفزه على دوام الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص498–499، تحت عنوان «فائدة إضافة رب إلى ضمير المخاطب في قوله واذكر ربك»","url":""}]},{"id":"s7-1541","number":1541,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما علة اختيار في الظرفية في قوله: ﴿في نفسك﴾؟","answer":"يدل على الذكر الخفي الحاضر في القلب، البعيد عن الرياء، مع استبطان عظمة المذكور ومراقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص499، تحت «علة اختيار في الظرفية في قوله: ﴿في نفسك﴾»","url":""}]},{"id":"s7-1542","number":1542,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما نكتة عطف قوله وخيفة على قوله تضرعًا؟","answer":"التضرع إظهار الذل والافتقار، والخيفة خوف القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص501، تحت عنوان «نكتة عطف قوله وخيفة على قوله تضرعًا»","url":""}]},{"id":"s7-1665","number":1665,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما معنى تضرعًا وخيفة في السياق؟","answer":"جمع بين هيئة العبودية الظاهرة وحالها الباطنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496، تحت عنوان «شرح المفردات: تضرعًا وخيفة»","url":""}]},{"id":"s7-1543","number":1543,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة ﴿خيفة﴾ في وصف الذكر؟","answer":"الخيفة حالة خوف تستحضر القلب وتناسب الخشوع في الذكر؛ ويبين المصدر أن هذا الانفعال قد يصاحبه خفض الصوت. فهي حال للذاكر، لا مجرد أداء ألفاظ الذكر بلا حضور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص501–502، تحت عنوان «نكتة عطف قوله وخيفة على قوله تضرعًا»","url":""}]},{"id":"s7-1544","number":1544,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما الفرق بين ﴿ودون الجهر من القول﴾ و«سرًا»؟","answer":"﴿دون الجهر﴾ يثبت قولًا مسموعًا منخفضًا بين الجهر والإسرار التام، فيجمع حضور اللسان وخشوع الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص502، تحت عنوان «فائدة قوله ودون الجهر»","url":""}]},{"id":"s7-1545","number":1545,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة تقييد الذكر بـ﴿بالغدو والآصال﴾؟","answer":"خُص أول النهار وآخره لأنهما طرفاه وأوقات تجدد الأحوال، وذكر الطرفين كناية عن ملازمة الذكر في اليوم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص503، تحت عنوان «المراد بقوله بالغدو والآصال»","url":""}]},{"id":"s7-1546","number":1546,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"كيف يعبر ﴿بالغدو والآصال﴾ عن ملازمة الذكر؟","answer":"الغدو وقت أول النهار، والآصال أوقات العشي، وهي جمع أصيل. وذكر الطرفين يحث على استدامة الذكر وتجديد الصلة بالله في أحوال اليوم، لا على حصره في هذين الوقتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص503، تحت عنوان «المراد بقوله بالغدو والآصال»","url":""}]},{"id":"s7-1547","number":1547,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما مناسبة النهي في ﴿ولا تكن من الغافلين﴾؟","answer":"لما أمر بدوام الذكر نهى عن ضده، وهو الغفلة التي تقطع الصلة بالله وتفتح مدخل الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص504، تحت عنوان «دلالة الواو في قوله ولا تكن من الغافلين»","url":""}]},{"id":"s7-1548","number":1548,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما الفرق بين ﴿ولا تكن من الغافلين﴾ و«ولا تكن غافلًا»؟","answer":"النهي عن الكون من الغافلين أبلغ من مجرد النهي عن الغفلة؛ إذ يحذر من اكتساب وصفهم والتخلق بطريقتهم، حتى لا يصير الذكر أمرًا عارضًا والغفلة حالًا ملازمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص505، تحت «فائدة دخول لا على تكن»","url":""}]},{"id":"s7-1549","number":1549,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما مناسبة ختم السورة بذكر ﴿الذين عند ربك﴾؟","answer":"جعل الملائكة المقربين قدوة في دوام العبادة بعد الأمر بالذكر والنهي عن الغفلة، وفيه حث على التشبه بأهل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص509–510، تحت «علة فصل قوله إن الذين عند ربك عما قبله»","url":""}]},{"id":"s7-1550","number":1550,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"من المراد بـ﴿الذين عند ربك﴾، وما دلالة العندية؟","answer":"المشهور أنهم الملائكة المقربون، والعندية عندية منزلة وزلفى ورحمة، لا قرب مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص510–511، تحت عنوان «دلالة الظرفية في قوله عند ربك»","url":""}]},{"id":"s7-1551","number":1551,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة اختيار ﴿ربك﴾ في وصف قرب الملائكة؟","answer":"يستحضر رعاية الله للنبي ويشرفه بالإضافة، ويحثه على الالتحاق في الذكر بمن قربتهم طاعتهم من رحمة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص511، تحت «فائدة إضافة الظرف إلى الرب وتخصيصه»","url":""}]}]);
